// AUTO-GENERATED — 1048 chunks
export const KB = [{"id": "gk_0", "t": "physics", "text": "[PHYSICS] Cannon-es uses gravity of 9.82 meters per second squared as the standard Earth gravity value. Context: Setting up a Cannon physics world with realistic gravity"}, {"id": "gk_1", "t": "physics", "text": "[PHYSICS] Cannon Box shape uses half-extents: a 1x1x1 Three.js BoxGeometry corresponds to a Cannon Box(0.5, 0.5, 0.5). Context: Creating physics collision shapes that match visual geometry sizes"}, {"id": "gk_2", "t": "physics", "text": "[PHYSICS] Cannon physics body for a dynamic object uses mass of 1 for standard interactive rigid bodies. Context: Creating a cube body with mass=1 so it responds to gravity and collisions"}, {"id": "gk_3", "t": "physics", "text": "[PHYSICS] Physics world step uses clock.getDelta() to advance simulation by the elapsed time each frame. Context: Synchronizing Cannon physics world updates with Three.js render loop using world.step(delta)"}, {"id": "gk_4", "t": "rendering", "text": "[RENDERING] Two engines run simultaneously: Cannon for physics simulation and Three.js for 3D rendering; each frame you copy Cannon body positions/quaternions to Three.js mesh positions/quaternions. Context: Pattern for syncing physics engine state to visual representation: cubeMesh.position.copy(cubeBody.position), cubeMesh.quaternion.copy(cubeBody.quaternion)"}, {"id": "gk_5", "t": "physics", "text": "[PHYSICS] cannon-es version 0.18 is the maintained fork of the original cannon.js physics library, installed via npm install cannon-es --save-dev. Context: cannon-es is a modern ES module fork of the unmaintained cannon.js, designed for use with Three.js"}, {"id": "gk_6", "t": "npc", "text": "[NPC] AI controller requires calling super::OnPossess(Pawn) as the first action in the OnPossess override to ensure downstream logic in the AI controller base class executes properly \u2014 skipping super calls causes weird behavior. Context: UE5 AI controller setup pattern: always call parent class OnPossess before custom logic to avoid broken behavior chains"}, {"id": "gk_7", "t": "npc", "text": "[NPC] AI controller uses OnPossess(APawn* Pawn) virtual void override to take control of a pawn, with a Cast to the specific NPC character class to validate the pawn type before executing AI logic. Context: Pattern: cast the possessed pawn to your NPC character base class and store as 'ControlledPawn' pointer (initialized to nullptr), only run AI logic if cast succeeds"}, {"id": "gk_8", "t": "npc", "text": "[NPC] NPC character class is derived from a base character class (TFCharacter), and the AI controller is a separate class that possesses and controls the NPC pawn \u2014 separation of character definition from AI behavior. Context: UE5 architecture pattern: NPCCharacter inherits from CharacterBase, AIControllerBase is a separate class that references the NPC via a private ControlledPawn pointer"}, {"id": "gk_9", "t": "npc", "text": "[NPC] NPC roaming requires a navigation mesh (nav mesh) that defines walkable areas \u2014 the nav mesh bounds volume covers the entire map including vertical space for multi-level navigation. Context: Unreal Engine 5 nav mesh bounds volume scaled to 15x15x15 to cover full map; same concept applies to any pathfinding system"}, {"id": "gk_10", "t": "npc", "text": "[NPC] Roaming AI pattern: separate AI Controller (brain) from AI Character (body) \u2014 controller issues movement commands, character executes them. Context: AI Controller class assigned to character via AI Controller Class property; controller contains event graph with movement logic"}, {"id": "gk_11", "t": "npc", "text": "[NPC] Simple roaming NPC behavior: on begin play trigger 'start roaming' custom event that picks a random navigable location from the nav mesh and moves the AI to it. Context: Random point selection constrained to nav mesh walkable area ensures NPC only targets reachable positions"}, {"id": "gk_12", "t": "npc", "text": "[NPC] Nav mesh bounds volume needs extra vertical height to cover stairs and multi-floor areas \u2014 expand Z-axis beyond ground level. Context: Without sufficient height, AI cannot pathfind to upper floors or elevated areas"}, {"id": "gk_13", "t": "npc", "text": "[NPC] Dialogue system uses a Queue (FIFO - first in first out) data structure to manage sentences, loading all sentences into the queue when dialogue starts and dequeuing them as the player reads through. Context: Unity C# dialogue system architecture using System.Collections queue of strings rather than arrays for sequential sentence display"}, {"id": "gk_14", "t": "npc", "text": "[NPC] Dialogue data is stored in a separate non-MonoBehaviour class containing a public string array for sentences and a public string for NPC name, passed into a DialogueManager to start conversations. Context: Separation of dialogue data (Dialogue class) from dialogue logic (DialogueManager) allows reusable dialogue objects that show up in the Unity inspector"}, {"id": "gk_15", "t": "npc", "text": "[NPC] Dialogue UI consists of a dialog box image, two text objects (NPC name + dialogue text), and a continue button, built with standard Unity UI tools. Context: Minimal UI setup for an NPC dialogue system with a separate trigger button for testing"}, {"id": "gk_16", "t": "physics", "text": "[PHYSICS] Gravity set to -9.82 in the Y direction for realistic physics simulation. Context: Cannon.js world initialization for vehicle physics"}, {"id": "gk_17", "t": "physics", "text": "[PHYSICS] Ground body uses type 'static' with geometric plane shape, rotated 90 degrees to be horizontal. Context: Cannon.js ground plane setup - without rotation the plane defaults to vertical"}, {"id": "gk_18", "t": "vehicles", "text": "[VEHICLES] Car body mass set to 5, positioned at (0, 6, 0) to spawn above ground. Context: Cannon.js rigid vehicle body setup - 6 units above ground so it falls into place"}, {"id": "gk_19", "t": "vehicles", "text": "[VEHICLES] Cannon.js RigidVehicle class handles vehicle creation including hinge constraints for wheel steering. Context: Built-in class that manages wheel attachment, constraints, and turning behavior automatically"}, {"id": "gk_20", "t": "vehicles", "text": "[VEHICLES] Wheels use sphere shape with angular dampening, offset downward to avoid intersection with car body. Context: Cannon.js vehicle wheel setup - each wheel is a separate body added via vehicle.addWheel()"}, {"id": "gk_21", "t": "rendering", "text": "[RENDERING] Cannon.js debugger creates green wireframe overlay on physics objects for visualization. Context: Debug tool that takes Three.js scene and physics world as inputs, updated each frame"}, {"id": "gk_22", "t": "physics", "text": "[PHYSICS] Animation loop updates both Cannon debugger and physics world each frame for sync. Context: Three.js + Cannon.js integration pattern - physics world must be stepped in the render loop"}, {"id": "gk_23", "t": "rendering", "text": "[RENDERING] WebGL renders graphics at target 60fps using GPU-accelerated matrix multiplication/linear algebra. Context: Smooth rendering requires distributing calculations to GPU since CPU alone cannot handle the volume of linear algebra operations needed"}, {"id": "gk_24", "t": "rendering", "text": "[RENDERING] 3D rendering pipeline: vertices (x,y,z points) -> primitives (triangles) -> lighting/shadows -> rasterization (3D to 2D pixel projection). Context: Core WebGL/OpenGL rendering pipeline stages for converting 3D geometry to 2D screen output"}, {"id": "gk_25", "t": "rendering", "text": "[RENDERING] Shaders are GPU functions that customize the rendering pipeline - vertex shaders process vertex data, fragment shaders calculate per-pixel color. Context: Written in OpenGL ES Shading Language (GLSL), shaders take vertex or fragment info and use GPU to calculate pixel render data"}, {"id": "gk_26", "t": "rendering", "text": "[RENDERING] WebGL is based on OpenGL (established 1992) and runs inside HTML canvas element without external plugins. Context: Access via canvas.getContext('webgl') in JavaScript; provides hardware-accelerated GPU graphics in browser"}, {"id": "gk_27", "t": "rendering", "text": "[RENDERING] Three.js abstracts WebGL shader writing - allows 3D graphics without hand-writing GLSL shaders. Context: Libraries like Three.js and tools like Spline provide higher-level APIs over raw WebGL"}, {"id": "gk_28", "t": "city", "text": "[CITY] Forest vegetation requires models of different heights to simulate different layers of the forest canopy. Context: Unity terrain vegetation placement technique for realistic forests"}, {"id": "gk_29", "t": "city", "text": "[CITY] For terrain vegetation, 5000-10000 tree models are used to cover a terrain surface. Context: Unity terrain tree density - author needed 10000 but demonstrated with 5000 models placed automatically"}, {"id": "gk_30", "t": "rendering", "text": "[RENDERING] Terrain texture layers stack with higher layers covering lower layers, each layer supports modifiers like height (max height, max falloff) and slope for placement control. Context: Procedural Terrain Painter tool in Unity uses layered textures with modifiers to auto-paint based on terrain properties"}, {"id": "gk_31", "t": "rendering", "text": "[RENDERING] Rock textures should be placed using a slope modifier to automatically appear on steep terrain slopes. Context: Procedural terrain painting technique - slope-based texture assignment for realistic rock placement"}, {"id": "gk_32", "t": "rendering", "text": "[RENDERING] Terrain grass uses 4 grass models mixed automatically via spine details tool with target density controlling frequency of each model. Context: Unity Terrain Tools package provides spine details for automatic grass placement with density-controlled mixing of multiple grass types"}, {"id": "gk_33", "t": "rendering", "text": "[RENDERING] Stamp-based terrain sculpting uses adjustable brush size and stamp height with 'stamp from current height' set to 1 for additive stamping. Context: Stamp It free package for Unity terrain - stamps predefined height profiles onto terrain for quick landscape creation"}, {"id": "gk_34", "t": "rendering", "text": "[RENDERING] Increasing splat map resolution and map resolution improves terrain texture detail quality. Context: Procedural Terrain Painter setup step - resolution settings affect texture painting fidelity on terrain"}, {"id": "gk_35", "t": "npc", "text": "[NPC] NPC crowd systems use Zone Graphs with Zone Shapes to define walkable areas, with lane profiles containing forward and backward lanes. Context: Unreal Engine 5.5 City Sample Crowds uses Zone Graph system where Zone Shapes define areas NPCs can walk, with lane profiles specifying directional lanes (forward/backward) for pedestrian flow"}, {"id": "gk_36", "t": "npc", "text": "[NPC] NPC crowd agents require MassAgent component with entity config containing: agent capsule collision sync, agent movement (mass-to-actor), and agent orientation align (mass-to-actor). Context: Mass Entity system in UE5.5 requires specific component configuration for crowd NPCs - capsule collision uses actor-to-mass transform, while movement and orientation use mass-to-actor transforms"}, {"id": "gk_37", "t": "npc", "text": "[NPC] Crowd NPC lane profile width set to 100 units for pedestrian paths. Context: Zone Graph lane profiles for pedestrian crowds use 100 unit width, controlling the walkable corridor size for NPC pathfinding"}, {"id": "gk_38", "t": "npc", "text": "[NPC] Crowd NPCs use 2 lanes per path - one forward, one backward - for bidirectional pedestrian flow. Context: Lane profiles define 2 directional lanes allowing NPCs to walk in both directions along a path, simulating realistic sidewalk behavior"}, {"id": "gk_39", "t": "npc", "text": "[NPC] Mass Entity crowd system uses MassCrowd plugin (MCrow) for large-scale NPC simulation. Context: UE5.5 uses the Mass Entity framework with a dedicated crowd plugin to handle large numbers of NPCs efficiently, separate from traditional AI controllers"}, {"id": "gk_40", "t": "npc", "text": "[NPC] Crowd NPC characters need capsule collider positioning - mesh placed inside capsule with correct orientation. Context: When setting up crowd characters, the skeletal mesh must be positioned within the capsule component with correct facing direction for proper collision and movement"}, {"id": "gk_41", "t": "npc", "text": "[NPC] Simple crowd NPCs can use a single looping forward walk animation as their base animation blueprint. Context: For basic crowd simulation, a single looping walk animation connected to the output pose is sufficient - complex state machines not required for background NPCs"}, {"id": "gk_42", "t": "rendering", "text": "[RENDERING] Terrain brush size of ~400 for coarse/large terrain features, ~200 for smaller detail passes. Context: Unity terrain height painting workflow using noise brush at different scales"}, {"id": "gk_43", "t": "rendering", "text": "[RENDERING] Grass detail distance set to 250 units to make grass visible from further away. Context: Unity terrain detail rendering - default detail distance is too low, needs to be increased for grass to be visible at distance"}, {"id": "gk_44", "t": "rendering", "text": "[RENDERING] Fog density of 0.0045 provides good distance obscuring while looking natural. Context: Fog hides grass/detail pop-in at distance and blends terrain into skybox"}, {"id": "gk_45", "t": "rendering", "text": "[RENDERING] Fog color sampled from low horizon of skybox creates cohesive sky-to-ground fade. Context: Color sampling trick: match fog color to skybox horizon color so fog blends seamlessly with sky"}, {"id": "gk_46", "t": "rendering", "text": "[RENDERING] Grass healthy color sampled from lighter parts of base terrain texture, dry color from darker parts. Context: Eyedropper sampling trick to keep grass colors cohesive with ground texture"}, {"id": "gk_47", "t": "rendering", "text": "[RENDERING] Mass place 15000 trees on terrain for dense forest coverage. Context: Unity Mass Place Trees feature for rapid tree population across entire terrain"}, {"id": "gk_48", "t": "rendering", "text": "[RENDERING] Fog used to hide LOD pop-in and grass detail distance cutoff. Context: Fog serves dual purpose: atmosphere and hiding rendering limitations where detail stops rendering"}, {"id": "gk_49", "t": "npc", "text": "[NPC] AI NPC conversation system requires ~28GB download for local inference, suggesting large language model running client-side. Context: Replica demo uses local AI models for real-time NPC conversation, not cloud-based"}, {"id": "gk_50", "t": "npc", "text": "[NPC] AI NPC voice response latency is variable and noticeable \u2014 sometimes 1-3 seconds delay between player speech and NPC reply. Context: Real-time speech-to-speech NPC interaction has perceptible lag that breaks immersion at times"}, {"id": "gk_51", "t": "npc", "text": "[NPC] AI NPCs maintain consistent personality traits across a conversation \u2014 a hostile NPC stays hostile, a dismissive one stays dismissive. Context: NPCs assigned personality/mood profiles that persist through multiple dialogue exchanges"}, {"id": "gk_52", "t": "npc", "text": "[NPC] AI NPCs can contextually respond to environment \u2014 acknowledging heat, traffic, city crowding \u2014 without scripted triggers. Context: NPCs reference world state like weather and traffic organically in free-form conversation"}, {"id": "gk_53", "t": "city", "text": "[CITY] Demo city has sidewalks wide enough for 2+ NPCs side by side, vehicle traffic on roads, and stairway geometry on sidewalks. Context: Urban layout includes pedestrian sidewalks, vehicle lanes, and vertical geometry transitions typical of city blocks"}, {"id": "gk_54", "t": "npc", "text": "[NPC] NPCs walk along sidewalks autonomously while holding props (coffee cup) and can be approached mid-walk for conversation. Context: Ambient NPC behavior includes pathfinding along sidewalks with contextual prop items, interruptible by player proximity"}, {"id": "gk_55", "t": "rendering", "text": "[RENDERING] Demo world has visible boundary walls ('Matrix wall') \u2014 hard invisible collision bounds at world edge. Context: Bounded demo area uses collision walls at map edges rather than infinite terrain"}, {"id": "gk_56", "t": "vehicles", "text": "[VEHICLES] Car can control angular velocity while in the air to perform flip tricks. Context: Canon.js physics engine allows modifying angular velocity of car body when airborne, enabling mid-air rotation control"}, {"id": "gk_57", "t": "rendering", "text": "[RENDERING] React Three Fiber project with cannon.js physics is 4-5 files total for a complete race track with colliders. Context: Minimal file count for a physics-based car game: trees and signs as colliders, ramp for air physics, third-person camera"}, {"id": "gk_58", "t": "rendering", "text": "[RENDERING] Use Suspense component to wrap 3D asset loading in React Three Fiber. Context: React Suspense block handles async loading of 3D models and textures while scene initializes"}, {"id": "gk_59", "t": "rendering", "text": "[RENDERING] Environment component creates 3D background from an environment map texture file. Context: Three.js scene setup using @react-three/drei Environment component with downloaded HDR/texture map"}, {"id": "gk_60", "t": "rendering", "text": "[RENDERING] OrbitControls component enables mouse-controlled camera with a Target property defining look-at point. Context: Camera control setup: perspective camera with configurable position, orbit controls with target point in 3D space"}, {"id": "gk_61", "t": "vehicles", "text": "[VEHICLES] Cannon.js used as physics engine for car racing with colliders on trees, signs, and ramps. Context: Scene elements (trees, signs) act as static colliders; ramp propels car into air for trick physics"}, {"id": "gk_62", "t": "rendering", "text": "[RENDERING] All Three.js/R3F hooks must be used inside the Canvas component \u2014 scene logic goes in child components. Context: React Three Fiber architecture requirement: Canvas wraps all 3D content, separate Scene component holds game logic"}, {"id": "gk_63", "t": "physics", "text": "[PHYSICS] cannon-es (fork of cannon.js) uses a World object equivalent to Three.js's Scene \u2014 two engines run simultaneously: cannon for physics simulation and Three.js for 3D rendering. Context: Setting up physics simulation alongside Three.js renderer requires creating parallel representations of objects in both engines"}, {"id": "gk_64", "t": "physics", "text": "[PHYSICS] Gravity is set via new CANNON.World() with gravity value 9.82 m/s\u00b2 (Earth gravity), and the world is stepped each frame using world.step(delta) where delta comes from a Three.js Clock. Context: The physics world must be updated every animation frame using the time delta to calculate object movement"}, {"id": "gk_65", "t": "physics", "text": "[PHYSICS] CANNON.Box uses half-extents: a Three.js BoxGeometry(1,1,1) maps to new CANNON.Box(0.5, 0.5, 0.5), and the body is created with mass:1 then added to the world via world.addBody(). Context: Physics shapes must match visual geometry dimensions but use half-extents convention for box colliders"}, {"id": "gk_66", "t": "physics", "text": "[PHYSICS] Each frame, sync physics to visuals by copying: cubeMesh.position.set(cubeBody.position.x, cubeBody.position.y, cubeBody.position.z) and cubeMesh.quaternion.copy(cubeBody.quaternion). Context: The cannon body position and rotation must be manually copied to the Three.js mesh every frame to keep visual and physics representations in sync"}, {"id": "gk_67", "t": "physics", "text": "[PHYSICS] Without a ground plane body in the physics world, rigid bodies with gravity will fall infinitely \u2014 a floor mesh visible in Three.js does not automatically create a physics collider. Context: The transcript demonstrates that objects fall through the visible floor because the physics world has no corresponding body for the ground plane"}, {"id": "gk_68", "t": "physics", "text": "[PHYSICS] cannon-es is installed via 'npm install cannon-es --save-dev' (version 0.18.x) and is a maintained fork of the original abandoned cannon.js library. Context: The original cannon.js is no longer maintained; cannon-es is the recommended replacement for rigid body physics simulation"}, {"id": "gk_69", "t": "npc", "text": "[NPC] AI Controller constructor requires FObjectInitializer as a const reference parameter, matching the base AAIController constructor signature. Context: Setting up a custom AI controller class derived from AAIController in UE5 C++"}, {"id": "gk_70", "t": "npc", "text": "[NPC] OnPossess is a virtual void override taking an APawn* pointer, used as the entry point where the AI controller takes over a pawn. Context: Overriding OnPossess in a custom AI controller to initialize NPC control logic"}, {"id": "gk_71", "t": "npc", "text": "[NPC] Super::OnPossess(InPawn) must be called first in the OnPossess override to ensure downstream logic in the base AAIController executes properly, preventing undefined behavior. Context: Lesson learned from past bugs where not calling Super on overrides caused weird behavior"}, {"id": "gk_72", "t": "npc", "text": "[NPC] Store a private pointer to the NPC character class (ControlledPawn) initialized as nullptr, then assign it in OnPossess using Cast<ANPCCharacter>(InPawn) to verify the pawn type. Context: AI controller casts the possessed pawn to the specific NPC character class to access NPC-specific functionality"}, {"id": "gk_73", "t": "npc", "text": "[NPC] After successful cast in OnPossess, retrieve the behavior tree from the NPC using ControlledPawn->GetBehaviorTree() and store it as a const UBehaviorTree* pointer. Context: The NPC character owns its behavior tree reference, and the AI controller retrieves it during possession"}, {"id": "gk_74", "t": "npc", "text": "[NPC] The NPC character class is derived from a shared base character class (TFCharacter), allowing both player and NPC characters to share common functionality. Context: Architecture pattern where NPC character inherits from same base as player character in a survival game"}, {"id": "gk_75", "t": "npc", "text": "[NPC] AI controller header uses sections private/protected/public, includes the NPC character header for the cast, and the ControlledPawn pointer does not necessarily need a UPROPERTY macro. Context: Class organization pattern for UE5 AI controller with private NPC reference"}, {"id": "gk_76", "t": "npc", "text": "[NPC] Nav Mesh Bounds Volume actor defines walkable area for AI navigation; toggle visibility with P key to see green overlay of navigable surfaces. Context: Required first step before any AI movement - covers floor areas and multi-level surfaces like stairs"}, {"id": "gk_77", "t": "npc", "text": "[NPC] AI Controller blueprint class serves as the 'brain' assigned to an AI character via the AI Controller Class property in the character's Details panel. Context: Separates AI logic (controller) from AI body (character), allowing reusable behavior patterns"}, {"id": "gk_78", "t": "npc", "text": "[NPC] Roaming NPC uses Get Random Reachable Point in Navigable Radius node with the controlled pawn's location as origin to pick random destinations. Context: On Begin Play triggers a custom 'Start Roaming' event that queries the nav mesh for valid random positions"}, {"id": "gk_79", "t": "npc", "text": "[NPC] Get Controlled Pawn node returns a Pawn object reference; pipe its return value through Get Actor Location to obtain XYZ world coordinates as the navigation origin. Context: The controlled pawn is the AI character body that the AI Controller is driving"}, {"id": "gk_80", "t": "npc", "text": "[NPC] Nav Mesh Bounds Volume scale of 15x15x15 via Details panel creates a large navigable cube; height must cover vertical geometry like stairs for multi-floor navigation. Context: R key activates scale gizmo for manual resizing; volume must fully enclose all intended AI roaming areas"}, {"id": "gk_81", "t": "npc", "text": "[NPC] AI character created by duplicating BP_ThirdPersonCharacter and reassigning its AI Controller Class from default to a custom controller blueprint. Context: Third Person template provides a ready-made character with mesh and animations that can be repurposed as an NPC"}, {"id": "gk_82", "t": "physics", "text": "[PHYSICS] 2D platformer uses trap collision detection where hitting any trap triggers player death and level restart. Context: Basic 2D platformer with walk, jump, collect items, and trap-based death/respawn loop"}, {"id": "gk_83", "t": "physics", "text": "[PHYSICS] Moving platforms are used as timed obstacles that the player must wait for before proceeding. Context: Level design includes platforms that move away and return on a cycle"}, {"id": "gk_84", "t": "npc", "text": "[NPC] Collectible item system uses a UI counter in the top-left corner tracking collected cherry count per level. Context: Cherry pickups are tracked with an on-screen HUD counter"}, {"id": "gk_85", "t": "physics", "text": "[PHYSICS] Level transition triggers load the next scene when the player reaches the end point of a level. Context: Completing a level automatically loads the next level scene in sequence"}, {"id": "gk_86", "t": "physics", "text": "[PHYSICS] Unity 2D platformer uses C# scripts edited in Visual Studio Community IDE with Unity autocompletion support. Context: Microsoft Visual Studio Community is recommended for C# scripting due to Unity interoperability and code completion"}, {"id": "gk_87", "t": "interior", "text": "[INTERIOR] Unity 6 terrain tiles are massive in scale \u2014 a single tile is large enough that a player cannot traverse it in a 10-20 minute play session, so developers should focus on one tile before expanding. Context: Terrain system scale guidance for level design in Unity 6 HDRP"}, {"id": "gk_88", "t": "interior", "text": "[INTERIOR] Build out one terrain tile completely (layers, textures, topology) before adding neighboring tiles, because adding layers after creating multiple tiles requires manually adding layers to each tile separately. Context: Workflow order matters for Unity terrain system to avoid redundant per-tile layer configuration"}, {"id": "gk_89", "t": "tps", "text": "[TPS] Unity 6 HDRP template project includes built-in third and first person controllers; free alternatives from Unity Technologies are available on Asset Store by searching 'third person'. Context: Character controller setup for terrain-based projects in Unity 6"}, {"id": "gk_90", "t": "interior", "text": "[INTERIOR] Terrain painting uses two primary controls: brush size and opacity, where opacity controls the influence level (strength) of the brush stroke on terrain height. Context: Unity terrain raise/lower tool parameters for sculpting topology"}, {"id": "gk_91", "t": "interior", "text": "[INTERIOR] Unity Shader Graph package includes importable 'production ready shaders' samples containing pre-built textures, prefabs, and rock assets that can be used as terrain layers. Context: Shader Graph samples provide ready-made terrain texturing materials in Unity 6"}, {"id": "gk_92", "t": "interior", "text": "[INTERIOR] In Unity 6 HDRP, use File > New Scene > Basic Outdoors to get a scene with pre-built volumetric clouds and outdoor lighting setup. Context: Scene template shortcut for outdoor terrain environments with atmospheric effects"}, {"id": "gk_93", "t": "npc", "text": "[NPC] A Queue<string> (FIFO collection from System.Collections namespace) is used to store dialogue sentences, allowing sequential display by loading sentences from the front of the queue as the player progresses through dialogue.. Context: Unity dialogue system stores NPC conversation sentences in a Queue rather than an array for ordered first-in-first-out processing."}, {"id": "gk_94", "t": "npc", "text": "[NPC] Dialogue data is stored in a separate non-MonoBehaviour class marked with [System.Serializable] attribute containing a public string[] sentences array and a public string name field, allowing it to appear in the Unity Inspector for editing.. Context: The Dialogue class is a serializable data container passed into the DialogueManager to start a new conversation."}, {"id": "gk_95", "t": "npc", "text": "[NPC] The architecture uses three scripts: DialogueManager (processes queue and displays text on an empty GameObject), Dialogue (serializable data class with name + sentences), and DialogueTrigger (attached to NPC/interactable to initiate conversation).. Context: A three-class separation pattern for dialogue systems in Unity keeps data, triggering, and display logic decoupled."}, {"id": "gk_96", "t": "npc", "text": "[NPC] The dialogue UI consists of a Canvas containing an Image (dialog box), two Text objects (NPC name and dialogue text), and a Continue button, all built with Unity's standard UI tools.. Context: Standard Unity UI hierarchy for an NPC dialogue box with name label, text content, and navigation button."}, {"id": "gk_97", "t": "npc", "text": "[NPC] The Queue is initialized in Start() as 'sentences = new Queue<string>()' and kept as a private variable on the DialogueManager, with sentences enqueued when a new dialogue starts and dequeued as the player clicks continue.. Context: Queue initialization and access pattern for managing dialogue sentence progression in Unity."}, {"id": "gk_98", "t": "physics", "text": "[PHYSICS] Cannon.js world gravity is set to -9.82 in the Y direction to simulate Earth gravity. Context: Setting up a Cannon.js physics world for a vehicle simulation in Three.js"}, {"id": "gk_99", "t": "physics", "text": "[PHYSICS] Ground body uses type 'static' with a geometric plane shape, rotated 90 degrees to be horizontal instead of vertical. Context: Creating the ground plane in Cannon.js physics world"}, {"id": "gk_100", "t": "physics", "text": "[PHYSICS] Cannon.js debugger takes the Three.js scene and physics world as arguments and creates green wireframe overlays on each physics object for visualization. Context: Using a debugger to visualize the physics world alongside the 3D scene"}, {"id": "gk_101", "t": "vehicles", "text": "[VEHICLES] Car body is created with mass=5 and positioned at (0,6,0) above ground, then wrapped in a Cannon.js RigidVehicle class that handles vehicle-specific physics. Context: Building a simple car using Cannon.js rigid vehicle framework"}, {"id": "gk_102", "t": "vehicles", "text": "[VEHICLES] Wheels are sphere shapes with 'wheel' material type, offset downward to avoid intersecting the car body, with angular dampening applied. Context: Adding wheels to a Cannon.js RigidVehicle"}, {"id": "gk_103", "t": "vehicles", "text": "[VEHICLES] RigidVehicle.addWheel() internally adds hinge constraints so wheels turn correctly; requires wheel body, position, axis, and direction parameters. Context: The Cannon.js RigidVehicle class abstracts away constraint setup for vehicle wheels"}, {"id": "gk_104", "t": "physics", "text": "[PHYSICS] Animation loop must call update on both the Cannon.js debugger and the physics world every frame to keep physics and rendering in sync. Context: Main game loop structure for Three.js + Cannon.js integration"}, {"id": "gk_105", "t": "city", "text": "[CITY] Gaia world generation uses a 4-step pipeline: 1) create World Designer in Gaia Manager, 2) generate world (stamps terrain), 3) spawn biome (populates vegetation/objects), 4) create runtime (enables gameplay). Context: Workflow for generating a fully populated island environment in Unity using Gaia terrain tool"}, {"id": "gk_106", "t": "city", "text": "[CITY] Gaia separates terrain shape generation (stamp step) from biome population (spawn step), allowing terrain geometry and object placement to be independently configured. Context: The island terrain mesh is created first, then biome spawning adds trees, rocks, and other objects as a separate pass"}, {"id": "gk_107", "t": "city", "text": "[CITY] Gaia uses a 'stamp' system to apply heightmap and sculpting data onto Unity terrain tiles, generating landmasses like islands from predefined or procedural templates. Context: The world generation step stamps an island shape onto the terrain before any object population occurs"}, {"id": "gk_108", "t": "npc", "text": "[NPC] ConvAI NPCs in UE5 generate real-time dynamic dialogue responses to player questions using generative AI, with each NPC maintaining a distinct personality and emotional state (angry car owner, concerned worker, indifferent bystander). Context: Demo shows multiple NPCs each responding differently to the same event based on their assigned role and disposition"}, {"id": "gk_109", "t": "npc", "text": "[NPC] ConvAI NPCs maintain contextual awareness of world events (tank hit by lightning, flipped into air) and reference them coherently in unscripted voice conversations with the player. Context: Multiple NPCs independently describe the same tank-lightning incident from different perspectives without scripted dialogue trees"}, {"id": "gk_110", "t": "npc", "text": "[NPC] NPCs are assigned occupational roles (construction crew supervisor, investigator, civilian driver) that constrain their dialogue priorities \u2014 e.g. construction NPC only cares about crew safety, car owner NPC fixates on vehicle damage. Context: Role-based personality systems shape NPC response focus even when asked the same open-ended questions"}, {"id": "gk_111", "t": "city", "text": "[CITY] The UE5 ConvAI demo features a drivable urban street environment with civilian vehicles, construction zones, and destructible/interactive elements like tanks subject to physics events. Context: City scene includes NPCs positioned contextually \u2014 workers near construction, drivers near damaged cars, investigators near incident"}, {"id": "gk_112", "t": "physics", "text": "[PHYSICS] Physics simulation triggers narrative events: a tank asset is struck by lightning and flips into the air, colliding with a civilian car \u2014 these physics outcomes become the shared context for all NPC conversations. Context: Demonstrates coupling physics engine events to AI dialogue systems so NPCs can discuss emergent gameplay moments"}, {"id": "gk_113", "t": "vehicles", "text": "[VEHICLES] Vehicle damage from physics events (tank flipping onto a car) persists in the world and NPCs reference the specific damage state \u2014 car owner NPC expresses anger about their damaged vehicle and refuses medical help. Context: Shows NPCs reacting to vehicle collision outcomes with emotionally consistent generative dialogue"}, {"id": "gk_114", "t": "npc", "text": "[NPC] Player initiates NPC conversations with natural speech input and NPCs respond with generated voice audio in real-time, supporting multi-turn dialogue (follow-up questions like 'are you okay' and 'do you want to go to the hospital'). Context: ConvAI system supports back-and-forth conversational flow rather than single-response interactions"}, {"id": "gk_115", "t": "dungeon", "text": "[DUNGEON] Pseudo-random number generators use a seed value fed into a formula to produce a deterministic sequence of numbers; same seed always produces the same sequence. System time is commonly used as seed for unique results each run.. Context: Foundation of all procedural and random generation in games."}, {"id": "gk_116", "t": "dungeon", "text": "[DUNGEON] Binding of Isaac dungeon generation: start with default starting room, randomly select one of 4 sides to place next room, pick a random room from predefined layout collection, repeat until enough rooms placed, then place boss room, then optionally scatter random elements (chests, items, special objects) inside rooms.. Context: Example of random generation using predefined room layouts stitched together."}, {"id": "gk_117", "t": "dungeon", "text": "[DUNGEON] Random generation uses predefined elements (pre-designed rooms, objects) assembled in random configurations. Procedural generation creates entirely original content algorithmically. These are distinct approaches despite being used interchangeably.. Context: Definitions per Gamasutra distinguishing the two generation paradigms."}, {"id": "gk_118", "t": "dungeon", "text": "[DUNGEON] Random generation requires developers to create large amounts of predefined content (room layouts, object placements) beforehand to ensure variety. Procedural generation avoids this by algorithmically creating content at runtime.. Context: Trade-off between the two approaches for dungeon/world generation."}, {"id": "gk_119", "t": "dungeon", "text": "[DUNGEON] Procedural generation of worlds (Minecraft, Terraria style) relies on computer-generated noise functions rather than predefined room stitching, enabling creation of original terrain and content the developers never manually designed.. Context: Noise-based procedural generation as alternative to room-stitching for large worlds."}, {"id": "gk_120", "t": "dungeon", "text": "[DUNGEON] Destructible terrain uses a dictionary with tile coordinates as keys and tile health as values; when health reaches zero the tile is removed from the tilemap. A level manager script handles tile placement and damage requests from player controller and other damage sources.. Context: Core system for cave exploration roguelike with destructible environments built in Godot."}, {"id": "gk_121", "t": "dungeon", "text": "[DUNGEON] Base tile size is 8x8 pixels for a minimalist pixel art aesthetic, chosen specifically to reduce art production time and allow focus on technical systems.. Context: Deliberate design constraint for a procedurally generated cave roguelike."}, {"id": "gk_122", "t": "dungeon", "text": "[DUNGEON] Cave generation uses a modular noise-based system with 'World Gen Rules' (custom resource type) that define conditions, values, and thresholds. The level manager loops through world coordinates for every rule and applies them based on conditions, enabling different caves, formations, and biomes.. Context: Procedural generation architecture allowing varied underground environments."}, {"id": "gk_123", "t": "dungeon", "text": "[DUNGEON] Color palette shader takes each pixel's color and shifts it to the nearest color in a predefined palette (modified Dawnbringer 32 palette from lospec.com), creating banded lighting effects as lights dim and a crunchy retro look.. Context: Post-processing visual technique for underground cave atmosphere."}, {"id": "gk_124", "t": "dungeon", "text": "[DUNGEON] Game structure replaces conventional roguelike floors/levels/rooms with a single large procedurally generated cave system. Deeper levels spawn different features, tested via a debug teleport view.. Context: World structure design for vertical cave exploration roguelike."}, {"id": "gk_125", "t": "dungeon", "text": "[DUNGEON] Traversal items include bombs (area destruction + weapon), ropes (vertical traversal + weapon), and flares (light up dark areas, inspired by Deep Rock Galactic), all interacting with the destructible tile system.. Context: Player tools designed for dual-purpose traversal and combat in cave environments."}, {"id": "gk_126", "t": "dungeon", "text": "[DUNGEON] Room placement uses spawn-then-separate: spawn randomly sized prefab rooms, detect overlaps, push overlapping rooms apart based on center-of-mass direction. Repeat until all rooms are separated. If separation fails, re-run with different initial placements.. Context: 3D dungeon generation system inspired by Lethal Company, built in Godot."}, {"id": "gk_127", "t": "dungeon", "text": "[DUNGEON] Rooms are prefab-based with predefined doors marked as 'necessary' (green) or 'optional' (yellow). A pathfinding algorithm connects all doors between separated rooms via corridors.. Context: Door connectivity system ensures rooms link together after placement separation."}, {"id": "gk_128", "t": "dungeon", "text": "[DUNGEON] Union-Find algorithm prevents isolated room islands: maintain sets/trees of connected nodes where each tree root is the lowest node value. When merging trees, update all nodes to the new lowest value. Continue connecting until all rooms share one set.. Context: Ensures full reachability across all rooms and floors in multi-level dungeons."}, {"id": "gk_129", "t": "dungeon", "text": "[DUNGEON] Multi-floor connectivity uses stair rooms that span exactly 2 floors. Union-Find tracks which floors are connected, and stair rooms are added iteratively until all floors belong to one connected set.. Context: Vertical dungeon connectivity solved as a separate pass after room placement."}, {"id": "gk_130", "t": "dungeon", "text": "[DUNGEON] The 3D algorithm is a direct extension of a 2D prototype: same overlap-separation and pathfinding-based corridor connection, but rooms are placed in 3D space and corridors are 3D hallways.. Context: Development approach started with 2D proof-of-concept before extending to 3D."}, {"id": "gk_131", "t": "dungeon", "text": "[DUNGEON] Algorithm order: (1) place random rooms, (2) separate overlapping rooms, (3) place stair rooms connecting floors via Union-Find, (4) connect same-floor rooms with pathfinding corridors via Union-Find until fully connected.. Context: Complete pipeline for procedural multi-level dungeon generation."}, {"id": "gk_132", "t": "dungeon", "text": "[DUNGEON] Procedural generation requires constraints to prevent unplayable results \u2014 pure random output produces white noise (random blocks everywhere with no terrain contour). Constraints ensure consistent surface materials, terrain flow, and structural coherence.. Context: Analysis of why Minecraft worlds look coherent despite being algorithmically generated, contrasted with completely random block placement."}, {"id": "gk_133", "t": "dungeon", "text": "[DUNGEON] Procedural generation design principle: balance enough variants to create unique/fun experiences while mitigating generation of unplayable configurations. Even a 1% chance of unplayability means 1 in 100 players gets a broken experience.. Context: Discussion of the fundamental tradeoff in proc-gen systems between variety and reliability."}, {"id": "gk_134", "t": "dungeon", "text": "[DUNGEON] Spawn validation is critical: if a player spawns surrounded by impassable material (e.g., stone in Terraria) with no escape, the world is unplayable. Spawn point selection must verify traversability.. Context: Example of worst-case proc-gen failure where generated terrain traps the player at spawn."}, {"id": "gk_135", "t": "dungeon", "text": "[DUNGEON] Brute-force voxel-based occlusion approximation can provide lighting for particle/voxel systems, but requires all geometry to stay within the voxel grid bounds \u2014 out-of-bounds procedural shapes get clipped, creating visual artifacts.. Context: Technical implementation detail from an iterated function system particle visualizer with voxel lighting."}, {"id": "gk_136", "t": "dungeon", "text": "[DUNGEON] Iterated Function Systems (IFS) using randomly generated sets of affine transformations produce unpredictable shapes \u2014 bounding the output within a fixed grid is a key constraint problem when combining proc-gen geometry with grid-based rendering.. Context: Demonstration of how procedural shape generation must be constrained to fit within rendering infrastructure bounds."}, {"id": "gk_137", "t": "rendering", "text": "[RENDERING] WebGL rendering pipeline: vertices (x,y,z coordinates) \u2192 connected into triangles (primitives) \u2192 light source creates shadows/depth \u2192 rasterized from 3D vector to 2D pixel projection. Context: Core 3D rendering pipeline stages used by WebGL to display graphics in browser"}, {"id": "gk_138", "t": "rendering", "text": "[RENDERING] Shaders are functions that customize the rendering pipeline, written in OpenGL ES Shading Language (not JavaScript), processing vertex or fragment data on the GPU to calculate pixel render data. Context: Shaders handle per-vertex and per-fragment calculations on GPU for real-time rendering"}, {"id": "gk_139", "t": "physics", "text": "[PHYSICS] Rendering at 60fps requires massive linear algebra/matrix multiplication operations that exceed CPU capacity alone, requiring GPU distribution of calculations. Context: GPU parallel processing is necessary for smooth real-time 3D graphics and physics simulations"}, {"id": "gk_140", "t": "rendering", "text": "[RENDERING] WebGL is based on OpenGL (established 1992), runs hardware-accelerated graphics on client GPU inside an HTML canvas element \u2014 initialized by getting canvas element then calling getWebGLContext(). Context: WebGL setup requires only an HTML canvas and its WebGL context to begin GPU-accelerated drawing"}, {"id": "gk_141", "t": "rendering", "text": "[RENDERING] 3D geometry is built from vertices connected into triangle primitives; rasterization converts these 3D triangles into 2D pixel projections for screen display. Context: Triangle-based mesh rendering is the fundamental building block for all 3D objects in WebGL"}, {"id": "gk_142", "t": "rendering", "text": "[RENDERING] Three.js and Spline are abstraction layers over WebGL that eliminate need to write raw shaders by hand for 3D web experiences. Context: Higher-level libraries simplify WebGL development for game and interactive 3D applications"}, {"id": "gk_143", "t": "fps", "text": "[FPS] Multiplayer Three.js app architecture: front-end creates player mesh, adds to local scene, then notifies backend; backend broadcasts new player parameters to all other connected front-ends so each client adds remote players to their own scene. Context: Basic client-server multiplayer pattern using Three.js scenes with per-client player instantiation"}, {"id": "gk_144", "t": "fps", "text": "[FPS] Player movement on front-end is handled locally using WASD or arrow keys before any network sync occurs; each client owns and controls only its own player object in the Three.js scene. Context: Client-authoritative movement pattern where input handling is done entirely on the front-end"}, {"id": "gk_145", "t": "fps", "text": "[FPS] Remote players are instantiated on each client by receiving parameter sets from the backend and calling the same constructor (e.g. new Hamburger with synced parameters) then adding the result to the local Three.js scene. Context: Multiplayer object replication pattern where player creation parameters are serialized and broadcast"}, {"id": "gk_146", "t": "fps", "text": "[FPS] Position the player's gun on screen so the player can see where they are shooting without needing separate crosshair UI \u2014 gun placement itself should indicate aim direction. Context: Gun positioning on screen should serve as a natural aiming reference, reducing UI dependency"}, {"id": "gk_147", "t": "fps", "text": "[FPS] Default FPS movement without game feel additions results in a flat glide forward feeling \u2014 camera bob, head bob, and movement sway are necessary to give the player the sensation of having legs. Context: The video satirically notes that without movement feel effects, the player feels like they're on a remote-controlled vacuum robot"}, {"id": "gk_148", "t": "fps", "text": "[FPS] FPS level design should utilize full 3D vertical space rather than flat 2D layouts \u2014 a skybox alone does not make a map three-dimensional if the playable geometry is flat. Context: Satirically warns against designing FPS maps as flat 2D planes that could be planned entirely on paper"}, {"id": "gk_149", "t": "shooting", "text": "[SHOOTING] Four standard FPS weapon archetypes: normal gun (medium range balanced), sniper rifle (scoped long range), shotgun (close range spread), machine gun (high fire rate with spread) \u2014 each needs distinct effective ranges and spread patterns to feel differentiated. Context: The video identifies the four default weapon types and satirizes poor balancing where they all feel the same"}, {"id": "gk_150", "t": "shooting", "text": "[SHOOTING] Machine gun spread pattern must be tuned carefully \u2014 too wide a spread cone makes bullets miss at any practical range, effectively hitting behind the player's intended target. Context: Exaggerated example of bad weapon balancing where spread is so wide bullets go in unintended directions"}, {"id": "gk_151", "t": "fps", "text": "[FPS] FPS UI should provide all necessary player information (health, ammo, minimap) \u2014 removing UI entirely in favor of 'immersion' removes critical gameplay feedback. Context: The video sarcastically suggests having no UI is bad, implying a well-designed HUD is essential for FPS gameplay"}, {"id": "gk_152", "t": "physics", "text": "[PHYSICS] Rapier physics engine integrated via @react-three/rapier; wrap Experience component in <Physics> component to enable physics simulation. Context: React Three Fiber game setup using Rapier as the physics engine"}, {"id": "gk_153", "t": "physics", "text": "[PHYSICS] Stage platform built as low-height cylinder using RigidBody with type='fixed' and explicit cylinder collider (colliders='force') so it blocks objects but doesn't move. Context: Creating a static game platform that participates in physics without being dynamic"}, {"id": "gk_154", "t": "interior", "text": "[INTERIOR] MeshReflectorMaterial from drei used to create reflective floor; fog added to blend background objects with the floor for depth effect. Context: Scene composition technique for polished visual appearance in React Three Fiber"}, {"id": "gk_155", "t": "interior", "text": "[INTERIOR] GLTF models loaded via useGLTF hook; gltfjsx CLI tool auto-generates React Three Fiber component code from .gltf model files. Context: Workflow for importing 3D models into R3F scenes"}, {"id": "gk_156", "t": "interior", "text": "[INTERIOR] Text3D component from drei renders 3D text; requires facetype.json font generated from facetype.js; subset characters to reduce file size (20MB full Japanese font reduced to 87KB by including only needed characters). Context: Optimizing 3D text rendering by generating font subsets for performance"}, {"id": "gk_157", "t": "interior", "text": "[INTERIOR] Zustand used for game state management over React Context (causes re-renders) and Redux (too verbose); game level generator creates array of stages with increasing difficulty by adding more options per stage. Context: State management architecture choice for React Three Fiber game engine"}, {"id": "gk_158", "t": "interior", "text": "[INTERIOR] Scene lighting uses ambientLight intensity=1 plus directionalLight for shadows; background color set on Canvas component. Context: Basic lighting setup for a 3D game scene in React Three Fiber"}, {"id": "gk_159", "t": "terrain", "text": "[TERRAIN] Stamp-based terrain sculpting uses a free Unity package called 'Stamp It' where you set stamp height, adjust brush size, and set 'stamp from current height' value to 1 to stack terrain stamps additively. Context: Rapid terrain shape creation using predefined height stamps rather than manual brush sculpting"}, {"id": "gk_160", "t": "terrain", "text": "[TERRAIN] Procedural Terrain Painter auto-textures terrain using layered rules: higher layers in the stack cover layers below, each layer supports modifiers like 'height' (with max height and max falloff) and 'slope' (to place rock textures on slopes), and multiple modifiers can be combined per layer. Context: Automated terrain texturing tool that assigns materials based on terrain geometry rather than manual painting"}, {"id": "gk_161", "t": "water", "text": "[WATER] Unity's built-in Water Surface River object is added via right-click, positioned at terrain center, raised to desired height, rotated and scaled to cover the area, with 'distance wind orientation' controlling river flow direction. Context: Adding river water to terrain using Unity's native water surface system"}, {"id": "gk_162", "t": "terrain", "text": "[TERRAIN] Mass tree placement uses Unity's 'MPL three' option to batch-place vegetation (e.g., 5000 or 10000 models at once) across the entire terrain surface, with tree height min/max controlling model size variation. Context: Efficient forest creation by bulk-placing tree models then selectively removing unwanted ones with Ctrl+click"}, {"id": "gk_163", "t": "terrain", "text": "[TERRAIN] Unity Terrain Tools package (installed via Window > Package Manager > Unity Registry) adds 'Spine Details' for grass placement that auto-mixes multiple grass models using 'Target Density' to control frequency of each model type. Context: Grass and small vegetation added using extended terrain tools with automatic model mixing"}, {"id": "gk_164", "t": "terrain", "text": "[TERRAIN] Terrain Tools brush mask filters (added via + button) include a 'Layer' filter that restricts detail painting to a specific texture layer with adjustable sharpness, enabling large-area detail placement constrained to specific terrain material zones. Context: Filter system ensures grass and details only appear on appropriate terrain surfaces like soil rather than rock"}, {"id": "gk_165", "t": "terrain", "text": "[TERRAIN] Realistic forests require vegetation of different heights to simulate natural forest layers (canopy, understory, ground cover), combining trees, smaller vegetation, and grass models. Context: Multi-layer vegetation principle for believable forest terrain composition"}, {"id": "gk_166", "t": "interior", "text": "[INTERIOR] In-game phone UI built as UMG Widget Blueprint (WB_Phone) using canvas panels: CP_Phone for outer container, CP_Screen for the screen area, with phone image set to 407x792 pixels matching the 3D phone model dimensions. Context: Creating an interactive phone system overlay similar to GTA/Saints Row where players press a key to bring up a phone widget"}, {"id": "gk_167", "t": "interior", "text": "[INTERIOR] Phone screen region defined by manually dragging canvas panel anchor points to match the screen portion of the phone image, then child elements use full-size anchors within that constrained CP_Screen canvas. Context: Technique for aligning UI elements to a specific region of a background image in UMG widget blueprints"}, {"id": "gk_168", "t": "interior", "text": "[INTERIOR] Phone widget centering done via Ctrl+Alt+Shift click on center anchor preset to set pivot to middle, then canvas set to 'desired' size mode instead of 'fill screen' to match phone dimensions. Context: UMG layout technique for centering a fixed-size widget element on screen"}, {"id": "gk_169", "t": "interior", "text": "[INTERIOR] Phone background wallpaper uses image tiling setting on the UMG Image widget to prevent squashing, combined with a background tint color (blue) for visual polish. Context: Technique to make a phone screen background look natural by using tiling instead of stretching a texture"}, {"id": "gk_170", "t": "interior", "text": "[INTERIOR] Doors in hub areas are modeled as visual props that don't lead anywhere \u2014 hallways surrounding the player terminate into void, creating the illusion of a larger space while keeping the playable area minimal.. Context: FNAF Help Wanted's main hub pizzeria uses fake doors and dead-end hallways just out of the player's sight line."}, {"id": "gk_171", "t": "interior", "text": "[INTERIOR] A one-sided piece of geometry is placed directly behind the player's cart to create the illusion that track fades out of existence, hiding the fact that the track model extends far behind the player.. Context: The intro roller coaster ride uses a single-faced occluder plane to mask geometry the player shouldn't see behind them."}, {"id": "gk_172", "t": "interior", "text": "[INTERIOR] Doorway transitions use pitch-black post-processing and a white sphere at the end of the passage; when the player reaches the sphere, the cart immediately stops and the scene cuts to the hub area.. Context: Room-to-room loading is masked by darkness inside door geometry with a trigger sphere that ends the transition cutscene."}, {"id": "gk_173", "t": "interior", "text": "[INTERIOR] Billboards along the intro track are all pre-loaded and visible in the scene but only illuminate as the player passes by them, using lighting activation rather than spawn/load triggers.. Context: All billboard geometry exists from scene start; timed light activation creates the illusion of progressive reveal."}, {"id": "gk_174", "t": "interior", "text": "[INTERIOR] The prize crane mechanism teleports back to its original suspended position behind a back wall after leaving the player's sight, rather than animating a return path.. Context: The crane slides out through a door, drops a prize, exits through another door, then instantly teleports back to reset position."}, {"id": "gk_175", "t": "interior", "text": "[INTERIOR] Room exteriors are covered in a default/placeholder texture since the player is never meant to see them; only interior-facing surfaces receive final art.. Context: The outside of the intro track room uses untextured default material, visible only when post-processing is disabled."}, {"id": "gk_176", "t": "interior", "text": "[INTERIOR] Hidden objects placed out of bounds include a disc-shaped flashing light and an 'end Showtime' button positioned to the right of the stage area, used as developer control assets.. Context: Leftover developer debug objects exist outside the playable bounds for controlling show sequences."}, {"id": "gk_177", "t": "interior", "text": "[INTERIOR] A 360\u00b0 immersive room requires multiple projectors, computers, and projection mapping software to create seamless interior environments. Context: Equipment list for building an immersive projection room that simulates realistic virtual scenarios"}, {"id": "gk_178", "t": "interior", "text": "[INTERIOR] Remote debugging of a multi-projector immersive room setup can be completed within 30 minutes when using projection mapping software. Context: Timeline for calibrating and debugging a 360\u00b0 projection room installation"}, {"id": "gk_179", "t": "interior", "text": "[INTERIOR] Adding sensors to an immersive projection room enables interaction with virtual content, allowing users to trigger and manipulate scene elements. Context: Sensor-based interactivity layer added on top of projected interior environments for scene simulation and interactive games"}, {"id": "gk_180", "t": "vehicles", "text": "[VEHICLES] Car movement and logic built iteratively in three.js with checkpoints and booster sections as core game mechanics. Context: 3D browser racing game built with Blender and custom three.js 'Rave' engine in 2 weeks"}, {"id": "gk_181", "t": "city", "text": "[CITY] Environment blocked out first in Blender focusing on track layout and feel before adding detail. Context: Workflow prioritized layout blockout in Blender then iterative refinement in three.js"}, {"id": "gk_182", "t": "rendering", "text": "[RENDERING] Lights set up in Blender and baked into lightmaps for optimal web performance rather than using real-time lighting. Context: Lightmap baking used to reduce runtime cost for browser-based 3D racing game"}, {"id": "gk_183", "t": "rendering", "text": "[RENDERING] Low-poly assets modeled and textured in Blender to add detail while keeping geometry count browser-friendly. Context: Asset pipeline used low-poly modeling with textures for a three.js web game"}, {"id": "gk_184", "t": "vehicles", "text": "[VEHICLES] Checkpoints and booster sections implemented as track mechanics to structure race progression and add speed variation. Context: Core racing mechanics iterated on until layout and feel were satisfactory"}, {"id": "gk_185", "t": "npc", "text": "[NPC] City Sample Crowds in UE 5.5 requires enabling the MassAI (MCrow) plugin, then adding the City Sample Crowds content package (select 5.3 version as no 5.5-specific update exists). Context: Setup pipeline for MetaHuman crowd NPCs in Unreal Engine 5.5"}, {"id": "gk_186", "t": "npc", "text": "[NPC] BP_CrowdCharacter blueprint must be reparented from SkeletalMeshActor to Character class, then all 5 SkeletonMeshComponent references must be replaced with the new mesh component. Context: Required blueprint reparenting step to make crowd characters function as proper characters with capsule collision"}, {"id": "gk_187", "t": "npc", "text": "[NPC] MassAgent component requires 3 entity config traits: AgentCapsuleCollisionSync (set to ActorToMass with ZSync transform deselected), AgentMovement (MassToActor), and AgentOrientationZ (MassToActor). Context: Incorrect MassAgent sync direction settings cause MetaHumans to not animate or spawn in place"}, {"id": "gk_188", "t": "npc", "text": "[NPC] UE 5.5 introduces a new error in the GetSafeCopy function of BP_CrowdCharacter; fix by clicking MakeArray, deleting the empty array element, and recompiling. Context: Version-specific bug workaround when migrating City Sample Crowds to UE 5.5"}, {"id": "gk_189", "t": "city", "text": "[CITY] ZoneGraph system uses ZoneShapes placed in levels with Lane Profiles containing forward and backward lanes (set width to 100); must enable Show > Developer > ZoneGraph in viewport to visualize shapes. Context: ZoneGraph defines walkable paths where crowd MetaHumans navigate in the city"}, {"id": "gk_190", "t": "npc", "text": "[NPC] ZoneShape Lane Profiles require custom tags (e.g., 'Peds') to be created and assigned, with the default tag deselected, to properly route crowd agents. Context: Tag-based lane filtering controls which crowd agent types use which navigation paths"}, {"id": "gk_191", "t": "npc", "text": "[NPC] Skeletal mesh components must be moved one-by-one into the Mesh component hierarchy and positioned inside the capsule collider; moving all at once can crash the editor. Context: Stability workaround when restructuring the crowd character blueprint component hierarchy"}, {"id": "gk_192", "t": "city", "text": "[CITY] Unity terrain detail distance must be increased (e.g., 250) to render grass/details visible from the player's position; default is too low for open worlds. Context: Grass painted on terrain was invisible at distance until detail distance was set to 250 in terrain settings"}, {"id": "gk_193", "t": "city", "text": "[CITY] Fog density of approximately 0.0045 with color sampled from the low horizon of the skybox creates a cohesive fade that hides terrain detail pop-in boundaries. Context: Fog obscures the distance where grass detail stops rendering, and color-matching it to the skybox horizon makes the transition seamless"}, {"id": "gk_194", "t": "city", "text": "[CITY] Unity Mass Place Trees feature can batch-place 15,000 trees across an entire terrain in one operation, but tree distance in terrain settings must be increased to render distant trees. Context: Only trees close to the player render by default; tree distance setting controls the rendering cutoff"}, {"id": "gk_195", "t": "city", "text": "[CITY] Terrain brush size of ~400 gives coarse landscape height passes, then reducing to ~200 adds finer terrain detail; use a brush with noise for natural-looking elevation. Context: Two-pass terrain sculpting with raise/lower terrain tool creates more natural height variation than a single pass"}, {"id": "gk_196", "t": "city", "text": "[CITY] For grass detail textures, sample the healthy color from lighter parts of the base ground texture and the dry color from darker parts using the eyedropper to maintain color cohesion. Context: Color-matching grass detail to the underlying terrain texture prevents visual disconnect between ground and vegetation layers"}, {"id": "gk_197", "t": "city", "text": "[CITY] A cohesive open world scene requires color-sampling consistency: skybox horizon color for fog, base texture colors for grass healthy/dry tints, and tree prefab materials matching the grass environment. Context: The tutorial emphasizes an eyedropper sampling technique across fog, grass, and trees to keep the entire scene visually unified"}, {"id": "gk_198", "t": "npc", "text": "[NPC] Replica AI NPC demo requires a 28 GB download, runs via a local setup/install process, and processes voice input with variable response latency \u2014 sometimes noticeably longer than real-time conversational pace. Context: Demonstrates the storage and compute cost of running local AI-driven NPC dialogue systems"}, {"id": "gk_199", "t": "npc", "text": "[NPC] AI NPCs maintain per-character personality and emotional state: different NPCs respond with distinct attitudes (hostile, dismissive, helpful) and can escalate or de-escalate based on player tone and conversation history within a session. Context: Demonstrates persistent conversational context and personality differentiation across NPC instances"}, {"id": "gk_200", "t": "npc", "text": "[NPC] AI NPCs can process contextual environmental queries (e.g., weather, directions to landmarks like a park) and generate spatially-aware responses such as 'go straight down the street and take a left at the next corner'. Context: Shows NPCs have some awareness of the game world's spatial layout and environmental conditions"}, {"id": "gk_201", "t": "city", "text": "[CITY] The demo city environment includes sidewalks, streets with vehicle traffic (including box trucks), stairs, and pedestrian NPCs walking routes \u2014 but has visible boundary limits referred to as 'the Matrix wall'. Context: City sandbox demo has finite world boundaries and standard urban scene elements"}, {"id": "gk_202", "t": "vehicles", "text": "[VEHICLES] The demo features AI-driven traffic with vehicles like box trucks navigating city streets, and NPCs contextually reference the traffic conditions (e.g., 'the traffic's ridiculous') when prompted. Context: Vehicles serve as ambient city simulation and NPCs can comment on traffic as environmental context"}, {"id": "gk_203", "t": "npc", "text": "[NPC] Voice-to-voice NPC interaction uses a pipeline of speech recognition \u2192 AI text generation \u2192 text-to-speech, with the latency gap visible between player speech ending and NPC audio response beginning. Context: Real-time voice NPC dialogue has a perceptible processing delay that varies per interaction"}, {"id": "gk_204", "t": "npc", "text": "[NPC] The Unrecord game (police game) shares assets with the Replica demo (e.g., the same box truck model appears in both), indicating asset reuse across AI NPC tech demos and game prototypes. Context: Asset pipeline reuse between AI NPC demos and in-development game titles"}, {"id": "gk_205", "t": "shooting", "text": "[SHOOTING] Bullet movement uses rotation basis multiplied by speed constant (set to 40) in the process function to move projectiles forward along their local negative Z axis. Context: Physical bullet projectile system rather than hitscan, bullets are scene instances with their own movement logic"}, {"id": "gk_206", "t": "shooting", "text": "[SHOOTING] Shoot animation length is 0.1 seconds (a tenth of a second) with snapping set to 100, using 3 keyframes: original position, gun pulled back, return to original position \u2014 only the middle keyframe position changes. Context: AnimationPlayer node with Property track on the gun mesh position creates recoil effect"}, {"id": "gk_207", "t": "shooting", "text": "[SHOOTING] Fire rate control checks if shoot animation is NOT currently playing before allowing another shot \u2014 if animation finished or button just pressed, play shoot animation again. Context: Uses Input.is_action_pressed in physics_process with animation state as the rate limiter"}, {"id": "gk_208", "t": "shooting", "text": "[SHOOTING] Bullet mesh is a BoxMesh with X and Y dimensions set to 0.05, with emission color at strength 5 for a glowing projectile effect. Context: Bullet scene uses Node3D root with MeshInstance3D child and RayCast3D for collision detection"}, {"id": "gk_209", "t": "shooting", "text": "[SHOOTING] Gun barrel spawn point uses a RayCast3D with target_position set to negative Z (0, 0, -1) since negative Z is the forward direction in Godot's coordinate system. Context: RayCast3D is positioned at the gun barrel to define bullet spawn location and verify gun model orientation"}, {"id": "gk_210", "t": "shooting", "text": "[SHOOTING] Bullet collision detection uses a RayCast3D attached to the bullet with length slightly exceeding the mesh bounds, pointing in negative Z direction. Context: Each bullet projectile has its own raycast for detecting hits rather than using a single hitscan ray from the camera"}, {"id": "gk_211", "t": "fps", "text": "[FPS] Gun is parented as child of the camera node, positioned using camera preview checkbox to see first-person view without running the game; shadow casting is disabled on gun mesh via cast_shadow setting in geometry section. Context: Standard FPS gun setup with visual tuning of metallic, specular, and roughness material properties"}, {"id": "gk_212", "t": "shooting", "text": "[SHOOTING] Hitscan bullets have zero travel time and hit whatever is at the crosshair center instantly when the trigger is pulled. Projectile bullets send a physical in-game object with real travel time requiring the player to lead shots on moving targets.. Context: The two fundamental bullet types used in FPS games with distinct gameplay implications."}, {"id": "gk_213", "t": "shooting", "text": "[SHOOTING] Bullets can originate from the center of the camera (between the eyes) or from the gun barrel. Camera-origin means the bullet naturally hits where the crosshair points. Games like Overwatch, Apex Legends, and CS:GO shoot from the camera/eyes.. Context: Bullet origin point is a core design decision affecting accuracy and visual fidelity."}, {"id": "gk_214", "t": "shooting", "text": "[SHOOTING] Camera-origin shooting enables 'head glitching' where players shoot from behind cover as long as their head is unobstructed. The fix is to move the camera down to about chest height so the view is obstructed when behind cover.. Context: A known exploit caused by placing the camera at the player model's eye height."}, {"id": "gk_215", "t": "shooting", "text": "[SHOOTING] For camera-origin projectiles, a fake cosmetic bullet is fired from the gun barrel for visual effect while the real invisible projectile originates from the camera center. In Overwatch, projectiles near wall edges pass through visually but the real hitbox projectile never collides with the wall.. Context: Dual-bullet technique solves the visual mismatch of projectiles appearing to come from the player's face."}, {"id": "gk_216", "t": "shooting", "text": "[SHOOTING] Barrel-origin shooting (used by PUBG, Escape from Tarkov, TF2 Soldier's rocket launcher) causes bullets to hit slightly off-center from the crosshair unless the developer compensates. Players must offset aim when hip-firing and watch for walls blocking the barrel's line of fire.. Context: More realistic but introduces aiming complexity and occlusion issues near geometry."}, {"id": "gk_217", "t": "shooting", "text": "[SHOOTING] With barrel-origin bullets, enemies who get between the player and the gun barrel tip cannot be hit even if the crosshair is on them, because guns have physical length. Games handle this by pulling the gun model back near objects or disabling shooting at very close range.. Context: Close-range edge case unique to barrel-origin bullet systems."}, {"id": "gk_218", "t": "shooting", "text": "[SHOOTING] A hybrid bullet type exists where bullets are hitscan up to a certain distance and become projectiles beyond that threshold. Used in some Halo games and Insurgency: Sandstorm to give close-range weapons like SMGs immediacy while limiting long-range sniper effectiveness.. Context: Rare technique that combines both bullet types with a distance-based transition."}, {"id": "gk_219", "t": "recoil", "text": "[RECOIL] Prodeus uses per-shot screen shake (screen vibration on every gunshot) as a recoil-feel mechanic, giving visceral feedback without complex recoil patterns. Context: Described as core to the game's feel alongside fast movement and sprite-based enemies"}, {"id": "gk_220", "t": "ammo", "text": "[AMMO] Ultrakill replaces traditional ammo/health pickups with a blood-as-fuel mechanic where killing enemies at close range refills health, encouraging aggressive play. Context: Tagline 'blood is fuel' defines the core loop of staying close to enemies to sustain health"}, {"id": "gk_221", "t": "ammo", "text": "[AMMO] Prodeus horror mods use severely limited ammo pools combined with restricted lighting to shift the genre from action shooter to survival horror within the same engine. Context: Custom campaign found via built-in level editor demonstrated genre-shifting through ammo scarcity"}, {"id": "gk_222", "t": "hitscan", "text": "[HITSCAN] Ultrakill features a fist-parry mechanic that reflects enemy bullets back, implying projectile-based (non-hitscan) bullets that can be intercepted and redirected mid-flight. Context: Described alongside coin trick-shot mechanic as part of Ultrakill's advanced combat system"}, {"id": "gk_223", "t": "impact_force", "text": "[IMPACT_FORCE] Prodeus enemies use high-pressure blood-explosion death effects (described as 'blood pinatas') with gore that coats the player's gun model and environment walls. Context: Visual impact feedback is a core design pillar making kills feel powerful in boomer shooters"}, {"id": "gk_224", "t": "shooting", "text": "[SHOOTING] Ultrakill implements a coin-toss trick-shot system where firing a bullet at a thrown coin redirects it toward enemies, combining projectile physics with precision timing. Context: Used as an example of innovative mechanics possible in indie boomer shooters vs AAA titles"}, {"id": "gk_225", "t": "weapon_setup", "text": "[WEAPON_SETUP] To attach a weapon model in Unity FPS, drag the model inside the player hierarchy alongside the dummy weapon, then align its transform position to match the dummy weapon's position.. Context: Demonstrates the standard parenting workflow for first-person weapon placement."}, {"id": "gk_226", "t": "weapon_setup", "text": "[WEAPON_SETUP] After importing a weapon prefab, right-click and select 'Prefab > Unpack Completely' to break the prefab link so individual parts can be freely modified.. Context: Unpacking is required before customizing imported weapon models."}, {"id": "gk_227", "t": "weapon_setup", "text": "[WEAPON_SETUP] Weapon model scale often needs manual adjustment after import; e.g. a pistol prefab was scaled to 2x its default size to look correct in first-person view.. Context: Asset store models rarely ship at the exact scale needed for an FPS camera."}, {"id": "gk_228", "t": "rendering", "text": "[RENDERING] Pink/magenta materials on imported weapon models indicate a shader mismatch; fix by selecting all materials then using Edit > Rendering > Materials > Convert Selected Built-in Materials to URP.. Context: Common issue when importing Standard shader assets into a URP project."}, {"id": "gk_229", "t": "shooting", "text": "[SHOOTING] Camera raycast aiming works by casting a ray from screen center, then faking the bullet trail from the gun barrel to the hit point; trails play fast enough that imperfect angles are unnoticeable. Context: Most common FPS/TPS aiming method used throughout the game dev industry"}, {"id": "gk_230", "t": "shooting", "text": "[SHOOTING] Camera raycast method causes bullet trails to clip through walls near the gun because the ray originates from the camera while the trail renders from the gun barrel, creating a perspective mismatch. Context: Visual artifact is easily reproduced by standing close to a wall corner with the reticle aimed past it"}, {"id": "gk_231", "t": "shooting", "text": "[SHOOTING] Third-person shooters exacerbate the camera-vs-gun offset problem because the camera is significantly farther from the gun than in first person, and objects can pass between camera and player causing backward shots. Context: Requires additional logic to prevent raycasting hits on objects between camera and player"}, {"id": "gk_232", "t": "shooting", "text": "[SHOOTING] Barrel-origin shooting (raycast or projectile from gun muzzle) is the most realistic but makes crosshair placement difficult because gun model sway causes the aim point to shift constantly. Context: Crosshair would need to track the barrel's actual direction, which looks unnatural in games"}, {"id": "gk_233", "t": "shooting", "text": "[SHOOTING] A hybrid aiming method uses a camera raycast to find a world-space target point, then aims the gun barrel toward that point and fires the projectile from the gun, combining camera-based targeting with barrel-origin bullets. Context: Third approach that balances visual accuracy with realistic bullet origin"}, {"id": "gk_234", "t": "shooting", "text": "[SHOOTING] Three standard aiming implementations: (1) camera raycast with faked bullet trail from gun, (2) direct barrel-origin raycast/projectile, (3) hybrid where gun aims at camera raycast hit point then fires from barrel. Context: Industry-wide approaches to solving the aiming problem in shooters"}, {"id": "gk_235", "t": "tps", "text": "[TPS] Camera follow uses a CameraHolder empty object with child camera; a CamPos transform (Y=2.6) inside the player is tracked each Update via transform.position = camPos.position for direct position lock. Context: Simple camera follow without spring arm or lag \u2014 camera snaps to player position every frame"}, {"id": "gk_236", "t": "tps", "text": "[TPS] Mouse look uses Input.GetAxisRaw MouseX/MouseY multiplied by sensitivity (100) and 0.01f; vertical rotation (X axis) is clamped to -90..90 degrees via Mathf.Clamp. Context: Standard FPS-style mouse look with separate X/Y sensitivity floats and vertical clamp to prevent over-rotation"}, {"id": "gk_237", "t": "tps", "text": "[TPS] Orientation is a separate empty child object inside the player whose rotation is set to Quaternion.Euler(0, yRotation, 0); camera transform gets Quaternion.Euler(xRotation, yRotation, 0) \u2014 decoupling body yaw from camera pitch. Context: Splitting orientation from camera rotation prevents rigidbody from tilting and allows movement direction to follow horizontal look only"}, {"id": "gk_238", "t": "tps", "text": "[TPS] Player movement direction is calculated as orientation.forward * yInput + orientation.right * xInput, then force is applied to Rigidbody in FixedUpdate with moveSpeed=10. Context: Using orientation transform for movement basis means player moves relative to camera facing direction"}, {"id": "gk_239", "t": "tps", "text": "[TPS] Rigidbody is configured with Interpolate=Interpolate and CollisionDetection=ContinuousDynamic; rb.freezeRotation=true is set in Start to prevent physics-driven rotation. Context: Continuous dynamic collision detection prevents fast-moving player from tunneling through geometry; freeze rotation stops rigidbody from tipping over"}, {"id": "gk_240", "t": "tps", "text": "[TPS] Cursor is locked and hidden at Start via Cursor.lockState=CursorLockMode.Locked and Cursor.visible=false. Context: Standard FPS cursor lock pattern to capture mouse input for camera rotation"}, {"id": "gk_241", "t": "tps", "text": "[TPS] Right stick rotates camera up/down and around the character providing full orbit control in third person view. Context: Naughty Controller uses dual-stick input: right stick for camera orbit, left stick for movement"}, {"id": "gk_242", "t": "tps", "text": "[TPS] Left stick analog sensitivity controls locomotion blend: soft press triggers walk animation, full tilt triggers sprint animation. Context: Controller reads analog stick magnitude to blend between walk and sprint states"}, {"id": "gk_243", "t": "tps", "text": "[TPS] Ground detection uses raycasting to know when the character has hit the ground for ground checks and landing animations. Context: Raycasts determine grounded state to trigger fall-to-land animation transitions"}, {"id": "gk_244", "t": "tps", "text": "[TPS] Unity new Input System package required for simultaneous mouse/keyboard and controller support in third person controller. Context: Input System package must be installed from Unity Package Manager registry and editor restarted to swap input backends"}, {"id": "gk_245", "t": "tps", "text": "[TPS] Standard/built-in pipeline materials convert to URP via Window > Rendering > Render Pipeline Converter using upgrade materials then initialize and install. Context: Naughty Controller was built for standard pipeline so materials appear pink in URP until converted"}, {"id": "gk_246", "t": "tps", "text": "[TPS] Character materials use Universal Render Pipeline Lit shader with albedo base map, normal map, and metallic smoothness map slots. Context: Head material requires head albedo on base map and head metallic smoothness on metallic slot after shader swap to URP Lit"}, {"id": "gk_247", "t": "tps", "text": "[TPS] Unity Starter Assets Third Person Controller uses a CineMachine camera (player follow camera) for third person camera control, separate from the main camera. Context: The prefab includes main camera, player armature, and player follow camera as separate components that can be added individually or as a parent prefab"}, {"id": "gk_248", "t": "tps", "text": "[TPS] The Starter Assets third person controller prefab must be unpacked completely (right-click > unpack prefab completely) before customization, and the scene's existing main camera must be removed first. Context: Having a duplicate main camera causes display conflicts; unpacking allows full editing of the prefab hierarchy"}, {"id": "gk_249", "t": "tps", "text": "[TPS] Unity third person controller supports WASD movement, sprint, jump with sound effects, and CineMachine-driven camera orbit control out of the box with zero additional scripting. Context: The prefab comes fully configured with input handling, animations, and audio as a rapid prototyping starter kit"}, {"id": "gk_250", "t": "tps", "text": "[TPS] To retarget a Mixamo or third-party character mesh to Unity's third person controller, set the imported FBX model rig type to Humanoid and hit Apply, which maps the skeleton to Unity's humanoid avatar system. Context: Humanoid rig type enables automatic animation retargeting so any humanoid mesh can reuse the same animator controller and animations"}, {"id": "gk_251", "t": "tps", "text": "[TPS] When swapping character meshes, the new mesh is placed inside the PlayerArmature > Root > Geometry hierarchy, and the transform must be reset (right-click transform > Reset) to align it to the correct position. Context: The animator controller on PlayerArmature references an avatar that must be updated from the old armature avatar to the new character's avatar"}, {"id": "gk_252", "t": "tps", "text": "[TPS] Mixamo FBX exports for Unity should use FBX for Unity format with the character kept in T-pose (original position) to ensure correct animation retargeting. Context: T-pose is the standard reference pose that Unity's humanoid rig system uses to map bones between different character skeletons"}, {"id": "gk_253", "t": "tps", "text": "[TPS] In Unreal Engine, skeletal mesh components have 'Only Owner See' and 'Owner No See' boolean properties under Rendering > Advanced that control per-player mesh visibility in multiplayer.. Context: These flags let you show a first-person arms mesh only to the owning player and a third-person full-body mesh only to other players."}, {"id": "gk_254", "t": "tps", "text": "[TPS] For the first-person mesh: set 'Only Owner See' = true and 'Owner No See' = false. For the third-person mesh: set 'Only Owner See' = false and 'Owner No See' = true.. Context: This inverse configuration ensures the local player sees FPS arms while remote players see the full third-person body."}, {"id": "gk_255", "t": "tps", "text": "[TPS] With Owner No See enabled on the third-person mesh, the owning player cannot see their own third-person shadow or legs when looking down, confirming the mesh is fully hidden locally.. Context: This is expected behavior \u2014 shadow casting from the hidden mesh is also suppressed for the owner."}, {"id": "gk_256", "t": "tps", "text": "[TPS] In a Listen Server setup with two players, each player's pawn has both a first-person skeletal mesh (FPS arms/weapon) and a separate third-person skeletal mesh (full body) attached simultaneously.. Context: Both meshes exist on the actor at all times; visibility flags determine which one each client renders."}, {"id": "gk_257", "t": "tps", "text": "[TPS] Using F8 (Eject/Possess) in editor reveals both the first-person and third-person meshes simultaneously since camera ownership rules no longer apply to the detached spectator view.. Context: This is a useful debug technique to verify both meshes are correctly positioned on the same pawn."}, {"id": "gk_258", "t": "tps", "text": "[TPS] Cinemachine FreeLook camera uses follow and lookAt targets set to the player character to create an orbiting third person camera. Context: FreeLook camera assigned the Jammo character as both follow and lookAt target for third person view"}, {"id": "gk_259", "t": "tps", "text": "[TPS] FreeLook camera X-axis speed controls horizontal orbit rate (default was high, reduced to 100 for smoother rotation) and Y-axis speed controls vertical look (reduced to 4 for smoother vertical panning). Context: Lowering both axis speeds from defaults produces a much smoother camera orbit feel"}, {"id": "gk_260", "t": "tps", "text": "[TPS] Cinemachine FreeLook camera is preferred over vcam for third person because it provides full orbital mouse-driven rotation around the character on both X and Y axes. Context: Tutorial removed the vcam and kept only the FreeLook camera for the orbiting third person setup"}, {"id": "gk_261", "t": "tps", "text": "[TPS] Camera smoothing in third person is achieved by tuning X-axis and Y-axis speed values lower \u2014 reducing X-axis from default to ~100 and Y-axis to ~4 eliminates jerky rotation. Context: Demonstrated that default speeds were too fast and that lowering them gave a much more smooth look when rotating the camera"}, {"id": "gk_262", "t": "tps", "text": "[TPS] Third person character velocity can be adjusted independently from camera speed to control movement feel without affecting camera orbit behavior. Context: Character velocity was reduced to make movement slower while camera orbit settings remained separate"}, {"id": "gk_263", "t": "tps", "text": "[TPS] Use ForceMode.VelocityChange when adding force to a rigid body player controller \u2014 this ensures velocity changes are not affected by the rigid body's mass or the physics simulation step length. Context: Proper rigid body movement without breaking physics simulation"}, {"id": "gk_264", "t": "tps", "text": "[TPS] Apply high drag only while the player is grounded and low drag while airborne \u2014 constant high drag causes floating/gliding when walking off edges. Context: Solving rigid body slipperiness requires a ground-state-dependent drag system"}, {"id": "gk_265", "t": "tps", "text": "[TPS] Never directly set rigid body velocity every physics frame \u2014 it breaks the physics simulation; use AddForce instead as recommended by Unity documentation. Context: Setting velocity explicitly overrides the physics engine's own calculations each fixed update"}, {"id": "gk_266", "t": "tps", "text": "[TPS] Ground checking with a single raycast is inaccurate \u2014 use a sphere cast or OnCollisionEnter, then verify the hit is actual ground by checking the slope angle (angle between player down vector and surface normal) against a threshold. Context: Raycasts falsely report airborne when the character stands on an edge"}, {"id": "gk_267", "t": "tps", "text": "[TPS] Wall collisions can falsely register as ground \u2014 fix by assigning ground objects to a dedicated physics layer or by comparing the slope angle between the player's down vector and the contact normal. Context: Edge case where wall contact triggers grounded state during sphere cast or collision callbacks"}, {"id": "gk_268", "t": "tps", "text": "[TPS] For character controller + physics interaction, apply a force at each contact point in the direction of the surface normal on every rigid body the controller touches. Context: Hybrid approach allowing character controllers to push physics objects"}, {"id": "gk_269", "t": "cannon.js_vehicle_physics", "text": "[CANNON.JS_VEHICLE_PHYSICS] Cannon.js physics engine combined with React Three Fiber enables car physics with angular velocity control while airborne, allowing flip tricks off ramps. Context: A race track demo uses cannon.js for vehicle colliders on trees, signs, and ramps with mid-air angular velocity manipulation"}, {"id": "gk_270", "t": "react_three_fiber_scene_setup", "text": "[REACT_THREE_FIBER_SCENE_SETUP] All Three.js scripts must be wrapped under the Canvas component because React Three Fiber hooks cannot be used outside of Canvas. Context: Canvas component from React Three Fiber does setup work behind the scenes to initialize the Three.js environment"}, {"id": "gk_271", "t": "3d_environment_map", "text": "[3D_ENVIRONMENT_MAP] A 3D scene background can be created using an environment map loaded via the Environment component, producing a blurred background that supports orbit controls. Context: The perspective camera uses orbit controls with a Target property defining the look-at point in 3D space"}, {"id": "gk_272", "t": "third_person_camera", "text": "[THIRD_PERSON_CAMERA] A toggleable third-person camera view can be implemented alongside orbit controls for vehicle-based gameplay in React Three Fiber. Context: The race track demo features a third-person camera that follows the player-controlled car"}, {"id": "gk_273", "t": "physics_colliders", "text": "[PHYSICS_COLLIDERS] Scene elements like trees, signs, and ramps can act as physics colliders in cannon.js, enabling realistic collision responses for vehicles. Context: Static world objects serve dual purpose as visual decoration and physical collision boundaries on the race track"}, {"id": "gk_274", "t": "react_three_fiber_dependencies", "text": "[REACT_THREE_FIBER_DEPENDENCIES] Core dependency stack for a 3D physics game: three.js, @react-three/fiber, @react-three/drei (utility functions), and @react-three/cannon (physics) \u2014 pin exact versions for stability. Context: The 3D web game space moves quickly so matching exact library versions is critical for reproducibility"}, {"id": "gk_275", "t": "hitscan", "text": "[HITSCAN] Hitscan weapons perform instant ray checks from crosshair to target \u2014 if the crosshair is on the enemy at fire time, it registers a hit with zero travel time, making accuracy a pure aim check.. Context: Hitscan is contrasted with projectile weapons which require leading targets and have travel time."}, {"id": "gk_276", "t": "hitscan_ai", "text": "[HITSCAN_AI] AI bots with hitscan weapons can theoretically hit 100% of shots since there is no projectile to dodge \u2014 accuracy must be artificially limited by programming inaccuracy or the bot effectively becomes unavoidable damage-over-time.. Context: Without intentional miss chance, hitscan bots remove all player agency in avoiding damage."}, {"id": "gk_277", "t": "hitscan_counterplay", "text": "[HITSCAN_COUNTERPLAY] Movement speed can serve as implicit hitscan counterplay \u2014 bots are typically programmed to be less accurate against faster-moving targets, letting games like Titanfall 2 use high-speed movement to simulate the dodge dynamics of projectile weapons.. Context: Fast movement creates a pseudo-projectile feel but lacks visual feedback since players cannot see missed hitscan rays."}, {"id": "gk_278", "t": "bullet_spread", "text": "[BULLET_SPREAD] Counter-Strike adds depth to hitscan by requiring players to learn per-weapon spray patterns, control fire rate to allow aim reset, and stand still while shooting \u2014 turning accuracy into a technical skill layer on top of basic aim.. Context: Spray pattern mastery, fire-rate management, and movement timing transform simple hitscan into a high-skill-ceiling mechanic."}, {"id": "gk_279", "t": "projectile_counterplay", "text": "[PROJECTILE_COUNTERPLAY] Projectile weapons have inherent counterplay because shots are visible and have travel time \u2014 players can dodge by moving radically or increasing distance, which increases the lead prediction required by the shooter.. Context: Projectile difficulty scales non-linearly with range since both travel time and required prediction increase."}, {"id": "gk_280", "t": "hitscan_design", "text": "[HITSCAN_DESIGN] FEAR makes hitscan work by having enemy soldiers vocally narrate their actions (flanking, grenading, etc.), turning cover-based hitscan counterplay from passive waiting into active tactical decision-making.. Context: Audio callouts combined with level design convert forced-cover moments into engaging combat loops despite hitscan's lack of visible dodgeable shots."}, {"id": "gk_281", "t": "shooting", "text": "[SHOOTING] Hitscan shooting uses Physics.Raycast originating from the camera position in the forward direction; if nothing is hit, no action is taken. Context: Raycasting shoots an invisible ray from the camera forward, gathering hit info on collision or doing nothing on a miss"}, {"id": "gk_282", "t": "shooting", "text": "[SHOOTING] A gun script requires configurable public floats: damage (default 10) and range (default 100 units). Context: Core gun parameters are exposed as public variables for tuning damage output and maximum effective distance"}, {"id": "gk_283", "t": "shooting", "text": "[SHOOTING] Input.GetButtonDown('Fire1') maps to the left mouse button by default in Unity and is used to trigger the shoot function. Context: Unity's built-in input system provides a Fire1 binding that defaults to left mouse button for shooting"}, {"id": "gk_284", "t": "shooting", "text": "[SHOOTING] RaycastHit stores information about what the ray collided with, enabling damage application and impact effects. Context: A RaycastHit variable captures collision data so the system can respond with damage, muzzle flash, impact effects, and physics force"}, {"id": "gk_285", "t": "shooting", "text": "[SHOOTING] Gun graphics should be parented to the main camera, and the camera's near clipping plane must be decreased to prevent the gun model from being clipped. Context: Attaching the gun as a child of the FPS camera and lowering the near clip plane ensures the weapon renders properly on screen"}, {"id": "gk_286", "t": "shooting", "text": "[SHOOTING] Raycast hitscan guns can apply an impact force to physics objects on hit, in addition to damage and visual effects like muzzle flash and impact particles. Context: The gun script supports adding force to rigidbodies at the hit point, creating physical reactions to being shot"}, {"id": "gk_287", "t": "shooting", "text": "[SHOOTING] Hitscan guns use Physics.Raycast instead of spawning a rigidbody bullet game object, determining hits instantly in one frame. Context: Core hitscan implementation: fire a raycast, check if it hits something, then visually represent the shot with a trail renderer"}, {"id": "gk_288", "t": "shooting", "text": "[SHOOTING] Hitscan bullet trails use a TrailRenderer that goes from the shot origin point to the raycast hit point, with an impact particle system spawned at the hit location. Context: Visual feedback for hitscan requires faking bullet travel since the raycast resolves instantly in a single frame"}, {"id": "gk_289", "t": "shooting", "text": "[SHOOTING] Hitscan shooting requires only 2 scripts: a Gun script (attached to the weapon game object) and a PlayerAction script (attached to the player capsule) that calls gun.shoot(). Context: Minimal architecture for hitscan guns using Unity's new Input System with Send Messages behavior"}, {"id": "gk_290", "t": "shooting", "text": "[SHOOTING] Unity's new Input System uses Send Messages behavior to call an OnShoot method on all scripts attached to the game object with PlayerInput, triggered by a custom 'shoot' action bound to left mouse button. Context: Input binding setup: create a shoot action in the Input Action Asset, bind to left mouse button, mark as keyboard-and-mouse control scheme"}, {"id": "gk_291", "t": "shooting", "text": "[SHOOTING] The Gun reference in PlayerAction is a private serialized field ([SerializeField] private Gun gun) so it can be assigned in the Unity Inspector rather than hardcoded. Context: Standard Unity pattern for decoupling the input handler from the weapon logic while keeping inspector configurability"}, {"id": "gk_292", "t": "camera", "text": "[CAMERA] Camera follow is implemented by creating a 'camera holder' empty object, making the camera a child of it, then in Update setting transform.position = camPos.position where camPos is a transform reference point parented to the player at Y offset 2.6. Context: Simple first-person camera follow that snaps camera holder position to a child transform of the player every frame in Update"}, {"id": "gk_293", "t": "FPS", "text": "[FPS] First-person mouse look uses two floats x and y, accumulating input via y += Input.GetAxisRaw('Mouse X') * sensX * 0.01f and x -= Input.GetAxisRaw('Mouse Y') * sensY * 0.01f, then clamping x with Mathf.Clamp(x, -90, 90). Context: Standard FPS mouse look script attached to the camera with vertical rotation clamped to prevent over-rotation"}, {"id": "gk_294", "t": "FPS", "text": "[FPS] Camera rotation is split: orientation.rotation = Quaternion.Euler(0, y, 0) for horizontal yaw on a separate orientation object, and transform.rotation = Quaternion.Euler(x, y, 0) for the camera itself combining pitch and yaw. Context: Separating yaw into an orientation transform allows movement direction to be decoupled from vertical camera look"}, {"id": "gk_295", "t": "FPS", "text": "[FPS] Movement direction is calculated as Vector3 moveDirection = orientation.forward * yInput + orientation.right * xInput, then force is applied to the Rigidbody so movement aligns with camera yaw without pitch influence. Context: Using the orientation transform (yaw only) ensures the player moves along the horizontal plane regardless of where the camera looks vertically"}, {"id": "gk_296", "t": "FPS", "text": "[FPS] Rigidbody is configured with Interpolate set to 'Interpolate' and Collision Detection set to 'Continuous Dynamic', with rb.freezeRotation = true in Start to prevent physics-driven rotations. Context: These Rigidbody settings prevent jitter on the camera-followed player and stop tunneling through colliders at high speed"}, {"id": "gk_297", "t": "camera", "text": "[CAMERA] Camera follow target (camPos) is placed as a child of the player object at local position Y = 2.6, representing approximate eye height above the player capsule origin. Context: The camPos transform acts as the camera anchor point and inherits all player movement and rotation automatically as a child object"}, {"id": "gk_298", "t": "FPS", "text": "[FPS] Mouse sensitivity values are set to approximately 100 for both X and Y axes, multiplied by 0.01f in code (effective multiplier 1.0), with cursor locked via Cursor.lockState = CursorLockMode.Locked and Cursor.visible = false. Context: Standard FPS cursor lock setup with sensitivity scaling built into the input processing formula"}, {"id": "gk_299", "t": "camera", "text": "[CAMERA] Spring arm (camera boom) target arm length set to 200-250 units for third-person follow camera; socket offset Y = 35; target offset Z = 60. Context: Base camera boom settings for a third-person character camera in UE5"}, {"id": "gk_300", "t": "camera", "text": "[CAMERA] Custom event 'MoveCamera' takes two float inputs: TargetArmLength and SocketYOffset, with variables LastSocketY and LastArmLength storing current values before interpolation. Context: Blueprint event setup to smoothly transition camera position when player changes movement speed"}, {"id": "gk_301", "t": "camera", "text": "[CAMERA] Camera boom current values cached by reading GetSocketOffset.Y into LastSocketY and GetTargetArmLength into LastArmLength before any transition begins. Context: Snapshot current camera state so lerp can interpolate from old to new values"}, {"id": "gk_302", "t": "camera", "text": "[CAMERA] Timeline node 'CameraFloat' with length 1 second drives the interpolation; keyframes at (0, 0) and (0.7, 1) with first keyframe set to Auto tangent for smooth easing. Context: Timeline provides a 0-1 alpha curve over ~0.7s with smooth-start easing for camera transitions"}, {"id": "gk_303", "t": "camera", "text": "[CAMERA] Lerp node interpolates TargetArmLength: A = LastArmLength, B = target input value, Alpha = timeline float output; result fed into SetTargetArmLength on camera boom each tick (Update pin). Context: Per-frame lerp on the timeline Update pin smoothly transitions arm length when sprinting or walking"}, {"id": "gk_304", "t": "camera", "text": "[CAMERA] Second lerp node interpolates SocketOffset.Y: A = LastSocketY, B = target SocketYOffset input, Alpha = same timeline float; result fed into SetSocketOffset split Y pin. Context: Socket offset Y is lerped in parallel with arm length so both camera distance and lateral offset transition together"}, {"id": "gk_305", "t": "camera", "text": "[CAMERA] Sprint triggers MoveCamera with extended arm length (e.g. 250) to pull camera further back; returning to walk resets to default values via StopCamera and ResetCamera custom events on timeline Stop/NewTime pins. Context: Camera dynamically zooms out when sprinting and returns to default on walk, using timeline stop and reset events"}, {"id": "gk_306", "t": "collision", "text": "[COLLISION] Door interaction box collision dimensions: X scale 2.5, Y scale 1.75, Z scale 3.45 \u2014 sized to encompass both the player character and the door swing radius.. Context: Resident Evil-style door system in UE5 uses a box collision child of the door component to detect player overlap for interaction."}, {"id": "gk_307", "t": "collision", "text": "[COLLISION] Door system uses a scene component called 'door open location' as a child of the door mesh to define the target transform for open/partial-open states, separate from the collision volume.. Context: The scene component acts as a look/position target that the door interpolates toward during state transitions."}, {"id": "gk_308", "t": "camera", "text": "[CAMERA] Resident Evil door transitions use a three-state enumeration cycle: Closed \u2192 Partially Open \u2192 Open, repeating in order, to control door animation and camera behavior during traversal.. Context: An enumeration blueprint (e_DoorStates) with three values drives the door state machine, replacing simple binary open/close with a more cinematic multi-stage transition."}, {"id": "gk_309", "t": "camera", "text": "[CAMERA] Spring arm (camera boom) socket offset of X:0, Y:60, Z:60 with target arm length 120 creates a dead-space style over-the-shoulder third-person camera. Context: UE5 third-person starter project configuring the camera boom component for over-the-shoulder view"}, {"id": "gk_310", "t": "camera", "text": "[CAMERA] Store the starting socket offset in a variable at BeginPlay so aim-to-unaim transitions can restore the original camera position instead of resetting to 0,0,0. Context: Without caching the original offset, transitioning back from aim mode centers the camera on the character incorrectly"}, {"id": "gk_311", "t": "camera", "text": "[CAMERA] Set ViewPitchMax to 40 degrees via GetPlayerCameraManager to prevent extreme vertical camera rotation in third-person mode. Context: Unrestricted pitch allows the camera to look straight up/down which looks unnatural for over-the-shoulder cameras"}, {"id": "gk_312", "t": "camera", "text": "[CAMERA] Camera boom socket offset X controls forward/back, Y controls left/right shoulder offset, Z controls height offset relative to the follow target. Context: UE5 spring arm socket offset coordinate system for positioning the camera relative to the character"}, {"id": "gk_313", "t": "camera", "text": "[CAMERA] Over-the-shoulder aim mode transitions involve interpolating the socket offset from a wider TPS position to a tighter aim position, triggered by right mouse button input. Context: Dead Space style camera switches between normal follow and tighter aim mode with a reticle dot overlay"}, {"id": "gk_314", "t": "camera", "text": "[CAMERA] Camera setup logic should be encapsulated in a dedicated function (e.g. SetUpCamera) called once from BeginPlay to cache initial spring arm values before any runtime transitions modify them. Context: Initialization pattern ensures original camera settings are preserved for state transitions between aim and default modes"}, {"id": "gk_315", "t": "camera", "text": "[CAMERA] For true first person in UE5, delete the spring arm component and parent the camera directly to the skeletal mesh component, then set the parent socket to 'head'. Context: Converting a third-person ACF character to true first person by attaching camera to the head bone instead of using a spring arm"}, {"id": "gk_316", "t": "camera", "text": "[CAMERA] Camera transform for true first person on helmeted character: location offset (10, 20, 290) and rotation 90 degrees to align forward with character facing direction. Context: Specific values used to position the camera at the head socket so it looks through the character's eyes without clipping through the helmet"}, {"id": "gk_317", "t": "camera", "text": "[CAMERA] Camera must be rotated 90 degrees on one axis after parenting to head socket to correct the default orientation so the view faces forward. Context: When attaching camera to a skeletal mesh socket the camera's default forward axis does not match the character's facing direction"}, {"id": "gk_318", "t": "camera", "text": "[CAMERA] For characters with large head geometry (helmets), push the camera location further forward from the head socket to prevent the mesh clipping into view. Context: Head-mounted camera on a helmeted character will show helmet geometry unless the camera is offset forward past the obstruction"}, {"id": "gk_319", "t": "camera", "text": "[CAMERA] Head-parented camera inherits all skeletal animation motion, causing significant wobble during combat animations designed for third person. Context: Third-person attack animations produce large head movement that translates directly to camera shake when camera is socket-attached to the head bone"}, {"id": "gk_320", "t": "FPS TPS", "text": "[FPS TPS] Converting TPS to true FPS requires duplicating the entire player character blueprint hierarchy (base player, full player, final player) and reparenting each layer to maintain framework functionality. Context: ACF framework uses a 3-level BP inheritance chain that must be preserved when creating a first-person variant alongside the existing third-person setup"}, {"id": "gk_321", "t": "FPS TPS", "text": "[FPS TPS] True first person (camera on head bone) lets the player see their full body when looking down, unlike viewport-only first person which hides the body. Context: Advantage of socket-attaching camera to the mesh head bone is full body visibility providing more immersive first-person experience"}, {"id": "gk_322", "t": "collision", "text": "[COLLISION] Use sphere cast instead of single raycast for ground checking \u2014 a raycast will falsely report the player is airborne when standing on an edge, while a sphere cast covers more area beneath the collider. Context: Sphere cast provides more accurate ground detection for character controllers than a simple raycast"}, {"id": "gk_323", "t": "collision", "text": "[COLLISION] Make the sphere cast radius slightly smaller than the character collider radius so it won't register wall contacts as ground contacts, though this can introduce other edge cases. Context: Prevents walls from being falsely detected as ground surfaces during sphere cast ground checks"}, {"id": "gk_324", "t": "collision", "text": "[COLLISION] Validate ground contacts by checking slope angle: compute the angle between the player's down vector and the surface normal vector, and only register as ground if the angle is below a threshold. Context: Prevents walls and steep surfaces from being incorrectly classified as walkable ground"}, {"id": "gk_325", "t": "collision", "text": "[COLLISION] For character controller physics interaction with rigidbodies, apply a force at each contact point in the direction of the surface normal for every contact the character controller makes. Context: Enables a kinematic character controller to push dynamic rigidbody objects on contact"}, {"id": "gk_326", "t": "collision", "text": "[COLLISION] Use ForceMode.VelocityChange when adding movement force to a rigidbody player controller \u2014 this makes velocity changes independent of rigidbody mass and physics timestep length. Context: Ensures consistent movement speed regardless of mass or fixed update rate"}, {"id": "gk_327", "t": "collision", "text": "[COLLISION] Apply high drag on a rigidbody controller only while grounded and set drag much lower when airborne \u2014 grounded-only high drag fixes slipperiness, while low air drag prevents floating/gliding when walking off edges. Context: Separate drag values for grounded vs airborne states produce natural movement feel"}, {"id": "gk_328", "t": "collision", "text": "[COLLISION] On slopes, project the movement force vector to be parallel to the ground surface using the ground normal, and add an upward counter-force to counteract gravity \u2014 otherwise the player moves slower uphill, faster downhill, and slides when stationary. Context: Two separate slope fixes needed: anti-slide counter-gravity force and surface-parallel movement direction"}, {"id": "gk_329", "t": "buoyancy", "text": "[BUOYANCY] Buoyancy force is calculated as Vector3.up multiplied by floatingPower multiplied by the difference between water height and rigidbody Y position, so deeper submersion produces stronger upward force. Context: Core formula for making rigidbodies float on a water plane in Unity"}, {"id": "gk_330", "t": "buoyancy", "text": "[BUOYANCY] ForceMode.Force is used when applying the upward buoyancy force to the rigidbody, which accounts for mass and applies force over time rather than as an impulse. Context: The force mode choice ensures heavier objects sink more and lighter objects float higher"}, {"id": "gk_331", "t": "buoyancy", "text": "[BUOYANCY] Underwater drag values of 3 (linear) and 1 (angular) versus air drag values of 0 (linear) and 0.05 (angular) are used, switching between them based on whether the object is submerged. Context: Separate drag values for underwater vs above water simulate water resistance on rigidbodies"}, {"id": "gk_332", "t": "buoyancy", "text": "[BUOYANCY] A waterHeight float defines the Y-level of the water plane, and the difference between waterHeight and the rigidbody's Y position determines submersion depth and force magnitude. Context: Simple planar water uses a single float for water level rather than mesh-based detection"}, {"id": "gk_333", "t": "buoyancy", "text": "[BUOYANCY] The script uses RequireComponent(Rigidbody) attribute and runs buoyancy logic in FixedUpdate since it is physics-based, with a boolean tracking whether the object is currently underwater. Context: Physics calculations must run in FixedUpdate for consistent behavior across frame rates"}, {"id": "gk_334", "t": "buoyancy", "text": "[BUOYANCY] The water surface is a plane with its collider removed, serving only as a visual reference while the waterHeight float handles the actual physics boundary. Context: The water plane is purely visual; buoyancy is computed mathematically against a height value, not via collision"}, {"id": "gk_335", "t": "water", "text": "[WATER] Water material controls normal map, scattering, color tints, reflections, foam settings, and SSS (subsurface scattering) tint to adjust overall water appearance. Context: Crest ocean system uses a single ocean underwater material with separate parameters for each visual property"}, {"id": "gk_336", "t": "water", "text": "[WATER] Foam generation is driven by shallow depth \u2014 shallower areas produce more foam, with adjustable foam strength that updates in real-time during rendering. Context: Crest uses a Sim Foam Settings component where shore/shallow depth controls foam density and strength"}, {"id": "gk_337", "t": "water", "text": "[WATER] Wave animation uses an FFT (Fast Fourier Transform) shape component on a separate game object to generate animated waves. Context: Crest separates wave generation into a dedicated Shape FFT component that feeds into the ocean renderer"}, {"id": "gk_338", "t": "water", "text": "[WATER] Water system requires linear color space (not gamma) set in Project Settings > Player > Other Settings for correct rendering. Context: Crest ocean renderer produces best results only when the project uses linear color space"}, {"id": "gk_339", "t": "water", "text": "[WATER] Ocean rendering uses a LOD system with underwater support, surface clipping, acoustic simulation, and scattering \u2014 all as modular add-on components. Context: Crest architecture is component-based: animated waves, foam, LOD, underwater, and clipping are separate scripts added to the ocean game object"}, {"id": "gk_340", "t": "water", "text": "[WATER] Water system supports physics interaction allowing objects to be affected by water buoyancy and wave forces. Context: Crest includes physics-driven water interaction so rigid bodies can float and respond to wave motion"}, {"id": "gk_341", "t": "water", "text": "[WATER] Gerstner waves combine multiple sine waves to create complex ocean surfaces; more waves increase computational cost proportionally.. Context: Chosen over FFT waves (too complex) and scrolling textures (outdated) as the primary wave generation method."}, {"id": "gk_342", "t": "water", "text": "[WATER] Ocean mesh is a plane with LOD that gradually reduces detail from center outward; since waves are world-space, the mesh moves with the player to simulate an infinite ocean.. Context: The mesh was created in Blender with variable vertex density for performance optimization."}, {"id": "gk_343", "t": "water", "text": "[WATER] Distant waves use scrolling normal map textures on a completely flat surface instead of Gerstner displacement, saving GPU cost since the player never gets close.. Context: A hybrid approach where only near-field waves use vertex displacement and far-field waves fake detail with normal maps."}, {"id": "gk_344", "t": "water", "text": "[WATER] Ocean height data is rendered to a Render Target so any object in the world can cheaply sample wave height instead of recalculating Gerstner equations per-object; limitation is no rotation data is available.. Context: Used for lily pad deformation and buoy floating, though buoys suffer from the lack of rotation information."}, {"id": "gk_345", "t": "water", "text": "[WATER] Surface foam is added during stormy weather by increasing wave height and sharpness, combined with Niagara particle splashes spawned on wave peaks via a scratch pad module that samples the wave render target and destroys particles on low waves.. Context: The wave system is integrated with a weather system to dynamically change ocean appearance and foam generation."}, {"id": "gk_346", "t": "water", "text": "[WATER] Fake god rays are created in a fog material by stretching a noise texture in the light direction to brighten the fog, faded out over depth; volumetric shadow methods and shadow-casting planes were rejected due to visual artifacts.. Context: Light functions don't affect volumetric shadows, and invisible shadow-casting planes created unwanted shadow artifacts on other surfaces."}, {"id": "gk_347", "t": "water_volume_setup", "text": "[WATER_VOLUME_SETUP] ACF (Advanced Character Framework) uses a Physics Volume actor to define swimmable water areas. Place the volume to cover the water region and enable the 'Water Volume' flag so the framework auto-detects swim state.. Context: A Physics Volume with Water Volume enabled triggers automatic swim behavior when a character enters the volume bounds."}, {"id": "gk_348", "t": "swim_trigger", "text": "[SWIM_TRIGGER] Swimming is triggered by character overlap with the Physics Volume; exiting the volume immediately reverts the character to ground locomotion (walk/run blend space).. Context: The transition between swimming and walking is driven entirely by whether the character is inside or outside the water physics volume."}, {"id": "gk_349", "t": "water_surface_alignment", "text": "[WATER_SURFACE_ALIGNMENT] The top face of the Physics Volume should be aligned with the water surface mesh so the swim-to-walk transition matches the visible waterline and avoids awkward blending near the shore.. Context: Proper vertical alignment of the volume top with the water surface prevents the character from swimming above water or walking underwater."}, {"id": "gk_350", "t": "swim_blend_space", "text": "[SWIM_BLEND_SPACE] ACF uses a blend space for swim animations that activates automatically when the Water Volume flag is enabled on the physics volume \u2014 no additional animation blueprint wiring is required.. Context: The swim blend space is built into ACF and selected at runtime based on the water volume overlap state."}, {"id": "gk_351", "t": "water_color_absorption", "text": "[WATER_COLOR_ABSORPTION] Water color is implemented via light absorption formula: absorption_coefficient = percentage of light absorbed, using formula where alpha is absorption coefficient, a is percentage absorbed, x is material thickness. The absorption value is subtracted from scene color rather than multiplied.. Context: Beer-Lambert style absorption model applied in Unity Shader Graph for realistic water coloring based on depth."}, {"id": "gk_352", "t": "water_transparency", "text": "[WATER_TRANSPARENCY] Water transparency uses the Scene Color node (screen color buffer before water plane renders) instead of alpha output. The shader must be marked as transparent to access pre-rendered screen content.. Context: URP Shader Graph technique where scene color provides what's already rendered behind the water surface."}, {"id": "gk_353", "t": "water_depth_fade", "text": "[WATER_DEPTH_FADE] Water color changes based on depth: deeper water absorbs more color. Depth is calculated from camera position using the Scene Depth node (camera depth buffer before object renders), determining how much water the viewer is looking through.. Context: Depth-based absorption replaces a static thickness value to create realistic shallow-to-deep water color transitions."}, {"id": "gk_354", "t": "water_absorption_color_inversion", "text": "[WATER_ABSORPTION_COLOR_INVERSION] To select a desired water color instead of an absorption color, use one_minus(waterColor) to derive the absorption color. This inverts the target color so the absorption process yields the intended final water color.. Context: Artist-friendly workflow where you pick the end result color and the shader calculates which wavelengths to absorb."}, {"id": "gk_355", "t": "water_shader_components", "text": "[WATER_SHADER_COMPONENTS] A complete water shader consists of: transparency, color absorption, caustics, reflectiveness, aeration (foam/bubbles), and aeration movement. Each can be implemented as separate modules.. Context: Overview of water shader feature breakdown for modular Shader Graph implementation in Unity URP."}, {"id": "gk_356", "t": "water_absorption_formula", "text": "[WATER_ABSORPTION_FORMULA] Absorption formula nodes: absorption_coefficient controls how far light travels through material before fully absorbed, varies per wavelength and material. Result is multiplied by absorption color to get percentage of color visible, then subtracted from scene color.. Context: Node-based implementation of physical absorption model converted from mathematical formula into Shader Graph groups or sub-graphs."}, {"id": "gk_357", "t": "HDRP water setup", "text": "[HDRP WATER SETUP] Unity HDRP water system requires version 16+ of HDRP package and Unity 2023.2+; water surfaces are added via hierarchy right-click > Water menu with options for ocean/sea/lake, pool, and river. Context: The water system must be explicitly enabled in the HDRP asset settings and requires a Water Rendering override added to the Sky and Fog volume with state set to enabled"}, {"id": "gk_358", "t": "HDRP water rendering pipeline", "text": "[HDRP WATER RENDERING PIPELINE] Full water rendering requires enabling multiple pipeline features: water simulation, deformation, water foam, script interactions, surface decals, screen space reflections, and transparent screen reflections. Context: These settings are found in the Quality HDRP asset under the water section and must each be individually enabled for correct rendering"}, {"id": "gk_359", "t": "HDRP water surface types", "text": "[HDRP WATER SURFACE TYPES] The HDRP water system provides distinct surface types: Ocean/Sea/Lake for large bodies, Pool for contained water, and River for flowing water, plus auxiliary tools including excluder, deformer, and foam generator. Context: Each surface type is a separate component added through the Water hierarchy menu with different simulation characteristics"}, {"id": "gk_360", "t": "HDRP water visual features", "text": "[HDRP WATER VISUAL FEATURES] The water system supports waves, ripples, foam, underwater caustics, refractions, reflections, and deformation simulation as built-in features. Context: These effects combine to create realistic cinematic water for both ocean surfaces and underwater environments"}, {"id": "gk_361", "t": "HDRP water samples", "text": "[HDRP WATER SAMPLES] Unity provides importable water sample scenes via Package Manager > HDRP > Samples > Water Samples, including an Island scene pre-configured with correct water rendering settings. Context: The sample scenes automatically configure deformation, foam, script interactions, decals, screen space reflections, and volumetric clouds"}, {"id": "gk_362", "t": "HDRP water deformation", "text": "[HDRP WATER DEFORMATION] Water deformation is a separate render pipeline feature that must be enabled independently from base water rendering in the HDRP quality asset settings. Context: Deformation allows the water surface to be displaced by gameplay interactions and deformer objects placed in the scene"}, {"id": "gk_363", "t": "water", "text": "[WATER] Stylized Water for URP requires Unity 2019.3.9+ and supports buoyancy, waves, foam, refraction, planar reflections, and custom lighting. Context: Free Unity asset providing full stylized water pipeline for URP with mobile-friendly performance"}, {"id": "gk_364", "t": "water", "text": "[WATER] Water depth rendering uses shallow color near objects and deep color at edges, with configurable horizon settings and shore edge blending. Context: Depth-based color gradient system controls visual appearance based on object proximity and water depth"}, {"id": "gk_365", "t": "water", "text": "[WATER] Surface foam uses texture-based alpha cutoff, distortion amount, configurable scale, direction, and speed for both primary and secondary foam layers. Context: Dual-layer foam system with independent control over each layer's movement and appearance"}, {"id": "gk_366", "t": "water", "text": "[WATER] Intersection effects detect world objects intersecting water and apply configurable direction, scale, and blending at contact points. Context: Object-water intersection rendering creates foam and visual effects where geometry meets the water surface"}, {"id": "gk_367", "t": "water", "text": "[WATER] Asset includes specialized prefabs for beach cascading water, buoyancy floating objects, object interaction with planar reflections, and stylized game water. Context: Multiple demo scenes demonstrate different water configurations commonly needed in game development"}, {"id": "gk_368", "t": "water", "text": "[WATER] Foam shadows can be enabled separately with configurable strength, intersection amount, and foam effect intensity. Context: Optional shadow rendering on foam adds depth and realism while keeping it performant as a toggle"}, {"id": "gk_369", "t": "proc-gen", "text": "[PROC-GEN] Unconstrained random generation produces white-noise output \u2014 blocks everywhere with no terrain contour; constraints must enforce dirt-on-surface, no sky blocks, consistent terrain flow, and tree self-similarity to produce playable worlds.. Context: Minecraft world generation compared to pure random (white noise) to illustrate why constraints are mandatory."}, {"id": "gk_370", "t": "proc-gen", "text": "[PROC-GEN] Even with constraints, undesirable edge cases slip through \u2014 ranging from funny quirks to full unplayability (e.g., Terraria spawning a player surrounded by impassable stone). At 1% failure rate with millions of players, thousands get broken worlds.. Context: Explains why many studios move to artist-authored levels: procedural generation cannot guarantee 0% unplayable outcomes."}, {"id": "gk_371", "t": "proc-gen", "text": "[PROC-GEN] Procedural generation is not inherently random \u2014 results can be deterministic (same seed = same output). Randomness is opted into specifically to produce unpredictable variety; without that goal, manual authoring is preferred.. Context: Formal definition distinguishing algorithmic creation from artist-authored content."}, {"id": "gk_372", "t": "proc-gen", "text": "[PROC-GEN] The core engineering tradeoff: enough variance to keep gameplay unique and replayable vs. enough constraints to prevent unplayable degenerate cases. Tightening constraints reduces variety; loosening them increases failure rate.. Context: Described as 'taming chaos of RNGs' \u2014 a fundamental tension in all proc-gen systems."}, {"id": "gk_373", "t": "proc-gen", "text": "[PROC-GEN] High-fidelity games (e.g., God of War) still use procedural generation during development for element placement like foliage positions, but artists make the final design decisions \u2014 a hybrid approach that avoids runtime generation risks.. Context: Distinguishes dev-time procedural assist (artist-validated) from runtime generation (player-facing risk)."}, {"id": "gk_374", "t": "proc-gen", "text": "[PROC-GEN] Iterated function systems (IFS) using randomly generated sets of affine transformations can drive particle system visualizations, producing attractor patterns useful for procedural effects and lighting.. Context: Mentioned as a technique used in the presenter's own project for procedural particle effects."}, {"id": "gk_375", "t": "environment_design", "text": "[ENVIRONMENT_DESIGN] Complex dense environments like Elden Ring's Lindell Capital gate use a strategy of overwhelming scale with soaring towers and intricate filigree detail to convey power and royalty \u2014 the visual density is intentional design language, not random placement.. Context: Artist reverse-engineered FromSoftware's environmental storytelling approach by cataloging and studying each location before rebuilding in Unreal Engine."}, {"id": "gk_376", "t": "environment_design", "text": "[ENVIRONMENT_DESIGN] Every placement of rocks, broken churches, and cave entrances in Elden Ring is deliberately considered to weave storytelling into the environment geometry itself.. Context: FromSoftware's level design philosophy treats prop and formation placement as narrative tools rather than decorative filler."}, {"id": "gk_377", "t": "workflow", "text": "[WORKFLOW] Step 1 of environment recreation in Unreal Engine is gathering reference (images, videos, on-location photos, sketches) using a tool called PureRef to dissect the logic and visual structure before any 3D work begins.. Context: Reference gathering serves to reverse-engineer the construction strategy behind visually complex environments."}, {"id": "gk_378", "t": "environment_design", "text": "[ENVIRONMENT_DESIGN] Large-scale fantasy environments achieve depth and impact through layered visual complexity \u2014 dense intricate surface detail (filigree) combined with macro-scale architectural forms (towers, gates) creates the 'larger than life' effect.. Context: The Lindell Capital gate uses this dual-scale approach to communicate overwhelming grandeur to the player."}, {"id": "gk_379", "t": "marching_cubes", "text": "[MARCHING_CUBES] 8 corner points per cube, each with a noise value; values above 0 = air/open space, below 0 = rock/solid. 256 possible configurations but only 15 unique cases (rest are symmetries). Surfaces constructed from triangles by connecting edges in groups of 3.. Context: Core algorithm for generating terrain meshes from a 3D density field, published in 1987 for medical scan visualization but widely used in games."}, {"id": "gk_380", "t": "density_field", "text": "[DENSITY_FIELD] Terrain stored as a 3D texture of scalar values. Zero crossing defines the surface boundary. Negative values = inside solid, positive = open air. Slicing the 3D texture shows lighter regions (outside) and black regions (below surface) with a red boundary line at value 0.. Context: A 3D texture acts as the density field that marching cubes samples to construct the mesh."}, {"id": "gk_381", "t": "marching_cubes_gpu", "text": "[MARCHING_CUBES_GPU] Core algorithm written in HLSL to process many cubes in parallel on the GPU. Per cube: calculate 8 corner coordinates, look up their density values, determine which of 256 configurations applies via a precomputed triangle table, then find which edges the surface passes through and connect vertices in groups of 3 to form triangles.. Context: GPU parallelism is essential for real-time marching cubes performance."}, {"id": "gk_382", "t": "terraforming_caves", "text": "[TERRAFORMING_CAVES] Single-heightmap planets cannot represent caves, tunnels, or overhangs because each point maps to only one height value. A volumetric density field (3D grid of air/rock values) solves this, enabling carving of arbitrary underground geometry.. Context: Motivation for switching from noise-displaced sphere meshes to a full voxel marching cubes approach."}, {"id": "gk_383", "t": "marching_cubes_lookup", "text": "[MARCHING_CUBES_LOOKUP] A giant precomputed lookup table maps each of the 256 cube configurations to triangle edge connections. Two small arrays map each edge index to its two endpoint corner indices. Vertex placement along each edge defaults to the midpoint for simplicity.. Context: The lookup table is the bulk of the marching cubes code and avoids runtime geometric computation."}, {"id": "gk_384", "t": "planet_noise", "text": "[PLANET_NOISE] Planet terrain generated by starting with a sphere, sampling a 3D noise function at each surface point, and displacing vertices inward/outward based on the noise value. Mixing and layering different noise functions with different equations produces varied terrain.. Context: Traditional approach before switching to volumetric marching cubes for cave support."}, {"id": "gk_385", "t": "underground_tunnel", "text": "[UNDERGROUND_TUNNEL] Sewer tunnel used as connection path between two building basements; requires blocking out geometry for arch-shaped ceiling and snapping vertices to grid for proper alignment. Context: Artist blocks out an old sewer system tunnel connecting two buildings underground, using grid snapping for vertex placement"}, {"id": "gk_386", "t": "environmental_storytelling", "text": "[ENVIRONMENTAL_STORYTELLING] Sand pouring through drainage grates serves dual purpose: visual storytelling element showing surface proximity and gameplay mechanic providing player entry path into underground space. Context: Sand flowing in through drainage pads is used as both art detail and the mechanism for players to access the underground area"}, {"id": "gk_387", "t": "lighting_underground", "text": "[LIGHTING_UNDERGROUND] Underground spaces require blocking out additional light to sell the illusion of depth; too much ambient light leaking into basement/tunnel areas breaks the underground feel. Context: Artist notes needing to block out more light because too much is still getting into the underground boarded-up area"}, {"id": "gk_388", "t": "modular_level_design", "text": "[MODULAR_LEVEL_DESIGN] Plank boards placed over openings need careful overlap management to avoid z-fighting; thicker board geometry matches concept art and helps sell light occlusion at surface boundaries. Context: Manually placed planks over an opening required work to prevent overlapping, with board thickness affecting how much light bleeds through"}, {"id": "gk_389", "t": "tunnel_geometry", "text": "[TUNNEL_GEOMETRY] Arch-shaped tunnel ceilings require additional subdivided geometry (more geo on the plane) to achieve smooth curved profiles; vertices must sit below the arch curve line to avoid clipping. Context: Artist adds more geometry to a plane to make the tunnel arch flow nicely, checking that edge vertices are lower than the ceiling arch"}, {"id": "gk_390", "t": "depth_cue_sightlines", "text": "[DEPTH_CUE_SIGHTLINES] Partial visibility through bars/grates into adjacent spaces creates depth cues and player curiosity; the actual traversal path routes through a different building to reach the visible space. Context: Player can see through bars into the tunnel area but must find an alternate route through a building basement and cellar room to access it"}, {"id": "gk_391", "t": "isometric_workflow", "text": "[ISOMETRIC_WORKFLOW] For isometric 3D levels, start with a 2D sketch/map before creating a 3D blockout (simple walls, floors, ceilings) in Blender using cube with inverted normals and Ctrl+R loop cuts to extrude walls and cut windows.. Context: Blockout-first approach ensures spatial layout is correct before adding detail to an isometric scene."}, {"id": "gk_392", "t": "isometric_workflow", "text": "[ISOMETRIC_WORKFLOW] Blender .blend files can be imported directly into Unity without FBX export; Ctrl+S in Blender or Photoshop triggers a live update in Unity, enabling a non-destructive back-and-forth workflow.. Context: Eliminates export steps for isometric scene iteration between modeling and engine."}, {"id": "gk_393", "t": "isometric_workflow", "text": "[ISOMETRIC_WORKFLOW] Adding small knife-tool cuts on top of simple boxy meshes makes low-poly stylized art look handmade and intentional, useful for isometric game assets that read well at camera distance.. Context: Surface detail trick for stylized isometric 3D art without increasing geometric complexity significantly."}, {"id": "gk_394", "t": "isometric_workflow", "text": "[ISOMETRIC_WORKFLOW] Toon/cel shaders (e.g. Toony Colors Pro 2) strip specular, metallic, and normal map complexity, giving isometric scenes a flat stylized look that pairs well with simple geometry and solid color palettes.. Context: Shader choice directly affects the visual cohesion of low-poly isometric scenes."}, {"id": "gk_395", "t": "isometric_workflow", "text": "[ISOMETRIC_WORKFLOW] Complex isometric scene objects decompose into primitive shapes: couches = squashed rectangles, tables = squashed cylinders, trees = stacked cones, characters = ovals \u2014 all colored via simple flat material assignments in Blender.. Context: Primitive-based modeling keeps poly counts low and reads clearly at isometric camera angles."}, {"id": "gk_396", "t": "city", "text": "[CITY] Road presets include lane configurations with sidewalk variants (e.g., 'two lane + sidewalks'); roads auto-align to landscape with configurable elevation offset and landscape layer masking (e.g., grass removal under roads).. Context: CDBL plugin provides preset-based road drawing with landscape integration and per-layer material masking."}, {"id": "gk_397", "t": "city", "text": "[CITY] Road drawing uses click-to-place nodes for straight segments; holding Shift creates curved segments; middle mouse wheel adjusts elevation in real-time to create bridges and overpasses.. Context: Interactive road tool supports curves and elevation changes via modifier keys during draw mode."}, {"id": "gk_398", "t": "city", "text": "[CITY] City kits are swappable asset packs (e.g., 'Modern City', 'Miami Bass') added to a level with one click; custom kits can be created with user-provided meshes and styles.. Context: Kit system decouples city style from placement logic, enabling modular art pipeline."}, {"id": "gk_399", "t": "city", "text": "[CITY] Blocks (building zones) are generated using a 'from edges' tool that automatically detects valid buildable areas by analyzing road edge geometry.. Context: Block placement is derived from road network topology rather than manual definition."}, {"id": "gk_400", "t": "city", "text": "[CITY] Plugin operates as a custom Editor Mode (Selection Mode > City Builder) with dedicated widget tabs for General, Roads, and Blocks, plus a simplified game-style UI toggle in settings.. Context: CDBL integrates into Unreal's editor mode system with a City Skylines-inspired simplified UI option."}, {"id": "gk_401", "t": "city", "text": "[CITY] Building props use a struct called 'prop spline points' storing 5 local points that generate a spline path around the building perimeter for fence/edge placement.. Context: The procedural city generator uses spline points defined per building blueprint to control where perimeter props like fences spawn."}, {"id": "gk_402", "t": "city", "text": "[CITY] Spline mesh props use two mesh variants: a 'complete mesh' (both sides, used for the last segment) and an 'incomplete mesh' (one side, used for all other segments), with configurable mesh width, tangent length for curvature, and begin/end scale.. Context: This dual-mesh approach ensures clean termination of repeating fence/wall elements along building perimeters."}, {"id": "gk_403", "t": "city", "text": "[CITY] Spline mesh props have a configurable 'percent chance to spawn' (default 75% for fences), a tangent length controlling curvature, and support random material selection from a material list.. Context: Randomized spawn chance and materials add visual variety to procedurally generated building perimeters."}, {"id": "gk_404", "t": "city", "text": "[CITY] Edge props are individually placed along the building perimeter spline with configurable prop spacing, collision bounds, scale range, rotation, random yaw, and two-tier spawn probability: a global chance (e.g. 20% for pine trees on a house) and per-instance chance (e.g. 100% for each tree if global passes).. Context: The two-tier probability system controls both whether a building type gets edge props at all and the density of individual prop instances."}, {"id": "gk_405", "t": "city", "text": "[CITY] Road props support spline and edge prop types with specific 'curves and segment settings' unique to roads, and all prop configurations can be loaded from a data table.. Context: Data tables allow bulk configuration of prop parameters across the procedural city generator rather than per-instance setup."}, {"id": "gk_406", "t": "city", "text": "[CITY] City grid size is controlled by X size and Z size parameters; setting both to 5 with scale 25 creates a walkable city block, while 20x20 at scale 200 generates a full city-scale layout. Context: Oasis Builder Unity tool uses X/Z size params to define the procedural city footprint on a grid"}, {"id": "gk_407", "t": "city", "text": "[CITY] Vertex snapping (V key) is used to align building pieces and prefabs to each other precisely when manually editing the generated city. Context: Unity's vertex snap shortcut allows precise placement of modular city pieces after procedural generation"}, {"id": "gk_408", "t": "city", "text": "[CITY] Generated city buildings are composed of individually editable modular pieces (walls, doors, flags) that can be deleted or repositioned post-generation. Context: The procedural city output is not a single monolithic mesh but a hierarchy of selectable prefab parts"}, {"id": "gk_409", "t": "city", "text": "[CITY] City builder prefab is placed at origin (0,0,0) with initial scale 1,1,1 then scaled up (e.g. 25) to match the terrain size. Context: Proper placement requires centering the generator at world origin and scaling to fit the ground plane"}, {"id": "gk_410", "t": "city", "text": "[CITY] Global volume prefab from postprocesses folder is added for depth/lighting; environment skybox color is customized via Window > Rendering > Lighting panel. Context: Post-processing and lighting setup is done before city generation to preview the environment correctly"}, {"id": "gk_411", "t": "city", "text": "[CITY] The tool supports multiple building variations that are randomly selected during generation, providing visual variety across the city grid. Context: Procedural city generators cycle through prefab variations to avoid repetitive appearance in large layouts"}, {"id": "gk_412", "t": "city", "text": "[CITY] Road prefabs use a grid step of 38 units for discrete movement, ensuring no gaps form between road segments when snapping. Context: The suffix 38 in the road constructor folder name denotes the grid step size used for precise prefab alignment."}, {"id": "gk_413", "t": "city", "text": "[CITY] Road system height is set to 8.6 units and kept consistent across the entire road network. Context: The L-crossroads prefab height is set to 8.6 units as the standard elevation for all road segments."}, {"id": "gk_414", "t": "city", "text": "[CITY] Building block prefabs maintain constant pixel density, border geometry height, and window/floor sizes regardless of shape changes, allowing seamless assembly without UV adjustments. Context: Modular building prefabs can be combined without changing scale and the result looks seamless with consistent detail density."}, {"id": "gk_415", "t": "city", "text": "[CITY] Vertex snapping (V key) is used to precisely connect block prefabs to road edges by dragging outermost vertices together. Context: Gaps between roads are closed with block prefabs aligned using Unity's vertex snap tool for precise placement."}, {"id": "gk_416", "t": "city", "text": "[CITY] Two constructor systems are used: road constructor (Sci-Fi Road Constructor 38 inches folder) and city constructor (Sci-Fi City folder), each containing pre-configured prefabs. Context: The modular kit separates road and building construction into two distinct prefab-based systems."}, {"id": "gk_417", "t": "city", "text": "[CITY] Linear fog is used for optimization where camera clipping planes far distance and shadow distance match the fog range, and prefabs are marked static to avoid per-frame transforms at runtime. Context: Performance optimization techniques include fog-based culling alignment and static batching of placed prefabs."}, {"id": "gk_418", "t": "subscene_streaming", "text": "[SUBSCENE_STREAMING] Volume-based subscene loading uses two nested volumes: an outer 'preparation' volume for pre-loading scene data into memory, and an inner 'activation' volume that triggers the actual scene load. The activation volume must always be inside the preparation volume or the scene will not load.. Context: Two-phase load system where preparation handles memory pre-loading for performance before activation triggers the visible scene."}, {"id": "gk_419", "t": "subscene_unloading", "text": "[SUBSCENE_UNLOADING] Unload volumes are separate red-box trigger zones placed at exits. By changing 'amount of volumes' and setting type from 'load volume' to 'unload volume', a dedicated unload trigger is created that removes the subscene when the player passes through it.. Context: Explicit unload volumes give designers precise control over when subscenes are removed from memory at exit points."}, {"id": "gk_420", "t": "distance_based_loading", "text": "[DISTANCE_BASED_LOADING] Distance-based subscene loading uses a radius from center: the subscene loads when the player enters the range and automatically unloads when the player exits the range. Unlike volume-based loading, there is no separate pre-loading phase, making it optimal only for smaller subscenes.. Context: Simpler alternative to volume-based loading that trades pre-loading capability for ease of setup on small scenes."}, {"id": "gk_421", "t": "subscene_streaming", "text": "[SUBSCENE_STREAMING] Volume-based loading is configured by setting 'subscene loading mode' to 'volume based' in map settings via the subscene cogwheel icon, then setting 'amount of volumes' to define how many load/unload trigger zones exist per subscene.. Context: Configuration workflow in Unity for setting up volume-based subscene streaming."}, {"id": "gk_422", "t": "level_chunk_tooling", "text": "[LEVEL_CHUNK_TOOLING] An eye icon toggle allows hiding subscene geometry so designers can clearly see and position load/unload volumes or distance-based loaders without visual obstruction from the scene content itself.. Context: Editor UX feature for precise placement of streaming trigger volumes."}, {"id": "gk_423", "t": "subscene_streaming", "text": "[SUBSCENE_STREAMING] Renaming a subscene automatically updates all associated load/unload volumes to reflect the new name, and renaming an entire map triggers a scene reload but preserves all volume configurations. No data is lost during rename operations.. Context: Robust rename propagation prevents broken references when reorganizing streaming subscenes."}, {"id": "gk_424", "t": "uv_unwrap", "text": "[UV_UNWRAP] Always apply scale (Ctrl+A > Scale) before unwrapping; unapplied scale skews UV proportions, distorting texture density across the mesh.. Context: Blender applies the object's transform scale to the UV layout if not applied first, causing non-uniform texel density."}, {"id": "gk_425", "t": "uv_unwrap", "text": "[UV_UNWRAP] Use 'Project from View' (UV menu > 3D View > Project from View) as a clean-slate reset before marking seams, to eliminate inherited UV islands and seam artifacts from the modeling process.. Context: Modeling operations leave residual UV data that can corrupt the unwrap; projecting from view zeroes out that state."}, {"id": "gk_426", "t": "uv_seam_placement", "text": "[UV_SEAM_PLACEMENT] UV seams should prioritize minimizing distortion over minimizing seam count; place seams at natural geometry breaks (like clothing stitches or material boundaries) rather than trying to reduce them.. Context: The outdated rule of 'minimize seams' leads to higher distortion; modern texturing tools and triplanar mapping can paint over visible seams."}, {"id": "gk_427", "t": "uv_unwrap", "text": "[UV_UNWRAP] 4-step UV workflow: (1) apply scale, (2) project UVs from view, (3) mark seams on edges using Edge mode (press 2) with Alt+Click for edge loops and Ctrl+Click for edge paths, (4) select all faces and unwrap.. Context: Standardized pipeline ensures clean, predictable UV islands suitable for texture atlasing and consistent texel density."}, {"id": "gk_428", "t": "uv_seam_placement", "text": "[UV_SEAM_PLACEMENT] Triplanar mapping can blend across UV seams for procedural materials, reducing visible seam artifacts without manual texture painting, but should not replace proper unwrapping (avoid relying on cube projection alone).. Context: Useful for interior walls and floors using procedural textures where seam hiding is needed at material boundaries."}, {"id": "gk_429", "t": "uv_unwrap", "text": "[UV_UNWRAP] Clean topology with proper edge flow enables Alt+Click loop selection and Ctrl+Click path selection for fast seam marking; poor topology breaks these selection tools and complicates unwrapping.. Context: For interior geometry like walls and floors, maintaining quad-based topology ensures edge loops align with natural seam locations at corners and material transitions."}, {"id": "gk_430", "t": "world_generation", "text": "[WORLD_GENERATION] Gaia world generation uses a 4-step pipeline: 1) Create World Designer in Gaia Manager, 2) Generate world (stamps island onto terrain), 3) Spawn biomes, 4) Create runtime \u2014 producing a fully populated island. Context: Gaia is a Unity terrain tool that automates terrain stamping, biome placement, and runtime setup in 4 clicks"}, {"id": "gk_431", "t": "terrain", "text": "[TERRAIN] Gaia stamps pre-generated island heightmaps directly onto Unity terrain, separating world shape generation from biome population. Context: The terrain stamping step creates the base landform before any vegetation or object spawning occurs"}, {"id": "gk_432", "t": "biome_placement", "text": "[BIOME_PLACEMENT] Biome spawning is a distinct automated step that populates terrain with vegetation, textures, and objects after the base terrain is stamped. Context: Gaia decouples terrain generation from biome population, allowing one-click biome spawning onto existing terrain"}, {"id": "gk_433", "t": "world_generation", "text": "[WORLD_GENERATION] Gaia uses a runtime creation step as the final phase, converting the designed world into a playable game-ready environment. Context: The runtime step finalizes the world so it can be used in-game with proper loading and rendering"}, {"id": "gk_434", "t": "pathfinding", "text": "[PATHFINDING] Unity's 3D NavMesh can be repurposed for 2D pathfinding by forcing it into a 2D scaling, avoiding the need to implement A* from scratch.. Context: A GitHub package adapts Unity's built-in 3D NavMesh system to work in 2D game environments."}, {"id": "gk_435", "t": "pathfinding", "text": "[PATHFINDING] A* pathfinding is the traditional algorithm used for 2D pathfinding when no built-in navigation system is available.. Context: Before NavMesh-based shortcuts, 2D games typically required manual A* implementation for pathfinding."}, {"id": "gk_436", "t": "navigation_mesh", "text": "[NAVIGATION_MESH] Unity's NavMesh is natively a 3D system; 2D pathfinding requires either a wrapper/adapter package or a custom A* implementation.. Context: The video demonstrates a third-party package that bridges Unity's 3D NavMesh for use in 2D tile-based environments."}, {"id": "gk_437", "t": "pathfinding", "text": "[PATHFINDING] For 2D NavMesh pathfinding in Unity, the environment is built using tilemaps with separate layers for ground and walls to define walkable vs non-walkable areas.. Context: A 'ground' tilemap and a 'walls' tilemap are created as 2D objects to define navigation boundaries."}, {"id": "gk_438", "t": "ai", "text": "[AI] Enemy state machine uses idle and pursuing states; idle transitions to pursuing when player distance is within search radius AND line-of-sight is true. Context: Basic enemy AI built from scratch with two core states and distance-based detection gated by LOS checks"}, {"id": "gk_439", "t": "ai", "text": "[AI] Line-of-sight (LOS) is checked by calculating the line between enemy and player, then iteratively performing small circular obstacle queries along that line; if the sweep reaches the player unblocked, LOS is true. Context: Iterative raycasting alternative using circular queries prevents enemies from seeing or attacking through walls"}, {"id": "gk_440", "t": "ai", "text": "[AI] Pursuit steering uses a direction vector calculated as (player.position - enemy.position).normalize() to always angle movement toward the player. Context: Simplest pursuit approach that works in open areas but fails when obstacles are present, causing stuck or phasing behavior"}, {"id": "gk_441", "t": "ai", "text": "[AI] When LOS is lost during pursuing state, a naive fix is to revert to idle, but this causes enemies to give up at corners; a tile-tracking solution assigns pathfinding data to tiles around the player to guide enemies without direct LOS. Context: Tile tracking allows enemies to navigate around corners toward the player's last known or predicted position"}, {"id": "gk_442", "t": "ai", "text": "[AI] Distance-radius detection alone lets enemies detect through walls; combining radius check with LOS check fixes wall-penetrating detection so enemies only react when they can actually see the player. Context: Layered detection system prevents unrealistic behavior where enemies sense the player through solid obstacles"}, {"id": "gk_443", "t": "ai", "text": "[AI] State transitions follow the pattern: idle\u2192pursuing (distance < searchRadius AND LOS==true), pursuing\u2192idle (LOS==false as naive fallback), with LOS gating attack actions within pursuing state. Context: Simple two-state FSM with LOS-gated transitions forms the backbone before adding pathfinding for smarter navigation"}, {"id": "gk_444", "t": "navigation_mesh", "text": "[NAVIGATION_MESH] NavMeshAgent jitter when camera moves can be fixed by disabling automatic position updates (agent.updatePosition = false) in Awake, then manually updating transform.position using Vector3.SmoothDamp in FixedUpdate instead of letting the agent control position directly.. Context: Unity NavMeshAgent characters appear jittery during camera movement; manually smoothing position via SmoothDamp eliminates the visual artifact."}, {"id": "gk_445", "t": "steering", "text": "[STEERING] Vector3.SmoothDamp provides velocity-based smooth interpolation for character movement, producing smoother results than directly applying NavMeshAgent position updates each frame.. Context: SmoothDamp acts as a steering smoothing layer on top of pathfinding output to eliminate jerky motion."}, {"id": "gk_446", "t": "navigation_mesh", "text": "[NAVIGATION_MESH] Movement code for NavMeshAgents should run in FixedUpdate (fixed timestep) rather than Update (variable timestep) when manually controlling transform.position for consistent physics-rate smoothing.. Context: Using FixedUpdate ensures movement calculations happen at a fixed rate, reducing frame-dependent jitter."}, {"id": "gk_447", "t": "animation", "text": "[ANIMATION] Unity animator layers allow splitting animation control by body region \u2014 e.g., a 'base layer' for lower body (legs/locomotion) and an 'upper layer' for upper body (attack/aim), so two animations play simultaneously on different body parts.. Context: Demonstrates how to make a character sprint and attack at the same time by assigning each action to a separate animator layer."}, {"id": "gk_448", "t": "animation", "text": "[ANIMATION] Unity Avatar Masks define which bones/body parts a layer controls, allowing you to disregard portions of an animation (e.g., exclude legs from an attack clip so only the upper body plays the swing while legs continue the walk cycle).. Context: An Avatar Mask is created and assigned to the upper layer to isolate upper-body attack animations from lower-body locomotion."}, {"id": "gk_449", "t": "animation", "text": "[ANIMATION] Animator state machines use boolean parameters (e.g., 'isMoving') for sustained state transitions (idle\u2194sprint) and trigger parameters (e.g., 'attack') for one-shot action transitions, with conditions evaluated on each transition arrow.. Context: A simple three-state graph (Idle, Sprint, Attack) uses a bool for locomotion toggling and a trigger for the attack action."}, {"id": "gk_450", "t": "animation", "text": "[ANIMATION] Without layer-based blending, playing an attack animation interrupts locomotion entirely \u2014 the character stops moving, plays the full attack clip, then resumes walking, creating a visually jarring break in movement.. Context: This is the problem that multi-layer animation blending with avatar masks solves in Unity's Mecanim system."}, {"id": "gk_451", "t": "animation", "text": "[ANIMATION] Each Unity animator layer can have its own independent state machine with states and transitions, enabling parallel animation logic (e.g., upper body can be in 'Attack' state while base layer is in 'Sprint' state simultaneously).. Context: The upper layer gets its own set of animation states that run concurrently with the base layer's locomotion states."}, {"id": "gk_452", "t": "blend_tree", "text": "[BLEND_TREE] A blend tree adaptively changes the transition between two animation states based on input parameters, preventing the delayed or abrupt animations that occur with fixed-duration state machine transitions.. Context: When start/stop inputs are faster than a fixed transition duration, animations lag behind; blend trees solve this by interpolating states proportionally to input values like velocity."}, {"id": "gk_453", "t": "blend_tree_setup", "text": "[BLEND_TREE_SETUP] A 2D Free Form Directional blend type maps animations onto a 2D parameter space using velocityX and velocityY, where idle=(0,0), run_forward=(0,0.5), and sprint=(0,1.0).. Context: Each motion in the blend tree is positioned in a 2D space corresponding to player velocity direction and magnitude, allowing smooth interpolation between idle, walk, run, and sprint."}, {"id": "gk_454", "t": "state_machine_transition", "text": "[STATE_MACHINE_TRANSITION] State machine transitions use smooth interpolation between two states, but faster transitions reduce smoothness while slower transitions cause animation delay when inputs change rapidly.. Context: This fundamental tradeoff between transition speed and smoothness is the core problem that blend trees were designed to solve."}, {"id": "gk_455", "t": "blend_tree_architecture", "text": "[BLEND_TREE_ARCHITECTURE] Blend trees can replace multiple discrete state transitions; instead of defining boolean-triggered transitions between every animation pair, a single blend tree node handles all locomotion states with continuous parameter control.. Context: Rather than creating individual states with boolean conditions for idle, walk, run, and sprint, all locomotion animations are grouped into one blend tree controlled by velocity parameters."}, {"id": "gk_456", "t": "blend_tree_layering", "text": "[BLEND_TREE_LAYERING] Additional hard transitions can still be layered on top of blend tree states for actions like direction switching or sprint stopping, combining blend tree smoothness with discrete state changes.. Context: Honkai Star Rail demonstrates this hybrid approach where locomotion uses a blend tree but direction changes and sprint stops use layered transitions to/from blend tree states."}, {"id": "gk_457", "t": "animator_controller", "text": "[ANIMATOR_CONTROLLER] Unity's animator controller uses an Entry node that transitions to a default state; blend trees are created as named nodes (e.g., 'player Locomotion') that replace individual animation states in the state machine graph.. Context: The animator window visually represents the state machine where blend trees appear as single nodes that internally contain multiple weighted animations."}, {"id": "gk_458", "t": "animation", "text": "[ANIMATION] Motion matching dynamically selects animation frames from a database by analyzing character state, speed, and direction, replacing traditional blend trees and state machines for more fluid movement.. Context: Unreal Engine's motion matching system uses algorithms to find the best animation clip match rather than manually defined transitions."}, {"id": "gk_459", "t": "animation", "text": "[ANIMATION] Traditional UE animation systems use blend trees and state machines with manually defined transitions based on parameters like speed, direction, and states (idle, walking, jumping), requiring extensive setup and fine-tuning.. Context: Animation graphs with blend trees interpolate between animations similarly to Unity's animator system."}, {"id": "gk_460", "t": "animation", "text": "[ANIMATION] Motion matching requires configuring pose search schemas, databases, and choosers, plus detailed animation samples with root motion for every action the character needs to perform.. Context: Despite its premise of simplicity, motion matching demands significant setup and high-quality root motion animation data."}, {"id": "gk_461", "t": "animation", "text": "[ANIMATION] Orientation warping and other nodes from the Game Animation Sample (GAS) can be used independently within traditional animation graphs and state machines without adopting full motion matching.. Context: Developers can selectively adopt newer animation techniques while keeping a traditional state machine architecture."}, {"id": "gk_462", "t": "animation", "text": "[ANIMATION] For solo or small-team developers wanting full control, traditional animation graphs and state machines are recommended over motion matching due to the complexity and time investment motion matching requires.. Context: Motion matching is better suited for larger teams where a dedicated person can manage the animation system's details."}, {"id": "gk_463", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] Inverse kinematics calculates the rotation of all bones in a chain from the tip bone's position, while forward kinematics calculates the tip bone position from the rotation of all other bones in the chain.. Context: Core IK concept explaining why IK is useful for aligning hands/feet to terrain or objects."}, {"id": "gk_464", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] Two Bone IK constraint is used for anatomically correct characters with standard joint chains (e.g., arm: root=upper_arm, mid=forearm, tip=hand), while Chain IK is used for characters with more bones like rubber-hose style rigs.. Context: Choosing the correct IK solver type depends on the number of bones in the character's limb chain."}, {"id": "gk_465", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] Two Bone IK constraint requires three bone references: root (upper arm), mid (forearm), and tip (hand), plus two source objects: a target (controls position/rotation) and a hint (controls elbow direction).. Context: Unity Animation Rigging package setup for hand IK using the Two Bone IK Constraint component."}, {"id": "gk_466", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] The IK constraint weight parameter (0-1) controls how much the rig is affected by the constraint; setting weight to 1 means full IK control, and dynamically changing weight in code allows switching between multiple IK rigs (e.g., hand-on-object vs hand-on-terrain).. Context: Weight blending enables smooth transitions between different IK targets at runtime."}, {"id": "gk_467", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] The 'auto setup from tip's transform' option in Unity's Animation Rigging automatically creates target and hint game objects for the IK constraint, positioned relative to the tip bone.. Context: Shortcut for setting up IK source objects without manually creating and positioning them."}, {"id": "gk_468", "t": "inverse_kinematics", "text": "[INVERSE_KINEMATICS] The IK target object should be aligned to the hand bone's transform using 'align transform' (select target then ctrl+click hand), and a rig setup requires both a Bone Renderer (for bone visualization/selection) and a Rig component as parent of IK constraints.. Context: Proper setup hierarchy: character > rig component > IK constraint objects with aligned targets."}, {"id": "gk_469", "t": "animation", "text": "[ANIMATION] Attack combos use an Animation Montage array variable on the Third Person Blueprint, sized to the number of combo attacks (e.g., 3), with each montage assigned to a corresponding array index.. Context: Setting up a multi-hit melee combo system in Unreal Engine 5 using Blueprints."}, {"id": "gk_470", "t": "animation", "text": "[ANIMATION] A boolean variable tracks whether the character is currently in an attack animation, and a separate integer variable tracks the current attack index in the combo array to sequence through montages.. Context: State tracking for combo system uses two variables: an is-attacking bool and a current-attack-index int."}, {"id": "gk_471", "t": "animation", "text": "[ANIMATION] Play Montage node (not Play Animation Montage) is used with the skeletal mesh component; it checks the attack bool before playing and resets it on montage end via the On Completed callback.. Context: The Play Montage node provides completion callbacks needed for combo state transitions."}, {"id": "gk_472", "t": "animation", "text": "[ANIMATION] Combo progression logic increments the attack index each attack; if the index reaches the array length the combo resets to index 0, otherwise it advances to the next montage in the array.. Context: Simple modular combo state machine using array bounds checking to loop or advance."}, {"id": "gk_473", "t": "animation", "text": "[ANIMATION] Input buffering for combos is implemented by adding an Anim Notify named 'CanAttack' at a specific frame in each Animation Montage, marking the earliest point the player can queue the next attack.. Context: Anim Notifies placed per-montage control the combo input window timing for responsive feel."}, {"id": "gk_474", "t": "animation", "text": "[ANIMATION] In the Animation Blueprint (ABP) Event Graph, the CanAttack Anim Notify is received, cast to the Third Person Character, and sets the attack boolean to false \u2014 reopening the input window for the next combo hit.. Context: The ABP listens for the custom notify to transition combo state by unlocking the attack gate."}, {"id": "gk_475", "t": "animation", "text": "[ANIMATION] Animation Rigging creates a secondary rig layer that overrides specific bones of the original animation at runtime, allowing dynamic control without modifying the base animation clip.. Context: Unity's Animation Rigging package enables runtime bone overrides via constraint-based rigs layered on top of the animator-driven skeleton."}, {"id": "gk_476", "t": "animation", "text": "[ANIMATION] Character animation pipeline follows three steps: animator determines which animation plays, bones are moved by that animation, then the Skinned Mesh Renderer deforms the mesh to follow the bones.. Context: Unity's animation system chains Animator \u2192 bone transforms \u2192 Skinned Mesh Renderer to produce final character visuals each frame."}, {"id": "gk_477", "t": "IK", "text": "[IK] The Multi Aim Constraint references a target bone (e.g., head) and a target transform object, overriding that bone's rotation at runtime to track the target while the base animation continues playing.. Context: Multi Aim Constraint is one of several constraint types in Animation Rigging used for look-at behavior and aiming without baking directions into animation clips."}, {"id": "gk_478", "t": "animation", "text": "[ANIMATION] The character skeleton (rig) is a hierarchy of GameObjects representing bones: pelvis \u2192 spine \u2192 thigh \u2192 calf \u2192 foot, stored as children of the base object alongside the mesh.. Context: Unity represents skeletal rigs as nested GameObjects so each bone is individually addressable for constraints, IK, and runtime manipulation."}, {"id": "gk_479", "t": "animation", "text": "[ANIMATION] A standard animated character in Unity consists of three parts: a base GameObject with an Animator component, a child mesh with a Skinned Mesh Renderer, and a bone hierarchy (rig) as child GameObjects.. Context: This three-part structure (Animator, Skinned Mesh Renderer, bone hierarchy) is the foundation for all skeletal animation and rigging workflows in Unity."}, {"id": "gk_480", "t": "animation", "text": "[ANIMATION] Animation Rigging constraints allow runtime interaction (picking up objects, aiming, placing hands/feet on environment) by overriding specific bones without requiring pre-baked animation clips for every scenario.. Context: Constraint-based rigging solves the problem of fixed animations not fitting dynamic game interactions like variable object positions or player-relative aiming."}, {"id": "gk_481", "t": "root_motion", "text": "[ROOT_MOTION] Root motion glues the capsule collision to the character mesh for the duration of an animation, preventing the character from moving outside the capsule collision during attacks or movements.. Context: Core definition of root motion and its purpose in Unreal Engine character movement."}, {"id": "gk_482", "t": "root_motion", "text": "[ROOT_MOTION] Root motion requires the character to be moved by the root bone in the source animation; in Blender, ensure the root bone drives all character translation.. Context: Authoring requirement for root motion animations in 3D modeling software."}, {"id": "gk_483", "t": "root_motion", "text": "[ROOT_MOTION] In Unreal Engine, enable root motion by selecting the animation asset, searching 'root' in the detail section, and ticking 'Enable Root Motion'. A red line from center point to character in viewport (Character > Bones > All Hierarchy) confirms root bone movement is present.. Context: Step-by-step activation and visual verification of root motion in Unreal Editor."}, {"id": "gk_484", "t": "root_motion", "text": "[ROOT_MOTION] If the character moves into a funny angle when root motion is enabled, set 'Root Motion Root Lock' to 'Anim First Frame' to fix orientation issues.. Context: Common troubleshooting fix for root motion rotation/angle problems."}, {"id": "gk_485", "t": "animation_montage", "text": "[ANIMATION_MONTAGE] To use root motion at runtime, convert the root motion animation to a Montage (right-click animation in Content Browser > Convert to Montage), then play the Montage from the character blueprint. A default slot must be configured in the Animation Blueprint.. Context: Runtime playback pipeline for root motion via Montage system in Unreal Engine."}, {"id": "gk_486", "t": "root_motion", "text": "[ROOT_MOTION] Root motion is recommended for specific actions like weapon attacks rather than basic locomotion (walk/run), since standard capsule-driven movement is more appropriate for general movement.. Context: Best practice guidance on when to use root motion vs standard movement."}, {"id": "gk_487", "t": "state_machine", "text": "[STATE_MACHINE] A start-to-walk and walk-to-stop system can be built entirely in the animation blueprint using state machines, without needing to play montages manually.. Context: Unreal Engine 5 locomotion system using root motion for walk start/stop transitions handled via animation blueprint states and transition rules."}, {"id": "gk_488", "t": "root_motion", "text": "[ROOT_MOTION] The start-to-walk animation requires root motion enabled so the animation itself drives the character's forward movement when transitioning from idle to walking.. Context: Root motion is used specifically on the start-to-walk clip so the character physically moves forward during the transition rather than sliding."}, {"id": "gk_489", "t": "state_machine", "text": "[STATE_MACHINE] A boolean variable 'has_movement_input' is set true on key press and false on key release (WASD), and is used as the primary transition condition between idle, walk-start, walking, and walk-stop states.. Context: The input action trigger sets has_movement_input to drive state transitions in the animation blueprint without montage calls."}, {"id": "gk_490", "t": "transition", "text": "[TRANSITION] Eight directional movement possibilities exist (forward, back, left, right, and four diagonals), each requiring a unique start-to-walk animation and direction calculation to select the correct transition.. Context: Strafing and directional locomotion requires calculating the player's current movement direction and mapping it to one of eight animation sets."}, {"id": "gk_491", "t": "state_machine", "text": "[STATE_MACHINE] State machine complexity for directional locomotion can be reduced by using variables inside states and state transition rules rather than duplicating logic across many transition lines.. Context: Adding variables within states helps consolidate transition rules when scaling from simple forward walk to full 8-directional movement with run variants."}, {"id": "gk_492", "t": "transition", "text": "[TRANSITION] A quick tap of the movement key triggers both start-to-walk and walk-to-stop animations in rapid sequence, requiring the state machine to handle very short input durations gracefully.. Context: Tapping W briefly plays the walk-start then immediately transitions to walk-stop, demonstrating that transition rules must react to fast input changes."}, {"id": "gk_493", "t": "root_motion", "text": "[ROOT_MOTION] Enable root motion for start/stop locomotion animations by bulk editing via Property Matrix: check 'Enable Root Motion' and 'Force Root Lock' on all start/stop animation assets.. Context: Configuring start and stop locomotion animations to use root motion in Unreal Engine 5."}, {"id": "gk_494", "t": "state_machine", "text": "[STATE_MACHINE] Locomotion state machine uses three distinct states for directional movement: Movement Start, Cycle (looping walk/jog), and Stop, each requiring their own orientation warping node configuration.. Context: Animation blueprint state machine structure for start-cycle-stop locomotion pattern."}, {"id": "gk_495", "t": "animation", "text": "[ANIMATION] Orientation warping nodes require spine bone references matching the target skeleton; UE5 mannequin has 5 spine bones while UE4 mannequin has 3, causing errors when retargeting that must be fixed by deleting and re-adding the correct spine bone count.. Context: Fixing orientation warping errors after retargeting animation blueprints between skeletons with different bone counts."}, {"id": "gk_496", "t": "animation", "text": "[ANIMATION] Start and stop animations are created per direction (forward, backward, left, right) as separate assets, paired with corresponding cycle (looping) animations for each movement direction.. Context: Asset organization for directional locomotion start/stop system."}, {"id": "gk_497", "t": "animation", "text": "[ANIMATION] Retargeting an animation blueprint via 'Retarget Animation Assets > Duplicate and Retarget Animation Blueprint' automatically retargets all animations already slotted in the animation blueprint's state machine groupings.. Context: Workflow for porting an animation blueprint from UE5 mannequin to UE4 or custom skeleton."}, {"id": "gk_498", "t": "animation", "text": "[ANIMATION] Orientation warping nodes must be configured in every state of the locomotion state machine (start, cycle, stop); missing or misconfigured nodes cause the character to face forward regardless of movement direction.. Context: Debugging orientation warping failures after skeleton retargeting."}, {"id": "gk_499", "t": "animation_blend_tree", "text": "[ANIMATION_BLEND_TREE] In Godot 4, an AnimationTree node with a BlendTree root allows smooth transitions between animations by using Blend2 nodes, where a blend_amount value of 0.0 means fully first animation and 1.0 means fully second animation.. Context: Setting up an AnimationTree with blend nodes to replace snapping animation switches with smooth interpolated transitions."}, {"id": "gk_500", "t": "state_machine_blend", "text": "[STATE_MACHINE_BLEND] Multiple Blend2 nodes can be chained in series (idle\u2192run\u2192sit\u2192jump\u2192output) so that whichever blend value is highest transitions from the base idle pose to that animation, with all-zero values passing idle through every blend.. Context: Chaining Blend2 nodes creates an implicit priority system where idle is the default fallback state requiring no dedicated blend value."}, {"id": "gk_501", "t": "animation_transition", "text": "[ANIMATION_TRANSITION] Smooth blending between animation states is achieved by interpolating blend values using lerp_f(current_value, target, blend_speed * delta), with a typical blend_speed of 15 providing responsive transitions.. Context: Using linear interpolation per frame with delta-scaled blend speed ensures framerate-independent smooth animation transitions."}, {"id": "gk_502", "t": "animation_blend_tree", "text": "[ANIMATION_BLEND_TREE] AnimationTree blend parameters are set via anim_tree.set('parameters/<blend_node_name>/blend_amount', value), where blend node names like 'run', 'jump', 'sitting' correspond to the named Blend2 nodes in the tree.. Context: The parameter path mirrors the node hierarchy in the AnimationTree editor, accessible under the parameters dropdown."}, {"id": "gk_503", "t": "state_machine", "text": "[STATE_MACHINE] An enum defining states (IDLE, RUN, SIT, JUMP) combined with a current_animation variable drives a switch statement in handle_animations(delta) that determines which blend values to lerp toward 1.0 or 0.0 each frame.. Context: Using an enumerator for animation states provides a clean state-machine pattern to control which blend targets are active."}, {"id": "gk_504", "t": "animation_blend_tree", "text": "[ANIMATION_BLEND_TREE] Blend2 node values can exceed the 0-1 range to produce exaggerated or interesting animation effects, though normal usage keeps values clamped between 0.0 and 1.0.. Context: Going beyond standard blend values is an undocumented feature that can create stylized motion effects."}, {"id": "gk_505", "t": "root_motion", "text": "[ROOT_MOTION] Root motion animations move the character by animating the root bone (first/top bone in skeleton hierarchy), which translates the character's position in world space rather than animating in place.. Context: The root bone is the topmost bone in the skeleton hierarchy, and moving it forward during animation causes the character to physically move in the game world."}, {"id": "gk_506", "t": "root_motion", "text": "[ROOT_MOTION] In Unreal Engine, root motion must be explicitly enabled on the animation asset \u2014 without enabling 'Enable Root Motion' in the animation file, the animation plays in-place and the capsule/character does not move.. Context: By default, playing a root motion animation via montage will snap the character back to its original position because the capsule isn't being driven by the root bone movement."}, {"id": "gk_507", "t": "animation_montage", "text": "[ANIMATION_MONTAGE] Root motion animations are typically played via Animation Montages in UE \u2014 created by right-clicking the animation asset and selecting 'Create AnimMontage', then triggered in Blueprint with 'Play Montage' node specifying play rate (1.0), starting position (0), and the skeletal mesh component.. Context: Montages are the standard way to trigger one-shot root motion animations like attacks, and they are played on the character's skeletal mesh component."}, {"id": "gk_508", "t": "IK_root_motion", "text": "[IK_ROOT_MOTION] When moving the root bone forward in a root motion animation, IK targets do not automatically follow \u2014 all bones including IK targets must be selected and moved together, then keyframed with location+rotation to maintain correct IK solving.. Context: If only the root bone is moved, IK targets remain at their original position causing limbs to stretch backward toward the old location."}, {"id": "gk_509", "t": "animation_export", "text": "[ANIMATION_EXPORT] When exporting root motion animations from Blender for UE using Mr Mannequin FBX exporter, use 'Actions' export mode with sample rate of 1 (not 'Start End Keyframes') to properly capture the root bone translation data.. Context: The export settings matter for preserving root motion data \u2014 sample rate 1 ensures every frame's root bone position is captured in the FBX."}, {"id": "gk_510", "t": "animation_keyframing", "text": "[ANIMATION_KEYFRAMING] For root motion authoring in Blender: enable auto-keyframe, select all bones (A), set keyframes with I > Location Rotation at start frame, then at target frame (e.g. frame 30) move entire skeleton forward and set location+rotation again for all bones.. Context: Auto-keyframe mode combined with selecting all bones ensures both the root translation and all IK/FK bone poses are captured at each keyframe."}, {"id": "gk_511", "t": "state_machine_transition", "text": "[STATE_MACHINE_TRANSITION] In Godot's AnimationTree, setting the 'advance expression base node' to the CharacterBody3D allows state machine transitions to automatically evaluate character properties (like velocity) without code, using expressions in the transition's 'advance > expression' field.. Context: This enables no-code automatic animation transitions by letting the state machine query the character body's properties directly."}, {"id": "gk_512", "t": "transition_expression", "text": "[TRANSITION_EXPRESSION] A state machine transition expression 'velocity.length() > 0.2' on the idle-to-run transition triggers the run animation when the CharacterBody3D moves with any magnitude above 0.2.. Context: The velocity.length() check covers movement in any direction, making it a universal motion detection threshold."}, {"id": "gk_513", "t": "transition_weight", "text": "[TRANSITION_WEIGHT] A cross-blend value of 0.2 seconds is used on the idle-to-run transition for smooth blending between animation states in Godot's AnimationTree state machine.. Context: The cross-blend parameter controls how quickly one animation blends into another during a state transition."}, {"id": "gk_514", "t": "state_machine", "text": "[STATE_MACHINE] A basic character animation state machine in Godot uses three states \u2014 idle (loop), run (loop), and fall (loop) \u2014 as the foundational locomotion setup, managed via AnimationTree with a state machine root.. Context: These three states cover the most basic aspects of a character controller's animation needs."}, {"id": "gk_515", "t": "locomotion", "text": "[LOCOMOTION] Tank-style locomotion (forward/backward movement with left/right rotation) is implemented by zeroing out the X input direction and instead applying input to rotation: 'rotation.y -= input_dir.x * deg_to_rad(some_value)' to rotate the character.. Context: This replaces strafing with rotation for classic PlayStation-style tank controls on a CharacterBody3D."}, {"id": "gk_516", "t": "animation", "text": "[ANIMATION] Godot's animation retargeting workflow involves clicking the skeleton, adding a new BoneMap set to 'Humanoid', mapping bones, and reimporting \u2014 then using 'Editable Children > Animation Player > Manage Animations > Load Library' to assign an animation library.. Context: This is the standard pipeline for applying shared animation libraries to retargeted humanoid characters in Godot 4."}, {"id": "gk_517", "t": "root_motion", "text": "[ROOT_MOTION] Root motion drives character movement from the animation itself rather than code; the armature is animated moving through space, and the engine extracts translation/rotation deltas per frame to move the character, ensuring in-engine movement matches the animation software exactly.. Context: Contrasted with scripted movement where code sets velocity/rotation each frame and animation is purely visual overlay."}, {"id": "gk_518", "t": "locomotion", "text": "[LOCOMOTION] Root motion locomotion preserves per-step speed variation (acceleration, deceleration, stop-starts) baked into the animation clip, unlike scripted movement which typically applies a constant speed with a looping walk cycle played on the spot.. Context: Example given is a sneaky tiptoe character whose exaggerated step timing would be lost with constant-speed scripted movement."}, {"id": "gk_519", "t": "blend_tree", "text": "[BLEND_TREE] Pivoting to arbitrary angles is achieved by blending between a 90-degree turn animation and a 180-degree turn animation in a blend tree; interpolating the blend weight produces smooth pivot movements to any angle between those extremes.. Context: Demonstrated as a root motion technique for grounded directional changes without scripted rotation."}, {"id": "gk_520", "t": "foot_placement", "text": "[FOOT_PLACEMENT] Root motion eliminates foot sliding by tying character displacement directly to the animated foot-contact positions; blending a forward-walk clip with a walk-and-turn clip keeps feet planted correctly during directional changes, unlike scripted rotation which causes skate/slide artifacts.. Context: Side-by-side comparison showed scripted turning with basic walk animation producing visible foot sliding vs root motion blending keeping feet grounded."}, {"id": "gk_521", "t": "transition", "text": "[TRANSITION] Root motion is recommended only when the game heavily focuses on exaggerated movement animations, realistic pivots, or complex character-specific motion patterns; otherwise scripted movement with standard animation blending can achieve visually comparable results with far less animator-programmer coordination overhead.. Context: Author emphasizes root motion requires tight coupling between programming, Unity's Mecanim animation system, and animation authoring."}, {"id": "gk_522", "t": "animation", "text": "[ANIMATION] In Blender, root motion clips are authored by translating the armature root bone through world space as part of the keyframed animation, rather than animating a walk cycle in place; the resulting clip encodes both pose and displacement data for the engine to consume.. Context: Described as a technique the author found little documentation for elsewhere online."}, {"id": "gk_523", "t": "root_motion_navmesh", "text": "[ROOT_MOTION_NAVMESH] Root motion with NavMeshAgent requires implementing the OnAnimatorMove callback to synchronize the root motion position with the NavMeshAgent's nextPosition, preventing the animator and agent from fighting over character movement.. Context: Combining root motion animations with NavMeshAgent pathfinding requires explicit synchronization between the two movement systems."}, {"id": "gk_524", "t": "blend_tree_locomotion", "text": "[BLEND_TREE_LOCOMOTION] Animator setup requires velocity X and velocity Y parameters for a 2D blend tree, or a single Locomotion parameter for a 1D blend tree, with states for run forward, run backwards, run left, run right, and run 90 degrees.. Context: The blend tree configuration drives which root motion animation plays based on the agent's current movement direction relative to its facing."}, {"id": "gk_525", "t": "blend_tree_idle_trick", "text": "[BLEND_TREE_IDLE_TRICK] In a 1D locomotion blend tree, using a slow walking animation instead of an idle animation at the zero-speed threshold produces better results with root motion NavMeshAgent synchronization.. Context: A true idle clip with zero root motion can cause synchronization issues when the agent is nearly stopped but still adjusting position."}, {"id": "gk_526", "t": "root_motion_benefit", "text": "[ROOT_MOTION_BENEFIT] Root motion eliminates foot sliding because character displacement comes directly from the animation data rather than from a character controller or NavMeshAgent speed value that may not match the animation's actual movement speed.. Context: Foot sliding is a common artifact when procedural movement speed and animation playback speed are mismatched."}, {"id": "gk_527", "t": "navmesh_root_motion_update_loop", "text": "[NAVMESH_ROOT_MOTION_UPDATE_LOOP] The update loop sets animator parameters (velocity X/Y or locomotion) based on the NavMeshAgent's current movement direction and desired velocity, while OnAnimatorMove synchronizes positions each frame after the animator evaluates.. Context: This three-step pattern (set destination, update animator params in Update, sync positions in OnAnimatorMove) is the core architecture for root motion NavMeshAgent locomotion."}, {"id": "gk_528", "t": "blend_tree_dimensions", "text": "[BLEND_TREE_DIMENSIONS] Both 2D blend trees (using velocityX + velocityY) and 1D blend trees (using a single locomotion float) can drive root motion NavMeshAgent animation with the same synchronization script, requiring only different animator parameter setups.. Context: The author verified both approaches work with identical C# code by testing a 2D-configured Dude model and a 1D-configured Gargoyle model."}, {"id": "gk_529", "t": "root_motion", "text": "[ROOT_MOTION] To verify root motion in an animation, open the animation asset, go to Skeleton Tree, click on the root bone \u2014 a visible translation line from start to end position confirms root motion data exists.. Context: Checking whether an imported or marketplace animation contains root motion before using it in a project."}, {"id": "gk_530", "t": "root_motion", "text": "[ROOT_MOTION] In UE5, enable root motion by opening the animation asset, going to Asset Details, scrolling to Root Motion section, and checking 'Enable Root Motion' \u2014 the preview will appear in-place, which is expected behavior.. Context: Enabling root motion on an animation asset so it can drive character movement when played via montage or animation blueprint."}, {"id": "gk_531", "t": "root_motion", "text": "[ROOT_MOTION] Root motion can be applied through two methods: playing the animation inside an Animation Montage (via Play Montage node), or enabling it directly inside the Animation Blueprint.. Context: Two distinct workflows for applying root motion to a character's actor position at runtime."}, {"id": "gk_532", "t": "ik_retargeting", "text": "[IK_RETARGETING] When retargeting animations that contain root motion using UE5's IK Retargeter, set the root chain's Translation Mode to 'Globally Scaled' in the Chain Mapping settings to preserve root motion data.. Context: Ensuring root motion is not lost when transferring animation data between different skeletons via IK retargeting."}, {"id": "gk_533", "t": "animation", "text": "[ANIMATION] To create a montage from an animation with root motion: right-click the animation asset \u2192 Create \u2192 Animation Montage. The montage can then be triggered in a Character Blueprint using the Play Montage node.. Context: Standard workflow for converting a root motion animation into a playable montage for gameplay use such as attack combos."}, {"id": "gk_534", "t": "animation", "text": "[ANIMATION] Animations labeled 'in place' in asset packs are versions without root motion, while their counterparts without that label contain root motion translation data on the root bone.. Context: Naming convention used by animation asset packs to distinguish root motion vs in-place animation variants."}, {"id": "gk_535", "t": "root_motion", "text": "[ROOT_MOTION] Root motion moves the character via the animation itself rather than script, producing correct foot positions during walk/run and precise movement during attacks, eliminating foot sliding.. Context: Core concept: animation drives transform instead of code, solving foot-slide when speed mismatches animation."}, {"id": "gk_536", "t": "root_motion", "text": "[ROOT_MOTION] Enable root motion by selecting 'Apply Root Motion' checkbox on the Animator component; the animation's embedded translation/rotation then drives the GameObject's movement each frame.. Context: Unity Animator setting that switches from in-place to root-motion-driven locomotion."}, {"id": "gk_537", "t": "root_motion", "text": "[ROOT_MOTION] For child-object animators, implement OnAnimatorMove() to manually apply animator.deltaPosition and animator.deltaRotation to the parent Rigidbody via MovePosition and MoveRotation, making the Animator show 'Handled by Script'.. Context: Required pattern when the Animator is on a child object but the Rigidbody is on the parent."}, {"id": "gk_538", "t": "root_motion", "text": "[ROOT_MOTION] In humanoid rig import settings, configure Root Transform Rotation, Root Transform Position (Y for height), and Root Transform Position (XZ for movement) to control how root motion influences rotation, height, and lateral movement.. Context: Three import-settings sections that define which axes the root motion actually drives."}, {"id": "gk_539", "t": "root_motion", "text": "[ROOT_MOTION] Set Root Transform Rotation to 'Bake Into Pose' (Based Upon: Original) to strip unwanted left/right rotation drift from a forward walk animation, preventing unpredictable facing-direction changes when stopping mid-animation.. Context: Fixes the common issue where forward locomotion clips contain small rotational noise."}, {"id": "gk_540", "t": "blend_tree", "text": "[BLEND_TREE] A Blend Tree driven by a 'speed' float parameter blends idle/walk/run clips; a script sets the speed value, and enabling 'Apply Root Motion' lets the blended animation's root motion drive the character's actual movement speed.. Context: Combines blend tree locomotion with root motion so movement speed auto-matches the animation blend."}, {"id": "gk_541", "t": "locomotion", "text": "[LOCOMOTION] Use ForceMode.VelocityChange when adding force to a rigid body player controller \u2014 this ensures velocity changes are not affected by the rigid body's mass or the simulation step length.. Context: Proper rigid body player controller setup in Unity avoids directly setting velocity each physics frame."}, {"id": "gk_542", "t": "locomotion", "text": "[LOCOMOTION] Apply high drag only while the player is grounded and low drag while airborne; failing to switch causes floating/gliding when walking off edges.. Context: Drag management is essential for natural rigid body character movement transitions between grounded and airborne states."}, {"id": "gk_543", "t": "locomotion", "text": "[LOCOMOTION] Ground checking via simple raycast fails on edges; use sphere cast or OnCollisionEnter, then validate the hit is ground by checking the slope angle (angle between player down vector and surface normal) against a threshold.. Context: Accurate ground detection prevents false airborne/grounded states that break locomotion transitions."}, {"id": "gk_544", "t": "locomotion", "text": "[LOCOMOTION] Character controller can interact with Unity physics by applying a force at each contact point in the direction of the surface normal on every rigid body collision.. Context: Hybrid approach lets character controllers push physics objects without being a full rigid body."}, {"id": "gk_545", "t": "locomotion", "text": "[LOCOMOTION] Directly setting rigid body velocity every physics frame is discouraged by Unity docs because it breaks the physics simulation \u2014 forces should be used instead.. Context: Common tutorial anti-pattern that undermines proper physics-based player controllers."}, {"id": "gk_546", "t": "locomotion", "text": "[LOCOMOTION] Physics code must go in FixedUpdate to sync with Unity's fixed-rate physics simulation; wall collisions can falsely register as ground, fixable by assigning ground objects to a separate physics layer or checking slope angle.. Context: Edge cases in ground detection require layered validation to maintain correct grounded state."}, {"id": "gk_547", "t": "audio", "text": "[AUDIO] Resonance Audio plugins in FMOD + Unity provide full 3D spatialized sound with perceptible front/back, left/right, and up/down positioning; headphones required for proper perception.. Context: Demo of 3D audio realism using Google Resonance Audio integrated with FMOD and Unity."}, {"id": "gk_548", "t": "audio", "text": "[AUDIO] Audio occlusion can be implemented by casting multiple raycasts (triangulated lines) from around the listener to the audio source, counting how many are blocked by physical game objects, and using the green-to-red (unobstructed-to-obstructed) percentage to drive an occlusion filter parameter in FMOD.. Context: Custom occlusion script inspired by Quantum Break's audio system, adapted for Resonance Audio plugins."}, {"id": "gk_549", "t": "audio", "text": "[AUDIO] Audio occlusion modifies both amplitude and frequency content of the sound when a wall or object obstructs the path between source and listener, simulating real-world muffling.. Context: Occlusion affects volume and EQ filtering to replicate how physical barriers change perceived sound."}, {"id": "gk_550", "t": "audio", "text": "[AUDIO] Vertical raycasts should be included in the occlusion system so that player jumps dynamically affect the occlusion percentage, changing audio filtering in real time based on vertical position changes.. Context: Adding vertical lines to the raycast array ensures occlusion responds to Y-axis movement like jumping."}, {"id": "gk_551", "t": "audio", "text": "[AUDIO] A spherical AudioSource emitter (green sphere in scene) serves as the 3D spatialized sound origin; the occlusion system visualizes unobstructed rays as green and obstructed rays as red in the Unity scene view for debugging.. Context: Visual debugging of raycast-based occlusion helps tune the system during development."}, {"id": "gk_552", "t": "audio", "text": "[AUDIO] Spatial audio in Wwise uses three primary tools: Rooms (represent acoustic environments for both outdoor and indoor spaces), Portals (small rectangular apertures connecting rooms through which sound propagates or diffracts), and Reverb Zones (regions within a room with distinct reverb that don't require portals, used where there are no obvious walls like an external patio).. Context: Wwise spatial audio architecture for modeling sound propagation and reverberation in 3D game environments."}, {"id": "gk_553", "t": "audio", "text": "[AUDIO] Spatial audio volumes in Unreal/Wwise require enabling: Room, Late Reverb, Surface Reflector Set, Enable Diffraction, and Enable Diffraction on Boundary Edges for full spatial audio with reflections and diffraction.. Context: Configuration checklist for setting up a spatial audio volume in the engine."}, {"id": "gk_554", "t": "audio", "text": "[AUDIO] Spatial audio volumes have a 'Fit to Geometry' option that automatically conforms the volume shape to the surrounding room geometry, after which it can be unticked to lock the shape.. Context: Workflow for aligning spatial audio bounds to level architecture."}, {"id": "gk_555", "t": "audio", "text": "[AUDIO] Each face of a spatial audio volume can be assigned individual acoustic textures (e.g., concrete on walls, carpet on floor) and a per-wall transmission loss percentage controlling how much sound passes through that specific surface.. Context: Per-surface material and transmission configuration for realistic occlusion and reflection."}, {"id": "gk_556", "t": "audio", "text": "[AUDIO] Wwise spatial audio requires creating auxiliary buses (e.g., Reverb Large, Reverb Small, Reverb Patio) with reverb effects (such as convolution reverb), adding them to the sound bank, generating the bank, then reconciling new assets in the engine.. Context: Pipeline for setting up multiple reverb environments with distinct characteristics via auxiliary buses."}, {"id": "gk_557", "t": "audio", "text": "[AUDIO] Wwise spatial audio manages game object properties including position, auxiliary sends, obstruction, occlusion, and transmission, and runs geometric reflection, diffraction, and transmission algorithms packaged for the Reflect plug-in.. Context: Core spatial audio system responsibilities for 3D sound propagation simulation."}, {"id": "gk_558", "t": "audio", "text": "[AUDIO] AudioSettings.dspTime returns a double representing the precise number of samples processed by the audio system, independent of frame rate, making it far more accurate than Time.time or WaitForSeconds for audio timing.. Context: DSP time is the foundation for precise audio scheduling and cueing in Unity."}, {"id": "gk_559", "t": "audio", "text": "[AUDIO] AudioSource.PlayScheduled(goalTime) plays a clip at an exact DSP time rather than immediately, enabling sample-accurate scheduling by setting goalTime = AudioSettings.dspTime + delay.. Context: PlayScheduled allows queuing audio clips to play at precise future times unlike Play() which fires immediately."}, {"id": "gk_560", "t": "audio", "text": "[AUDIO] Clip duration in seconds can be calculated by dividing clip.samples by clip.frequency, then used to compute the exact DSP time when the clip will finish: nextGoalTime = currentGoalTime + (clip.samples / clip.frequency).. Context: Knowing the precise end time of a clip allows seamless scheduling of the next clip with no gap or overlap."}, {"id": "gk_561", "t": "audio", "text": "[AUDIO] Calling PlayScheduled on an AudioSource stops whatever clip is currently playing on that source, so seamless back-to-back playback requires two AudioSources that alternate (double-buffering pattern) toggling an index between 0 and 1.. Context: A single AudioSource cannot crossfade or chain clips without interruption, so a two-source swap pattern is used."}, {"id": "gk_562", "t": "audio", "text": "[AUDIO] When using PlayScheduled, the next clip should be pre-loaded and scheduled slightly before the current clip ends (e.g., goalTime - 1 second) rather than at the exact finish time, to avoid late scheduling artifacts.. Context: Pre-loading ahead of time ensures the audio system has the clip ready and prevents gaps during transitions."}, {"id": "gk_563", "t": "audio", "text": "[AUDIO] For scheduled AudioSources, looping and Play On Awake must both be disabled in the inspector, as they interfere with manual PlayScheduled timing and cause playback problems.. Context: These default AudioSource settings conflict with the manual scheduling system and must be turned off."}, {"id": "gk_564", "t": "audio", "text": "[AUDIO] Adaptive audio means sound changes dynamically based on game state: volume increases as player approaches a location (distance attenuation), heartbeat intensity scales with health, and footstep sounds vary by surface material.. Context: FMOD Studio is an industry-standard middleware for organizing, managing, and creating adaptive audio in video games."}, {"id": "gk_565", "t": "audio", "text": "[AUDIO] In FMOD, each piece of audio the game needs to play is created as an 'event' \u2014 an event can be a single sound or a collection of sounds with varying effects and internal logic, and events can be parameterized so sound varies based on parameter values.. Context: A single FMOD project corresponds to one game project, and all audio files are stored within the FMOD project."}, {"id": "gk_566", "t": "audio", "text": "[AUDIO] For footstep events, FMOD can contain multiple sound clips each representing a slightly different footstep, with internal logic that randomly selects which clip to play each time \u2014 preventing repetitive audio.. Context: Randomized footstep selection is a core pattern for natural-sounding player movement audio."}, {"id": "gk_567", "t": "audio", "text": "[AUDIO] FMOD provides distance-based volume attenuation where sounds play louder as the player gets closer to a specific location, implementing spatial 3D audio behavior through its event system.. Context: This is one of the primary adaptive audio features that makes FMOD valuable for game development."}, {"id": "gk_568", "t": "audio", "text": "[AUDIO] FMOD has direct integration plugins for Unity, Unreal Engine 4, and Unreal Engine 5; other engines like Godot can integrate via the FMOD Engine Runtime API or community-made integration plugins.. Context: For custom engines, integration requires using the runtime API directly, which involves more work than plugin-based integration."}, {"id": "gk_569", "t": "audio", "text": "[AUDIO] FMOD events can be parameterized, allowing a single event's sound output to vary dynamically based on parameter values passed from the game engine \u2014 enabling ambient triggers and context-sensitive audio without creating separate audio sources.. Context: Parameterized events are the core mechanism for adaptive audio, connecting game state to audio behavior."}, {"id": "gk_570", "t": "ambient_zone_system", "text": "[AMBIENT_ZONE_SYSTEM] Divide map into ambient zones using trigger colliders (one per area). Create an empty GameObject, add a collider component, set isTrigger=true, then size/position each collider to cover its area (forest, grassland, etc.).. Context: Proximity-based ambient sound system that crossfades between zones based on player location rather than using time-based trigger events."}, {"id": "gk_571", "t": "ambient_crossfade_gap", "text": "[AMBIENT_CROSSFADE_GAP] Leave a gap between adjacent ambient zone colliders \u2014 the gap space is where crossfading occurs. The fade distance is controlled by each sound's distance attenuation settings, so the gap width should match the desired crossfade range.. Context: Without the gap, sounds would switch abruptly; the gap allows both sounds' attenuation curves to overlap and blend gradually."}, {"id": "gk_572", "t": "floating_sound_proximity", "text": "[FLOATING_SOUND_PROXIMITY] Create a 'floating sound' script: store a reference to the zone collider and the player transform. In Update(), call collider.ClosestPoint(player.position) and set the AudioSource's transform.position to that returned point. The sound always sits at the nearest edge of the zone to the player.. Context: This makes the ambient sound follow the player inside the zone and naturally attenuate via distance when the player is outside, using the engine's built-in 3D audio distance falloff."}, {"id": "gk_573", "t": "proximity_vs_trigger_transitions", "text": "[PROXIMITY_VS_TRIGGER_TRANSITIONS] Trigger-based (OnTriggerEnter/Exit) ambient transitions are time-based and ignore player movement after firing \u2014 if a player stops mid-transition, the fade completes anyway. Proximity-based systems (ClosestPoint + distance attenuation) react continuously to player position, producing natural real-world-like blending.. Context: Proximity approach ensures ambience always matches the player's actual location rather than relying on a one-shot event."}, {"id": "gk_574", "t": "3d_audio_distance_attenuation", "text": "[3D_AUDIO_DISTANCE_ATTENUATION] The crossfade between ambient zones is entirely driven by each AudioSource's distance attenuation curve \u2014 no manual volume scripting needed. As the floating sound's ClosestPoint moves farther from the player (outside the zone), the engine's rolloff naturally fades it out.. Context: Leveraging built-in 3D spatial audio attenuation eliminates the need for custom fade logic and works with Unity audio, FMOD, or other middleware."}, {"id": "gk_575", "t": "custom_collider_shapes", "text": "[CUSTOM_COLLIDER_SHAPES] For ambient zones that can't be covered by Unity's basic geometry colliders (Box, Sphere, Capsule), use MeshColliders or composite colliders to create custom-shaped ambient zones that still support ClosestPoint() queries.. Context: Complex terrain like winding rivers or irregular forest edges need non-primitive collider shapes to accurately define the ambient area."}, {"id": "gk_576", "t": "audio", "text": "[AUDIO] AudioSource.Play() fails when the GameObject is destroyed mid-playback \u2014 if an enemy dies and its GameObject is destroyed, the AudioSource is destroyed too and the final sound clip won't play.. Context: Attaching an AudioSource directly to an enemy means destroying the enemy also destroys the audio, cutting off any in-progress or triggered sound."}, {"id": "gk_577", "t": "audio", "text": "[AUDIO] AudioSource.PlayClipAtPoint(clip, transform.position, volume) temporarily creates a hidden GameObject with an AudioSource, plays the clip, then auto-destroys \u2014 but you cannot assign an AudioMixer output to it.. Context: PlayClipAtPoint is a quick spatial audio solution but lacks access to the generated AudioSource, making mixer routing and volume slider control impossible."}, {"id": "gk_578", "t": "audio", "text": "[AUDIO] Unity AudioMixer groups let you route sound categories (music, SFX) to separate channels, apply effects per group, and control volume via UI sliders by exposing mixer parameters.. Context: An AudioMixer is required to implement per-category volume sliders in a settings menu."}, {"id": "gk_579", "t": "audio", "text": "[AUDIO] A Singleton SoundEffectsManager pattern solves both problems: it persists independently of game objects being destroyed and allows assigning an AudioMixer output to its AudioSource for volume control.. Context: Creating a dedicated manager GameObject with a singleton script provides a centralized, always-available audio playback system accessible from any script."}, {"id": "gk_580", "t": "audio", "text": "[AUDIO] AudioSource.PlayClipAtPoint accepts three parameters: AudioClip, Vector3 worldPosition, and float volume (0-1), providing basic spatial 3D audio playback at a specific point.. Context: The method signature is AudioSource.PlayClipAtPoint(clip, transform.position, 1.0f) for full-volume positional audio."}, {"id": "gk_581", "t": "audio", "text": "[AUDIO] Always uncheck 'Play On Awake' on AudioSource components when you want programmatic control over when sounds play, otherwise clips will trigger automatically when the GameObject initializes.. Context: Default AudioSource settings include Play On Awake enabled, which causes unintended playback at scene start."}, {"id": "gk_582", "t": "audio", "text": "[AUDIO] Sound effects that need reverb must be converted to an Audio Cue, with 'Override Attenuation' enabled and 'Enable Reverb Send' ticked in the attenuation settings.. Context: In Unreal Engine 5, reverb is applied per-sound by configuring the audio cue's attenuation override rather than a global setting."}, {"id": "gk_583", "t": "audio", "text": "[AUDIO] A Reverb Effect asset is created via right-click > Sounds > Effects > Reverb Effect, and the 'Decay Time' parameter controls perceived room size \u2014 larger values (e.g., 15\u201320) simulate large caves, smaller values simulate small rooms like bathrooms.. Context: Different Reverb Effect assets can be created for different environments (cave, bathroom, tunnel) each with unique parameter values."}, {"id": "gk_584", "t": "audio", "text": "[AUDIO] Without reverb, a sound plays 'flat' with no echo; enabling reverb send on the audio cue and placing it in a reverb zone adds realistic echo and spatial depth.. Context: The difference between reverb-enabled and disabled audio is clearly audible \u2014 flat vs. echoing \u2014 demonstrating the importance of reverb for realism."}, {"id": "gk_585", "t": "audio", "text": "[AUDIO] Each audio cue that needs reverb must be individually configured \u2014 override attenuation and enable reverb send are per-cue settings, not global.. Context: This per-cue approach allows fine-grained control over which sounds receive reverb processing and which do not."}, {"id": "gk_586", "t": "audio", "text": "[AUDIO] Multiple Reverb Effect assets can coexist in a project \u2014 e.g., one for a cave (Decay Time ~15-20), one for a bathroom, one for a tunnel \u2014 each with distinct parameter tuning for that environment type.. Context: This pattern of environment-specific reverb presets maps to the concept of reverb zones where different areas trigger different reverb profiles."}, {"id": "gk_587", "t": "audio", "text": "[AUDIO] Animation Events (blue arrow markers on the timeline) allow syncing audio playback to exact frames in an animation clip, preventing sounds from playing too early when using AudioSource.Play() directly.. Context: Without animation events, calling audio source play at animation start causes sound to fire before the visual action (e.g., sword swing) reaches the intended frame."}, {"id": "gk_588", "t": "audio", "text": "[AUDIO] To add an animation event: select the GameObject, open the Animation window, choose the target animation clip, position the playhead at the desired time, and click the 'Add Event' button to insert a callback marker.. Context: The event appears as a small blue arrow/line on the animation timeline that can be selected and configured."}, {"id": "gk_589", "t": "audio", "text": "[AUDIO] Animation events call public void methods on scripts attached to the same GameObject; the function must be public (e.g., `public void PlaySound() { audioSource.Play(); }`) and the GameObject must have both the script and an AudioSource component.. Context: The animation event dropdown only lists public methods from MonoBehaviour scripts attached to the GameObject with the Animator."}, {"id": "gk_590", "t": "audio", "text": "[AUDIO] If no script is attached to the GameObject, the animation event function dropdown will be empty \u2014 a MonoBehaviour script with at least one public method must be added before animation events can trigger audio.. Context: The event system requires a target function on the same GameObject to invoke at the marked frame."}, {"id": "gk_591", "t": "audio", "text": "[AUDIO] Game audio integration sits between audio/music production and game design \u2014 the core workflow is integrating audio and music into a game engine, not producing the audio itself.. Context: Game audio courses focus on the middleware integration pipeline rather than sound design or composition."}, {"id": "gk_592", "t": "audio", "text": "[AUDIO] Modern game audio workflows use audio middleware (like Wwise) as an intermediary between a DAW and the game engine, rather than importing audio directly into the engine.. Context: The workflow is based on a particular game engine paired with a particular audio middleware for integration."}, {"id": "gk_593", "t": "audio", "text": "[AUDIO] Steinberg Nuendo DAW has a 'Game Audio Connect' feature that bridges the DAW directly to game engines, enabling tighter integration between audio production and in-engine playback.. Context: This is an advanced feature that requires significant setup but simplifies the final export step."}, {"id": "gk_594", "t": "audio", "text": "[AUDIO] Game audio integration workflows are designed to be game-engine-agnostic and DAW-agnostic, meaning the spatial audio concepts (distance attenuation, reverb zones, triggers) apply across Unity, Unreal, and other engines.. Context: The principles of 3D audio integration transfer between engines even though specific APIs differ."}, {"id": "gk_595", "t": "audio", "text": "[AUDIO] Sound occlusion through walls requires enabling 'override attenuation' on the sound source and setting distance falloff values (e.g., inner radius 150, outer radius 1000), then enabling 'enable occlusion' to muffle or block sound through geometry.. Context: Unreal Engine sound occlusion system for muffling audio through walls and doors."}, {"id": "gk_596", "t": "audio", "text": "[AUDIO] Occlusion volume attenuation controls how much sound passes through walls: 0.0 = completely silent behind walls, 0.2 = muffled but audible, 1.0 = no occlusion effect (full volume passes through).. Context: The occlusion attenuation value is a 0-1 multiplier controlling sound reduction through occluding geometry."}, {"id": "gk_597", "t": "audio", "text": "[AUDIO] When a sound is occluded and volume drops to zero, the audio source stops playing by default; setting virtualization mode to 'Play When Silent' keeps the sound playing even when inaudible so it resumes naturally when the listener returns.. Context: Without virtualization, occluded sounds stop and don't resume when the player re-enters the audible area."}, {"id": "gk_598", "t": "audio", "text": "[AUDIO] Sound occlusion uses level geometry (walls, doors) as occluders automatically once enabled \u2014 no special collision volumes or trigger zones are needed for basic wall occlusion.. Context: The engine performs occlusion checks against existing scene geometry between the listener and audio source."}, {"id": "gk_599", "t": "audio", "text": "[AUDIO] Distance attenuation and occlusion are separate systems: attenuation controls volume falloff over distance (inner/outer radius), while occlusion handles volume reduction when geometry blocks the line of sight between listener and source.. Context: Both systems work together \u2014 a sound gets quieter with distance AND gets muffled/silenced when a wall is between listener and source."}, {"id": "gk_600", "t": "audio", "text": "[AUDIO] Sound Cues (sound queues) wrap raw audio assets and allow adding attenuation and occlusion properties; these properties are configured on the cue rather than individual sound files.. Context: In Unreal Engine, right-clicking a sound asset and creating a Sound Cue provides the node graph for adding occlusion and attenuation overrides."}, {"id": "gk_601", "t": "audio", "text": "[AUDIO] To add audio in Unity, create an empty GameObject, add an AudioSource component via Add Component in the Inspector, then drag an audio clip into the AudioSource's audio clip field. Play On Awake is checked by default so it plays when the scene starts.. Context: Basic setup for playing background music in a Unity scene using the AudioSource component on a GameObject."}, {"id": "gk_602", "t": "audio", "text": "[AUDIO] To loop audio in Unity, enable the Loop checkbox on the AudioSource component. To adjust volume and pitch, use the Volume and Pitch sliders on the AudioSource (e.g., volume set to 0.6 to reduce loudness).. Context: AudioSource provides built-in controls for looping, volume, and pitch without any scripting required."}, {"id": "gk_603", "t": "audio", "text": "[AUDIO] AudioSource Priority determines how an audio source competes with others; higher priority sources are heard louder over lower priority ones when multiple AudioSources play simultaneously.. Context: Unity's audio mixing uses the Priority field to resolve contention when many sounds play at once."}, {"id": "gk_604", "t": "audio", "text": "[AUDIO] To persist audio across scene loads, use DontDestroyOnLoad(this.gameObject) in the Awake() method of a script attached to the music GameObject. Awake runs before Start, ensuring persistence is set before the scene fully loads.. Context: Without DontDestroyOnLoad, the music GameObject is destroyed on scene reload, causing music to restart."}, {"id": "gk_605", "t": "audio", "text": "[AUDIO] A singleton pattern is needed for persistent audio: DontDestroyOnLoad prevents destruction, but each scene reload instantiates a new music GameObject, causing duplicate audio. The script must check for and destroy duplicates.. Context: Common pitfall where DontDestroyOnLoad alone causes multiple overlapping music instances across scene transitions."}, {"id": "gk_606", "t": "audio", "text": "[AUDIO] To crossfade music at runtime, use two AudioSources: one with PlayOnAwake and Loop enabled at target volume, the other with Loop enabled and volume set to zero. Swap roles when triggered.. Context: Runtime music transition pattern using dual AudioSources in Unity."}, {"id": "gk_607", "t": "audio", "text": "[AUDIO] Smooth volume crossfade uses a coroutine with a percentage tracker: start at 0, increment by Time.deltaTime / transitionTime each frame, lerp volume from defaultVolume to 0 for outgoing and 0 to defaultVolume for incoming.. Context: Frame-by-frame volume interpolation using Time.deltaTime divided by a configurable transition duration."}, {"id": "gk_608", "t": "audio", "text": "[AUDIO] To allow interrupting a crossfade, call StopAllCoroutines() before starting the new crossfade coroutine; without this, multiple overlapping coroutines will conflict.. Context: Preventing coroutine stacking when the user triggers rapid music changes."}, {"id": "gk_609", "t": "audio", "text": "[AUDIO] The crossfade coroutine first pauses the currently playing AudioSource, unpauses the target, and calls Play() on the target if it wasn't already playing, then runs two sequential while-loops for fade-out and fade-in.. Context: Sequenced fade-out then fade-in within a single coroutine for clean audio transitions."}, {"id": "gk_610", "t": "audio", "text": "[AUDIO] A boolean flag tracking which AudioSource is currently playing can be used to correctly identify and swap the active and target sources, toggling after each transition.. Context: State tracking to ensure the correct source is faded out and the correct one is faded in."}, {"id": "gk_611", "t": "audio", "text": "[AUDIO] Spatial audio integration in Unity involves posting events via game-defined callbacks, managing sound bank loading/unloading, and configuring reverb zones to emulate acoustic environments.. Context: The Wwise 301 course covers fundamental integration patterns including callbacks for posting events, sound bank management, and reverb zones for acoustic emulation in Unity games."}, {"id": "gk_612", "t": "audio", "text": "[AUDIO] Reverb zones are used to emulate room acoustics by subscribing game objects to specific acoustic environments, replacing static reverb with spatially-aware acoustic processing.. Context: Reverb zones allow different areas of a game world to have distinct acoustic properties that affect how sounds are perceived based on the listener's location."}, {"id": "gk_613", "t": "audio", "text": "[AUDIO] Wwise spatial audio integration uses 'rooms and portals' architecture where game objects subscribe to acoustic environments, enabling dynamic reverb and distance-based attenuation without manual per-source configuration.. Context: The rooms and portals system replaces simple reverb zones with a more physically accurate model of how sound propagates through connected spaces."}, {"id": "gk_614", "t": "audio", "text": "[AUDIO] Spatial audio in Unity game integration requires three layers: event posting via callbacks on AudioSource-equivalent objects, sound bank loading for asset management, and environment subscription for acoustic context.. Context: These three layers form the complete Wwise spatial audio pipeline from triggering sounds to delivering them with proper spatialization."}, {"id": "gk_615", "t": "audio", "text": "[AUDIO] Unity Timeline audio tracks can play sound without an AudioSource component assigned, but an AudioSource is needed for 3D spatial sound emission from a specific position or to apply effects like reverb and low pass filters.. Context: When dragging audio clips into a Timeline, the track shows 'none' for AudioSource but still plays the audio in 2D."}, {"id": "gk_616", "t": "audio", "text": "[AUDIO] The low pass filter effect on an AudioSource is used to simulate a character being stunned or underwater by lowering the cutoff frequency, which muffles higher frequencies.. Context: Adding a low pass effect component to an AudioSource and reducing the cutoff frequency creates a muffled audio effect useful for gameplay states."}, {"id": "gk_617", "t": "audio", "text": "[AUDIO] AudioSource pitch can be adjusted (e.g., set to 1.1) to create slight variation in repeated sound effects like explosions, preventing repetitive identical playback.. Context: Setting pitch to 1.1 on an AudioSource gives a slightly higher pitch to differentiate some explosion instances from others."}, {"id": "gk_618", "t": "audio", "text": "[AUDIO] To emit 3D spatial sound from a specific world position, attach an AudioSource component to a GameObject at that location and assign it to the Timeline audio track.. Context: Creating an empty GameObject at an explosion's position and adding an AudioSource makes the explosion sound emit from that 3D location."}, {"id": "gk_619", "t": "audio", "text": "[AUDIO] Ambient audio volume in Unity Timeline is controlled by selecting the audio track and adjusting the volume property, e.g., reducing to ~0.5 to keep it as background.. Context: The ambient sound track volume was decreased to approximately half to prevent it from overpowering the explosion sound effects."}, {"id": "gk_620", "t": "audio", "text": "[AUDIO] Timeline audio clips can be split at the playhead position using the 'S' key shortcut, then trimmed or stretched to match animation timing of other tracks like activation tracks.. Context: Explosion sound effects were split and aligned to match activation track triggers so each explosion visual synced with its audio."}, {"id": "gk_621", "t": "combat", "text": "[COMBAT] Parry system uses two types: passive parry (automatic deflection when weapon is held in guard stance near incoming strike) and active parry (player manually flicks weapon to intercept an incoming attack). No dedicated block button exists.. Context: Half Sword uses stance-based defense where passive parry acts like aim-assist, nudging the weapon to intercept if held in fighting position, while active parry requires timing and manual input."}, {"id": "gk_622", "t": "combat", "text": "[COMBAT] Passive parry only activates when the weapon is held in a neutral guard stance in front of the character. It deactivates when the weapon is raised too high, extended out for a swing, or otherwise out of guard position.. Context: Guard stance gating prevents passive parry from working during attack windups or when the weapon is poorly positioned, creating offensive-defensive tradeoffs."}, {"id": "gk_623", "t": "combat", "text": "[COMBAT] Stance system ties foot position to weapon side: weapon angled to the right puts right foot forward, moving weapon to the left switches to left foot forward. Stance affects defensive vulnerability, particularly hand exposure.. Context: Procedural stance switching based on weapon position creates gameplay differences in hit exposure, with right-foot-forward preferred for better hand protection."}, {"id": "gk_624", "t": "combat", "text": "[COMBAT] Sprint key (shift) lowers the character into an athletic crouch stance enabling dodging and fast movement. It consumes stamina but is recommended to be held frequently during combat.. Context: Sprint toggle changes the character's posture from rigid upright to athletic, which is a prerequisite for dodge and movement mechanics."}, {"id": "gk_625", "t": "combat", "text": "[COMBAT] Mouse sensitivity should be set very low (example: middle of slider at 800 DPI) for precise weapon control. High sensitivity causes erratic flailing with no tactical precision.. Context: Weapon movement is directly mouse-controlled, so low sensitivity is critical for executing precise strikes, parries, and guard positioning."}, {"id": "gk_626", "t": "combat", "text": "[COMBAT] Optimal defense combines three layers: passive parry (guard stance auto-deflection), active parry (manual flick interception), and dodge/footwork movement to avoid strikes entirely.. Context: Layered defense system where no single mechanic is sufficient alone; mixing all three defensive options provides the best survivability."}, {"id": "gk_627", "t": "combat", "text": "[COMBAT] Attack combos use a boolean variable to track if character is in attack animation, an Animation Montage array variable sized to combo length (e.g., 3 for a 3-hit combo), and an integer variable tracking the current attack index in the array.. Context: Third person blueprint setup for melee combo system using animation montage arrays."}, {"id": "gk_628", "t": "combat", "text": "[COMBAT] Combo logic: on attack input, check if not already attacking, then play current montage from array. On animation end, reset attacking boolean. Increment combo index each attack; if index reaches array length, reset to 0 for next press.. Context: Blueprint flow for cycling through combo attacks and resetting the combo chain."}, {"id": "gk_629", "t": "combat", "text": "[COMBAT] Input buffering for combos is implemented by adding an Animation Notify named 'can attack' at a specific frame in each Animation Montage, marking the point where the player can buffer their next attack input.. Context: Notify points in montages control when combo input becomes available during an attack animation."}, {"id": "gk_630", "t": "combat", "text": "[COMBAT] The 'can attack' notify is handled in the Animation Blueprint (ABP) event graph: on receiving the notify, cast to the third person character and set the attack boolean to false, allowing the next attack input to register.. Context: ABP event graph processes the animation notify to re-enable attack input mid-combo."}, {"id": "gk_631", "t": "combat", "text": "[COMBAT] Play Montage node (not Play Animation Montage) is used for combo systems, referencing the skeletal mesh component, and replaces the simpler play-and-montage approach from single attacks.. Context: Node selection matters \u2014 Play Montage node is the correct choice for combo-capable attack systems."}, {"id": "gk_632", "t": "combat", "text": "[COMBAT] Animation Notifies can be copied from one Animation Montage and pasted into others at desired frames, allowing consistent combo buffer timing across all attacks in the chain.. Context: Right-click copy/paste workflow for placing identical notify points across multiple montages."}, {"id": "gk_633", "t": "combat", "text": "[COMBAT] Three-hit combo system with ability to flip/change direction mid-combo, allowing the player to re-orient attacks between hits. Context: 2.5D Souls-like game implementing Sekiro-inspired combat with beat-em-up visual style"}, {"id": "gk_634", "t": "combat", "text": "[COMBAT] Attack movement nudges the character forward in their facing direction on hit, and the left stick up/down moves the character on the z-axis while attacking. Context: Emphasizes 2.5D depth by allowing z-axis movement during attacks"}, {"id": "gk_635", "t": "combat", "text": "[COMBAT] Action caching system stores the next player input (e.g. attack after dash) during a current animation and executes it immediately when the current animation ends, preventing perceived input eating. Context: Compensates for lack of snappy animation canceling by buffering the next action"}, {"id": "gk_636", "t": "combat", "text": "[COMBAT] Hitbox z-axis size in 2.5D requires careful tuning via trial-and-error against a dummy NPC to avoid frustrating whiffs where attacks visually appear to connect but miss. Context: Depth perception problem unique to 2.5D/beat-em-up camera angles makes hit registration feel inconsistent"}, {"id": "gk_637", "t": "combat", "text": "[COMBAT] Knockback pushes the enemy in the opposite direction of the player on hit, including diagonal pushback along the z-axis, providing satisfying hit feedback. Context: Without pushback, hitting enemies felt weird and lacked proper feedback"}, {"id": "gk_638", "t": "combat", "text": "[COMBAT] Hit reactions are applied to both player and NPC \u2014 the NPC receives damage and plays hit reaction animations, and the player also reacts to being hit by AI attacks. Context: AI uses navmesh to chase the player when out of range, then attacks with its own hit system"}, {"id": "gk_639", "t": "combat", "text": "[COMBAT] Melee combat input detection uses UserInputService.InputEnded event, checking for UserInputType == Enum.UserInputType.MouseButton1 to trigger punch attacks on left click.. Context: Basic combat system binds left mouse button to punch action via UIS input ended callback with a guard clause to ignore input while chatting."}, {"id": "gk_640", "t": "combat", "text": "[COMBAT] A combo system requires a cooldown mechanism to prevent spam-clicking, implemented alongside a combo counter that tracks sequential hits.. Context: Without a cooldown, players can spam left click indefinitely, so a debounce/cooldown variable gates attack frequency for the combo system."}, {"id": "gk_641", "t": "combat", "text": "[COMBAT] Combat architecture uses a client-server split: a LocalScript ('combat client') detects input and fires a RemoteEvent, while a server Script ('server combat') listens via OnServerEvent to process hits and damage.. Context: RemoteEvent stored in ReplicatedStorage bridges client input to server-side combat logic, ensuring hit validation and damage are handled server-authoritative."}, {"id": "gk_642", "t": "combat", "text": "[COMBAT] Input guard pattern: check if the input event's gameProcessedEvent parameter is true (variable 'e') and return early, preventing combat actions from firing while the player is typing in chat.. Context: The 'if e then return end' pattern inside InputEnded ensures UI interactions like chat don't accidentally trigger attacks."}, {"id": "gk_643", "t": "combat", "text": "[COMBAT] Hit VFX (visual effects) are separate assets imported into the game, attached to play on punch impact to give visual feedback for melee strikes.. Context: Pre-made VFX assets are distributed via Discord and placed in the game project to trigger on hit events during combat."}, {"id": "gk_644", "t": "combat", "text": "[COMBAT] The RemoteEvent is created in ReplicatedStorage (named 'MainEvent') and fired from client via FireServer(), with the server listening via OnServerEvent:Connect(function(player) ...) to process combat actions.. Context: This is the standard Roblox pattern for secure client-to-server communication where the server validates and executes damage/hit logic."}, {"id": "gk_645", "t": "combat", "text": "[COMBAT] Melee hitbox is implemented as a box collision component attached to the character, with box extent and location adjusted to match the attack animation's reach. For beat-em-ups with multiple lanes, the hitbox depth controls how far attacks reach into other lanes.. Context: 2D sprite combat system using flipbook animations in Unreal Engine 5."}, {"id": "gk_646", "t": "combat", "text": "[COMBAT] Hitbox collision preset is set to Custom with all channels set to Ignore, then only Pawn set to Overlap, ensuring the hitbox only detects characters and not other objects.. Context: Collision filtering setup so melee attacks only register against character pawns."}, {"id": "gk_647", "t": "combat", "text": "[COMBAT] A hit_check function uses GetOverlappingActors on the hitbox with a class filter, iterates with a ForEach loop, skips self (since the hitbox overlaps the owner), and calls ApplyDamage on each other actor. A damage amount variable controls per-attack damage.. Context: Overlap-based hit detection that applies damage to all valid targets in the hitbox each frame."}, {"id": "gk_648", "t": "combat", "text": "[COMBAT] An is_attacking boolean is set true on attack input and false when the attack flipbook finishes playing. On Tick, hit_check is only called when is_attacking is true, but this causes multiple damage applications per attack since it fires every frame.. Context: Frame-based hit checking creates a multi-hit bug that needs to be resolved with a single-hit gate."}, {"id": "gk_649", "t": "combat", "text": "[COMBAT] Attack animation uses a non-looping flipbook. Set Looping is called with false on attack start. The OnFinishPlaying event fires when the animation completes, which resets to idle flipbook, re-enables looping, and calls Play if the sprite has stopped.. Context: Flipbook-based attack animation state management for a one-shot attack that returns to idle."}, {"id": "gk_650", "t": "combat", "text": "[COMBAT] The AnyDamage event on the receiver is triggered by ApplyDamage and provides the received damage value. The hitbox can be visualized by toggling SetHiddenInGame to false when is_attacking is true and back to true when the attack ends.. Context: Damage reception and debug visualization for the melee hitbox during development."}, {"id": "gk_651", "t": "combat", "text": "[COMBAT] Each weapon has a limited number of efficient dodges; after exceeding this count, dodge distance shrinks progressively. Efficient dodges reset after 0.5 seconds of not dodging, so optimal dodge rhythm is roughly once per second during horde fights.. Context: Dodge management is core melee defense \u2014 spacing dodges prevents degraded dodge distance while maintaining mobility."}, {"id": "gk_652", "t": "combat", "text": "[COMBAT] Each melee weapon has at least two attack sequences (light chain and heavy chain). Each attack in a sequence has distinct properties: attack speed, damage, cleave, stagger cleave, base damage, and armor damage \u2014 meaning specific attacks within a chain are better for horde clear vs single-target DPS.. Context: Weapon combo optimization requires analyzing per-attack stats to build separate horde-clear and anti-armor combos."}, {"id": "gk_653", "t": "combat", "text": "[COMBAT] Weapons have distinct horde-clear combos and anti-armor combos. Example: Rapier horde-clear = spam lights, anti-armor = spam heavies. Elven Spear horde-clear = push-attack \u2192 light \u2192 light, or heavy \u2192 light \u2192 light.. Context: Combo selection depends on enemy type \u2014 switching between light/heavy chains and push-attacks mid-combat is a core skill."}, {"id": "gk_654", "t": "combat", "text": "[COMBAT] Attacks have a cleave stat that determines how many enemies a swing passes through and staggers. When hordes are dense and attacks can't cleave enough enemies to stagger them all, pushes and push-attacks are used to create space and interrupt incoming hits.. Context: Push/push-attack is the defensive reset tool when cleave is insufficient against dense enemy groups."}, {"id": "gk_655", "t": "combat", "text": "[COMBAT] Stagger cleave is a separate stat from damage cleave \u2014 an attack can stagger more enemies than it damages. Higher stagger cleave values mean more enemies are interrupted per swing, which is critical for horde survival.. Context: Stagger and damage cleave are independent properties that inform weapon combo choices for crowd control vs killing."}, {"id": "gk_656", "t": "combat", "text": "[COMBAT] The core melee combat loop layers three systems: maintain dodge rhythm (~1/sec), execute the correct weapon combo for the situation (horde-clear or anti-armor), and use push-attacks when enemy density overwhelms cleave \u2014 all simultaneously.. Context: Effective melee requires combining dodge timing, combo selection, and push management as concurrent skills rather than sequential actions."}, {"id": "gk_657", "t": "combat", "text": "[COMBAT] Hit stop freezes both attacker and victim animations for a few milliseconds on hit impact, implemented by setting character's custom time dilation to 0, then restoring to 1 after a duration via timer.. Context: Hit stop makes hits feel more impactful and gives players' eyes time to register what happened on screen."}, {"id": "gk_658", "t": "combat", "text": "[COMBAT] Hit stop and hit stun are different: hit stun only affects the victim and disallows blocking so the attacker can connect combos, while hit stop affects both attacker and victim as a visual/feel effect.. Context: Clearing up a common confusion between two distinct combat feedback systems."}, {"id": "gk_659", "t": "combat", "text": "[COMBAT] Hit stop duration should be set per-attack using a data asset with explicit values for each move (damage, hit stop duration) rather than a single global value, giving designers precise control per combo hit.. Context: Using data assets allows clean per-attack configuration of combat properties."}, {"id": "gk_660", "t": "combat", "text": "[COMBAT] During hit stop, the victim's sprite/visual mesh should shake (flip-flop left/right) but the hitbox must NOT move with it \u2014 only the visual representation shakes to maintain consistent hit detection.. Context: Sakurai used this technique in Smash Bros to add visual feedback without breaking gameplay collision."}, {"id": "gk_661", "t": "combat", "text": "[COMBAT] Setting time dilation to 0 does NOT stop the actor from ticking, so tick functions and subroutines can still run during hit stop to drive effects like sprite shaking.. Context: This is important for implementing visual effects that play during the frozen hit stop window."}, {"id": "gk_662", "t": "combat", "text": "[COMBAT] Stronger hit stop leaves the attacker vulnerable in multiplayer (3+ players), so hit stop duration must be balanced against gameplay risk \u2014 Sakurai noted this tradeoff in Smash Bros design.. Context: Longer hit stop creates better feel but can be exploited by third-party attackers in free-for-all modes."}, {"id": "gk_663", "t": "combat", "text": "[COMBAT] Enemy basic setup requires: animations, a hitbox, health, and the ability to be hit by the player's attacks as the minimum foundation.. Context: Setting up basic enemies is straightforward with these core components before adding behavioral intelligence."}, {"id": "gk_664", "t": "combat", "text": "[COMBAT] Enemy states start with two basics: idle and pursuing. In idle, a distance radius check triggers pursuit; in pursuing, the enemy's movement direction vector always angles toward the player.. Context: Simple state machine with distance-based detection drives enemy movement toward the player."}, {"id": "gk_665", "t": "combat", "text": "[COMBAT] Line of sight (LOS) is calculated by tracing the line between enemy and player positions and iteratively performing small circular collision queries for obstacles along that line; LOS true means clear path, LOS false means blocked.. Context: LOS prevents enemies from detecting or attacking through walls and obstacles."}, {"id": "gk_666", "t": "combat", "text": "[COMBAT] Enemy attack gating: the enemy must pass both a distance radius check AND a line-of-sight check before transitioning from idle to attack/pursue state, preventing attacks through walls.. Context: Combining distance and LOS checks ensures enemies only engage when they have a valid path to the player."}, {"id": "gk_667", "t": "combat", "text": "[COMBAT] When LOS is lost during pursuit, the enemy reverts to idle state to prevent getting stuck on or phasing through obstacles, but a tile-tracking pathfinding system can maintain pursuit around corners.. Context: Simple LOS-loss fallback is safe but limited; tile-based path tracking adds smarter navigation when direct line to player is blocked."}, {"id": "gk_668", "t": "combat", "text": "[COMBAT] Hitboxes in Smash Bros style games use sphere colliders rather than cube/cuboid colliders, as spheres are more authentic to the original Smash Bros hit detection system.. Context: Sphere-based hitboxes are preferred for platform fighters to match authentic Smash Bros behavior, while fighting games typically use cube/square hitboxes."}, {"id": "gk_669", "t": "combat", "text": "[COMBAT] Hitboxes should be spawned as separate actors/objects that self-destroy after a short lifetime, not permanently attached colliders \u2014 they are instantiated on attack, check collision, apply damage, then auto-despawn.. Context: Each attack spawns a hitbox actor that handles its own collision detection and cleanup, keeping attack logic decoupled from the character."}, {"id": "gk_670", "t": "combat", "text": "[COMBAT] Hitboxes must filter by owner/team so the attacking player does not damage themselves \u2014 collision checks should exclude the player who spawned the hitbox.. Context: Without owner filtering, a player's own hitbox would register collision against themselves and cause self-damage."}, {"id": "gk_671", "t": "combat", "text": "[COMBAT] Hitbox spawn position must account for the character's facing direction \u2014 spawning always to one side regardless of facing is a common bug that requires reading the character's current orientation to offset correctly.. Context: Characters that can only face left or right need their facing state resolved before hitbox placement can work correctly on both sides."}, {"id": "gk_672", "t": "combat", "text": "[COMBAT] Hitboxes and hurtboxes are distinct concepts: hitboxes are offensive collision zones spawned during attacks, while hurtboxes are defensive zones on the character body that receive damage \u2014 they should be implemented as separate systems.. Context: Separating hitbox and hurtbox logic allows for more granular control over which attacks land and where on the body damage is registered."}, {"id": "gk_673", "t": "combat", "text": "[COMBAT] Advanced hitboxes can detect where on the weapon collision occurred (e.g. center of sword vs tip of boxing glove) to vary damage or knockback based on hit position \u2014 this is a refinement on basic collision checking.. Context: Position-aware hitboxes enable tipper mechanics and sweet/sour spot damage scaling seen in Smash Bros."}, {"id": "gk_674", "t": "combat", "text": "[COMBAT] Hit stop (freezing time momentarily on impact) should escalate across a combo chain \u2014 small pause on hit 1, medium on hit 2, large on hit 3 \u2014 to sell the weight of the final hit. Context: Escalating hit stop duration across a three-hit combo makes the player feel increasing impact with each successive strike"}, {"id": "gk_675", "t": "combat", "text": "[COMBAT] Knockback should trigger on the final hit of a combo to physically displace the enemy, reinforcing the heavy impact already sold by hit stop. Context: Combining knockback with escalating hit stop on the third combo hit creates a strong sense of power and finality"}, {"id": "gk_676", "t": "combat", "text": "[COMBAT] Hit flash (briefly changing enemy color/material to white on damage) provides immediate visual feedback that a hit connected before any animation plays. Context: Hit flash is a fast, low-cost feedback layer that confirms damage registration to the player"}, {"id": "gk_677", "t": "combat", "text": "[COMBAT] Weapon swing and impact sounds should reuse a single sound cue but randomize pitch between a min and max value each play to avoid repetition. Context: Pitch randomization on a single audio clip provides perceived variety without needing multiple sound assets"}, {"id": "gk_678", "t": "combat", "text": "[COMBAT] Impact VFX (blood splatter, sparks, explosion) must spawn at the exact point of contact between weapon and enemy to sell the hit location. Context: Positionally accurate impact particles immerse the player in the combat fantasy by showing precise contact"}, {"id": "gk_679", "t": "health", "text": "[HEALTH] Health bars should animate smoothly (lerp/tween) when losing HP rather than instantly jumping, so the player can perceive the exact amount of damage dealt. Context: Slowly animating the health bar drain gives clearer damage feedback than an instant chunk removal"}, {"id": "gk_680", "t": "dialogue", "text": "[DIALOGUE] A dialogue system can be built with three core scripts: a DialogLine script (serialized data class holding text, character name, portrait, and event triggers), a DialogueActivator script (holds a list of DialogLines and is placed on game objects like NPCs or room triggers to activate cutscenes), and a third controller script that manages playback.. Context: Three-script architecture where DialogLine is a serialized variable used by other scripts rather than attached to a game object directly."}, {"id": "gk_681", "t": "dialogue", "text": "[DIALOGUE] The DialogLine script is serialized (not attached to a game object) and serves as a data container variable used by other scripts, holding: display text, character name, character portrait, and event triggers for character movement and animations.. Context: Each DialogLine instance represents a single line of dialogue with associated metadata and scene actions."}, {"id": "gk_682", "t": "dialogue", "text": "[DIALOGUE] The DialogueActivator script is placed on in-scene game objects (NPCs, room regions) to both store an ordered list of DialogLine instances and serve as the trigger/entry point for initiating a cutscene sequence.. Context: This pattern ties conversation triggers to world objects, enabling spatial NPC conversation activation."}, {"id": "gk_683", "t": "dialogue", "text": "[DIALOGUE] Dialogue UI layout uses three key screen regions: a dialogue text box at the bottom, character portrait panels for showing expressions, and the remaining upper screen area reserved for in-scene action/movement during the conversation.. Context: UI layout designed for RPG cutscenes where characters can move and animate while dialogue plays."}, {"id": "gk_684", "t": "dialogue", "text": "[DIALOGUE] DialogLine events can trigger in-scene actions such as character movement and animation changes during dialogue playback, allowing cutscenes to combine text display with choreographed scene actions.. Context: Event triggers embedded in dialogue lines enable cinematic sequences beyond static text display."}, {"id": "gk_685", "t": "dialogue", "text": "[DIALOGUE] Character portraits support multiple expressions that can change per dialogue line, allowing NPCs to display different emotional states during a conversation sequence.. Context: Portrait switching is handled per DialogLine instance to convey character emotion throughout cutscenes."}, {"id": "gk_686", "t": "dialogue", "text": "[DIALOGUE] Dialog IDs are automatically read from the name of the dialog graph object created in Unity, but can be manually edited to any desired value.. Context: The dialog system uses the object name as the unique identifier that links the dialog definition to NPC references."}, {"id": "gk_687", "t": "dialogue", "text": "[DIALOGUE] C-vars (conversation variables) are defined in the dialog graph as a scratch pad to control conversation flow, allowing fine-tuning of what the player can see based on c-var values. They are referenced by name across all graph nodes.. Context: C-vars act as flag/state variables that gate dialogue branches \u2014 e.g. nurse1, nurse2, nurse3 \u2014 and are available to all nodes in the graph once declared."}, {"id": "gk_688", "t": "dialogue", "text": "[DIALOGUE] The dialog XML structure uses a start_statement node as the entry point, with statement IDs linking statements to responses. Statements contain NPC text, responses contain player reply options.. Context: The exported XML links the dialog ID to an NPC definition, and the start_statement field determines which statement node runs first when conversation begins."}, {"id": "gk_689", "t": "dialogue", "text": "[DIALOGUE] Dialogs are exported from a Unity-based dialog graph editor to a dialogs.xml file, with optional localization export that replaces inline text with hash-based localization keys prefixed by the dialog ID and an underscore.. Context: When exported without localization, statement and response text is written inline in the XML; with localization, a separate localization file is generated using the prefix pattern dialogID_statementID."}, {"id": "gk_690", "t": "dialogue", "text": "[DIALOGUE] The NPC ID in the mod's empty-handed template points to a dialog ID, creating the link between an NPC entity and its conversation tree. The dialog entry in dialogs.xml must match this NPC reference.. Context: NPC-to-dialog binding is done by setting the NPC's dialog/NPC ID field to match the dialog graph's exported ID."}, {"id": "gk_691", "t": "dialogue", "text": "[DIALOGUE] Dialogs can be hot-reloaded at runtime using a console command (e.g. 'dialogue') that rereads all dialog XML files from the mods folder without restarting the game.. Context: This enables rapid iteration on dialog content \u2014 edit the graph, export XML, run the reload command, and immediately test the updated conversation in-game."}, {"id": "gk_692", "t": "dialogue", "text": "[DIALOGUE] An NPC conversation is initiated by adding an 'NPC Conversation' component to a GameObject in the hierarchy, which is required to start any conversation with that character.. Context: The Dialogue Editor asset uses a component-based approach where each NPC gets an NPC Conversation script attached to a GameObject named for the conversation (e.g., 'robot conversation')."}, {"id": "gk_693", "t": "dialogue", "text": "[DIALOGUE] Dialogue trees are built with speech nodes that contain: character name, dialogue text, icon/sprite, optional audio with volume control, optional TextMeshPro font override, and an optional event callback for quest acceptance or other actions.. Context: Each speech node in the Dialogue Editor window exposes fields for name, text, icon, audio, font, and an event that fires after the node is displayed."}, {"id": "gk_694", "t": "dialogue", "text": "[DIALOGUE] Branch conditions are created via option nodes that present the player with selectable responses (e.g., 'I want a quest please' vs 'go away'), where each option can lead to further speech nodes or end the conversation if left unconnected.. Context: From a speech node you can create option nodes that branch the dialogue tree; an option with no child speech node automatically ends the conversation."}, {"id": "gk_695", "t": "dialogue", "text": "[DIALOGUE] Quest triggers are handled by adding Unity events to speech or option nodes, allowing actions like quest acceptance to fire at specific points in the conversation flow.. Context: The event field on a speech node lets you hook up any UnityEvent callback, such as accepting a quest, so game logic executes when that dialogue line is reached."}, {"id": "gk_696", "t": "dialogue", "text": "[DIALOGUE] Default dialogue settings (default sprite, default TextMeshPro font, continue/end button fonts) are configured by clicking on empty space in the Dialogue Editor window, applying to all nodes unless overridden per-node.. Context: The editor provides global defaults that can be set once and then selectively overridden on individual speech nodes for character-specific styling."}, {"id": "gk_697", "t": "dialogue", "text": "[DIALOGUE] Dialogue conversations should be edited on GameObjects in the scene hierarchy rather than on prefabs, as editing prefab-based conversations may fail to save the dialogue data properly.. Context: A known limitation of the Dialogue Editor asset is that prefab-based conversation editing may not persist changes, so in-scene editing is recommended."}, {"id": "gk_698", "t": "dialogue", "text": "[DIALOGUE] DialogLine extends Resource and has properties: text, time_between_letters (character processing delay), and read_time (delay until next line). Context: The dialogue system is built with Godot custom resources for reusability across projects."}, {"id": "gk_699", "t": "dialogue", "text": "[DIALOGUE] Dialogue resource has a name/ID field and an array of DialogLine resources. Context: Each Dialogue groups multiple DialogLine entries under a single identifier."}, {"id": "gk_700", "t": "dialogue", "text": "[DIALOGUE] Each NPC has a DialogueManager node that contains an array of Dialogue resources. Context: The DialogueManager component holds all dialogues for a given NPC, making the system modular and portable."}, {"id": "gk_701", "t": "dialogue", "text": "[DIALOGUE] NPC interaction is triggered by pressing the E key, which displays dialogue text on screen. Context: Player presses E near an NPC to initiate conversation, demonstrated with a red ball NPC saying 'Hello I'm a red ball'."}, {"id": "gk_702", "t": "dialogue", "text": "[DIALOGUE] Dialogues are created via Godot's custom resource system: New Resource > Dialogue, then managed under NPC Dialogues in the inspector. Context: The workflow uses Godot's built-in resource creation UI to define and assign dialogues to NPCs."}, {"id": "gk_703", "t": "dialogue", "text": "[DIALOGUE] The dialogue system is designed to be project-portable \u2014 it can be dropped into any new Godot project and work standalone. Context: The resource-based architecture with DialogLine, Dialogue, and DialogueManager is self-contained and reusable."}, {"id": "gk_704", "t": "NPC dialogue trigger", "text": "[NPC DIALOGUE TRIGGER] NPC dialogue is triggered by proximity detection using a sphere collider centered on the NPC with mesh renderer removed and isTrigger enabled, allowing the player to walk through it. Context: A trigger sphere around the NPC detects when the player enters range, enabling interaction without physical collision blocking movement"}, {"id": "gk_705", "t": "dialogue trigger condition", "text": "[DIALOGUE TRIGGER CONDITION] Player detection uses OnTriggerEnter to set a boolean playerDetection=true when the collider name matches 'Player', and OnTriggerExit to set it back to false. Context: The boolean tracks whether the player is within interaction range of the NPC using Unity's trigger collision callbacks"}, {"id": "gk_706", "t": "dialogue input condition", "text": "[DIALOGUE INPUT CONDITION] In Update(), the system checks if playerDetection is true AND the player presses the F key to start the dialogue interaction. Context: Two conditions must be met simultaneously: proximity (boolean flag) and player input (keypress), forming a simple branch condition for dialogue activation"}, {"id": "gk_707", "t": "NPC conversation variable", "text": "[NPC CONVERSATION VARIABLE] A boolean variable called playerDetection serves as the state flag that gates whether NPC dialogue can be initiated, toggled by trigger enter/exit events. Context: This pattern of using a boolean flag toggled by proximity events is the foundational variable pattern for NPC conversation systems"}, {"id": "gk_708", "t": "dialogue", "text": "[DIALOGUE] Typewriter-style dialogue systems that require player input (e.g., pressing A) between each line create unnecessary interaction friction; auto-advancing dialogue where characters keep talking without button prompts creates conversational fluidity.. Context: Developer removed the press-to-advance mechanic so NPC conversations flowed continuously without player interruption."}, {"id": "gk_709", "t": "dialogue", "text": "[DIALOGUE] Branching dialogue trees grow exponentially when NPCs use open-ended or polite phrasing (e.g., 'Could we sit down and speak?') because each optional action requires writing a refusal branch; replacing with direct/authoritative NPC lines (e.g., 'You're under arrest') eliminates entire branch paths.. Context: A cop NPC offering to sit down required branches for the player refusing, negotiating, etc., but a forceful arrest line removed all those branches."}, {"id": "gk_710", "t": "dialogue", "text": "[DIALOGUE] Dialogue branch conditions should only exist when the player choice adds meaningful narrative value; if a branch (e.g., 'I don't want to sit down') doesn't change outcomes or add story content, it should be eliminated entirely rather than written out.. Context: Developer applied a 'does this branch add anything?' filter to prune unnecessary dialogue tree paths."}, {"id": "gk_711", "t": "dialogue", "text": "[DIALOGUE] Cinematic editing principles (cutting meals, bathroom breaks, pleasantries) can be applied to game dialogue by reducing NPC conversations to only the essential lines that drive the scene forward, skipping realistic but non-functional exchanges.. Context: Developer realized games can streamline reality the same way movies cut non-essential moments from scenes."}, {"id": "gk_712", "t": "dialogue", "text": "[DIALOGUE] NPC conversation triggers should force the scene state directly (e.g., putting the player on the floor) rather than requesting cooperation, because forced state transitions eliminate the need for response-branch conditions handling player refusal.. Context: By having the cop NPC force the player to the floor instead of asking, the developer avoided writing conditional branches for player non-compliance."}, {"id": "gk_713", "t": "dialogue", "text": "[DIALOGUE] Early dialogue scripts tend to be overwritten with realistic conversational filler; iterative reduction passes that ask 'what are the basic things that have to be said' produce tighter, more effective dialogue trees with fewer branches and variables to track.. Context: Developer learned through iteration that reducing dialogue to essential beats improved both the writing quality and the system complexity."}, {"id": "gk_714", "t": "inventory", "text": "[INVENTORY] Inventory system populates slots as items are collected; clicking a slot displays item info, clicking again uses the item (e.g., heal); right-click drops items which respawn on the map.. Context: Unity inventory system tutorial covering core slot-based pickup, use, and drop mechanics."}, {"id": "gk_715", "t": "inventory", "text": "[INVENTORY] Inventory UI is designed to be minimalistic and semi-transparent so gameplay action remains visible behind it, inspired by Hollow Knight.. Context: UI design choice for a slot-based inventory overlay that doesn't fully obscure the game world."}, {"id": "gk_716", "t": "inventory", "text": "[INVENTORY] The inventory system is built as a multi-part series with a planned extension for an equipment system that pairs with the inventory.. Context: Architecture is modular enough to separate inventory (collect/use/drop) from equip/unequip functionality."}, {"id": "gk_717", "t": "inventory", "text": "[INVENTORY] Quick slots UI allows dragging items from inventory grid into numbered slots (1-4), pressing number keys selects that tool which then appears in the player's hand for use.. Context: Standard survival game pattern where equippable tools are dragged from inventory into quick slot bar and activated via number keys."}, {"id": "gk_718", "t": "inventory", "text": "[INVENTORY] Items can be removed by dragging them into a trash can UI element to delete them, right-clicking consumable items refills player status bars, and hovering shows item info tooltip.. Context: Core inventory interactions: drag-to-trash deletion, right-click consume, hover for info."}, {"id": "gk_719", "t": "inventory", "text": "[INVENTORY] When inventory or any menu is open, player interaction with world items must be disabled \u2014 otherwise players can still select and pick up items while the inventory UI is visible.. Context: Bug fix: opening inventory should block world item interaction to prevent unintended pickups."}, {"id": "gk_720", "t": "inventory", "text": "[INVENTORY] Cursor visibility is set to false at game start (in inventory system Start method), toggled to visible when inventory or crafting panel opens, and back to invisible when closed.. Context: Cursor management pattern ensures cursor only appears during UI interaction, critical for built game vs editor."}, {"id": "gk_721", "t": "inventory", "text": "[INVENTORY] Selected world items remain visually selected (highlighted hand icon) when inventory opens if interaction is not disabled, requiring explicit deselection logic on menu open.. Context: Edge case where item selection state persists across UI state changes needs to be handled."}, {"id": "gk_722", "t": "inventory", "text": "[INVENTORY] Equip system uses drag-and-drop from inventory grid slots into dedicated quick slot UI elements, with the equipped item model appearing in the player character's hand when the corresponding number key is pressed.. Context: Equip workflow: inventory slot \u2192 drag to quick slot \u2192 press number key \u2192 item renders in hand."}, {"id": "gk_723", "t": "inventory", "text": "[INVENTORY] Items are implemented as ScriptableObjects (data containers) rather than MonoBehaviours, meaning they persist between playthroughs and don't use Start/Update methods.. Context: ScriptableObjects serve as the data backbone for inventory items, storing properties like item name, stat to change, and amount to change."}, {"id": "gk_724", "t": "inventory", "text": "[INVENTORY] A [CreateAssetMenu] attribute is added above the ScriptableObject class so Unity's Create menu gains an 'item scriptable object' option for authoring new items directly in the editor.. Context: This lets designers right-click in the Assets folder and create item definitions without writing code."}, {"id": "gk_725", "t": "inventory", "text": "[INVENTORY] Each item ScriptableObject has a public string itemName field that the InventoryManager uses as a dictionary key to identify which item is being clicked or used.. Context: The itemName acts as a lookup key so the manager knows what logic to execute per item."}, {"id": "gk_726", "t": "inventory", "text": "[INVENTORY] Item stat effects use a public enum StatToChange with values {None, Health, Mana, Stamina}, exposed as a dropdown in the Unity Inspector, paired with a public int amountToChangeStat for the effect magnitude.. Context: Enums give designers a dropdown to pick which player stat an item modifies and by how much."}, {"id": "gk_727", "t": "inventory", "text": "[INVENTORY] A second enum pattern for attributes (Strength, Defense, Intelligence, Agility) can be added alongside StatToChange to let items modify both stats and attributes independently.. Context: Multiple enums allow items to affect different categories of player properties from a single ScriptableObject."}, {"id": "gk_728", "t": "inventory", "text": "[INVENTORY] Item ScriptableObjects are dragged into the InventoryManager's itemScriptableObject slots on the inventory canvas to register them, building a dictionary of all items that exist in the game.. Context: The manager references each item SO so it can resolve clicks on inventory slots to the correct item data and behavior."}, {"id": "gk_729", "t": "inventory_ui_sorting", "text": "[INVENTORY_UI_SORTING] Inventory list UI uses clickable column headers (name, value, etc.) to sort items by that column, similar to SkyUI menu system from Skyrim.. Context: Column-based sorting allows players to organize inventory by different attributes like weapon name or item value."}, {"id": "gk_730", "t": "inventory_template_pattern", "text": "[INVENTORY_TEMPLATE_PATTERN] A single disabled menu item template GameObject is cloned at runtime for each inventory entry; the template stays disabled so it doesn't render, and copies are instantiated per item in the array.. Context: Using a template prefab pattern avoids manually creating UI elements for every inventory item."}, {"id": "gk_731", "t": "inventory_data_model", "text": "[INVENTORY_DATA_MODEL] Each inventory item type (e.g., weapons) is represented as a ScriptableObject instance in Unity, and an array of these ScriptableObjects is assigned to a manager script via drag-and-drop in the inspector.. Context: ScriptableObjects decouple item data from scene objects, making it easy to add new item types."}, {"id": "gk_732", "t": "inventory_item_details", "text": "[INVENTORY_ITEM_DETAILS] Clicking an item in the scrollable inventory list on the left updates a detail panel on the right showing that item's attributes.. Context: A master-detail UI pattern lets players browse items quickly while seeing full info for the selected one."}, {"id": "gk_733", "t": "inventory_item_attributes", "text": "[INVENTORY_ITEM_ATTRIBUTES] Menu item entries initially only display a name field; value is being added as a second column attribute, with manual spacing used for alignment.. Context: Item attributes like name and value are rendered as separate text fields within each list row."}, {"id": "gk_734", "t": "inventory", "text": "[INVENTORY] Inventory UI uses a dedicated Canvas with Canvas Scaler set to 'Scale with Screen Size' at reference resolution 1920x1080 to handle multiple resolutions.. Context: The canvas scalar component must be changed from constant pixel size to scale with screen size for automatic resolution adjustment."}, {"id": "gk_735", "t": "inventory", "text": "[INVENTORY] Inventory menu panel hierarchy: Canvas > Inventory Menu (panel) > Inventory Slots (panel) + Inventory Description (panel); Inventory Slots contains Item Slot sub-panels (turned into prefabs for duplication); Description contains Item Image and Item Description panels.. Context: The UI is structured as nested panels where item slots become prefabs that are copied to create the full grid."}, {"id": "gk_736", "t": "inventory", "text": "[INVENTORY] Inventory menu uses a semi-transparent black background (alpha ~40) for a Hollow Knight-style minimalist see-through overlay that still shows gameplay behind it.. Context: Panel Image color is set to black with low alpha so the player can still partially see the game world."}, {"id": "gk_737", "t": "inventory", "text": "[INVENTORY] Inventory menu rect transform uses margins of 150 on left/right sides and 140 on top/bottom to inset the panel from screen edges.. Context: These specific margin values are chosen to fit nicely with additional panels added later."}, {"id": "gk_738", "t": "inventory", "text": "[INVENTORY] A Horizontal Layout Group component on the Inventory Menu parent controls the left (slots) and right (description) child panels, with padding of 25 on all sides and 'Force Expand' disabled.. Context: The horizontal layout group lets the parent automatically arrange the two inventory sections side by side."}, {"id": "gk_739", "t": "inventory", "text": "[INVENTORY] The inventory UI layout has slots grid on the left side and a zoomed-in item image with text description on the right side, and the menu is toggled via a button press that also pauses the game.. Context: This two-panel design separates browsing items from viewing item details, with game pause on menu open."}, {"id": "gk_740", "t": "inventory", "text": "[INVENTORY] Inventory grid is configured by specifying slots count, slots per row, and rows per page \u2014 e.g., 80 slots, 4 per row, 5 rows per page creates paginated pages of 5\u00d74 grids. Context: Nakshatra inventory system uses a grid layout with pagination via next/previous buttons"}, {"id": "gk_741", "t": "inventory", "text": "[INVENTORY] Slot prefab is 'inventory slot UI' prefab reused across inventory grid, quick access bar, and equipment panel; cell size set via grid layout (e.g., 100x100 for inventory, 65x65 for quick access bar). Context: The same slot prefab is customizable but should be backed up before modification"}, {"id": "gk_742", "t": "inventory", "text": "[INVENTORY] Quick access bar uses a button number text prefab that displays the item quantity for stacked items, with configurable slot count (e.g., 9 slots). Context: Stacked item quantities are shown as overlay text on quick access bar slots"}, {"id": "gk_743", "t": "inventory", "text": "[INVENTORY] Equipment panel is created via the inventory system window which auto-adds an equipment component to the player and auto-references each slot's game object. Context: This avoids manual prefab placement and ensures correct slot-to-component wiring for equip/unequip"}, {"id": "gk_744", "t": "inventory", "text": "[INVENTORY] Save/load functionality requires inventory component, quick access bar component, and equipment component on the player to all reference the same item DB asset. Context: The item DB asset maintains the master list of all created items and must be linked to each component"}, {"id": "gk_745", "t": "inventory", "text": "[INVENTORY] Currency system supports tiered conversion: copper converts to silver at a set conversion rate, silver converts to gold \u2014 each currency has an icon and a numeric conversion threshold. Context: Currency is created through the inventory manager window with icon selection and conversion rate per tier"}, {"id": "gk_746", "t": "inventory", "text": "[INVENTORY] Object pickup uses a tag-based system: create a 'can pick up' tag applied to all pickupable objects, then raycast or check against this tag to determine if an object can be picked up.. Context: Unity FPS pickup system using tags to identify interactive objects."}, {"id": "gk_747", "t": "inventory", "text": "[INVENTORY] Held objects are positioned using an empty GameObject called 'hold position' parented under the camera, dragged to the desired hold distance in front of the player.. Context: The hold position transform defines where picked-up objects are carried relative to the player camera."}, {"id": "gk_748", "t": "inventory", "text": "[INVENTORY] When picking up an object, its rigidbody is set to kinematic, which prevents physics forces but causes wall clipping; this is solved by rendering the held object on a separate 'hold layer' with a dedicated camera using depth-only clear flags and depth value 1.. Context: Two-camera rendering technique ensures held objects always render in front of world geometry without actual collision changes."}, {"id": "gk_749", "t": "inventory", "text": "[INVENTORY] The pickup camera settings are: clear flags set to 'Depth Only', culling mask set to only the hold layer, near clipping plane set to 0.01, and depth set to 1; the main camera's culling mask deselects the hold layer.. Context: Specific camera configuration values to separate held-object rendering from world rendering in Unity."}, {"id": "gk_750", "t": "inventory", "text": "[INVENTORY] Object rotation while held uses mouse axes applied directly to the object's rotation, requiring the mouse look/character controller script to be disabled during rotation and re-enabled after to prevent simultaneous camera movement.. Context: Rotating held objects requires temporarily disabling player look controls since both use mouse input."}, {"id": "gk_751", "t": "inventory", "text": "[INVENTORY] The pickup script is attached to the player's camera object and requires two references: a public reference to the player GameObject and a public Transform reference to the hold position.. Context: Script architecture for FPS pickup system with camera-based interaction."}, {"id": "gk_752", "t": "inventory", "text": "[INVENTORY] Inventory system built on ScriptableObjects allows data to persist between scenes as long as each scene contains a reference to the inventory ScriptableObject asset.. Context: ScriptableObjects serve as the data backbone so inventory state survives scene transitions without extra serialization."}, {"id": "gk_753", "t": "inventory", "text": "[INVENTORY] Items support drag-and-drop reordering in the UI grid, and the rearranged order persists when the inventory is closed and reopened.. Context: Drag-and-drop lets players organize their inventory slots and the layout is saved automatically."}, {"id": "gk_754", "t": "inventory", "text": "[INVENTORY] Right-click context menus provide item-specific actions: consumables show 'Eat' and 'Drop', while equipment shows 'Equip' and 'Drop'.. Context: Each item type defines its own set of right-click actions, enabling different functionality per item category."}, {"id": "gk_755", "t": "inventory", "text": "[INVENTORY] Consumable items like apples have a stack count that decreases on use (eating); when the stack reaches zero the item is removed from the inventory.. Context: Stackable consumables are depleted one at a time and auto-removed when fully consumed."}, {"id": "gk_756", "t": "inventory", "text": "[INVENTORY] Equipping an item removes it from the inventory and moves it to an equipment slot; if a slot is already occupied, the previously equipped item is returned to the inventory with its current durability.. Context: Equip/unequip swaps items between inventory grid and equipment slots, preserving per-instance stats like durability."}, {"id": "gk_757", "t": "inventory", "text": "[INVENTORY] The architecture uses Model-View-Controller (MVC): the Model is the inventory ScriptableObject, the View is the inventory UI, and a Controller separates logic from presentation for maintainability.. Context: MVC pattern keeps inventory data, display, and interaction logic decoupled for cleaner code."}, {"id": "gk_758", "t": "lighting", "text": "[LIGHTING] Set color space to Linear under Edit > Project Settings > Player for physically accurate lighting calculations. Context: Linear color space is a prerequisite for realistic lighting and post-processing in Unity."}, {"id": "gk_759", "t": "lighting", "text": "[LIGHTING] Set camera render path to Deferred to support advanced lighting features like multiple dynamic lights and better light interaction. Context: Deferred rendering is required for high-quality lighting setups with reflection probes and post-processing."}, {"id": "gk_760", "t": "lighting", "text": "[LIGHTING] Add a Reflection Probe (right-click in hierarchy) and bake it to capture environment reflections on nearby surfaces. Context: Baked reflection probes store cubemap snapshots of the scene for realistic material reflections."}, {"id": "gk_761", "t": "lighting", "text": "[LIGHTING] Use Post Processing stack with ACES tone mapping on the Color Grading effect to achieve accurate, cinematic color response. Context: ACES tone mapping maps HDR values to display range while preserving color accuracy and contrast."}, {"id": "gk_762", "t": "ambient_occlusion", "text": "[AMBIENT_OCCLUSION] Amplify Occlusion (free asset) produces better ambient occlusion results than Unity's built-in screen-space ambient occlusion. Context: Third-party AO solutions can offer higher quality contact shadows and cavity darkening at comparable performance cost."}, {"id": "gk_763", "t": "lighting", "text": "[LIGHTING] Increase directional light intensity to compensate for scene darkening caused by linear color space and ACES tone mapping. Context: Switching to linear color space and ACES often darkens the scene, requiring directional light and color grading adjustments."}, {"id": "gk_764", "t": "lighting", "text": "[LIGHTING] Lumen is UE5's default global illumination method focused on indirect realtime lighting; to use baked lighting instead, set global illumination method to 'None' in both viewport and project settings to disable Lumen. Context: When switching to GPU Lightmass baking, Lumen must be explicitly disabled in project settings by setting global illumination to none"}, {"id": "gk_765", "t": "lighting", "text": "[LIGHTING] GPU Lightmass is an experimental UE5 plugin that bakes lights using RTX hardware ray tracing instead of CPU, requiring 'Support Hardware Ray Tracing' and 'Use Hardware Ray Tracing when enabled' both checked in Project Settings. Context: GPU Lightmass leverages the GPU's RTX cores for significantly faster light baking compared to CPU Lightmass"}, {"id": "gk_766", "t": "lighting", "text": "[LIGHTING] For baked lighting, all lights (directional, sky, point) must be set to Static or Stationary mobility \u2014 Movable lights cannot be baked. Context: Before running a light build, each light actor's mobility must be changed from Movable to Stationary or Static"}, {"id": "gk_767", "t": "lighting", "text": "[LIGHTING] A lightmap is a texture that stores pre-calculated baked lighting information per static mesh, while Lightmass is the actual renderer/tool that performs the ray tracing calculations to generate those lightmaps. Context: Lightmap and Lightmass are distinct concepts: lightmap is the output texture, Lightmass is the baking renderer"}, {"id": "gk_768", "t": "lighting", "text": "[LIGHTING] Virtual Texture Support must be enabled in project settings for GPU Lightmass to function, as it splits the scene's large lightmap into smaller pieces for optimized next-gen rendering. Context: Virtual textures allow the baked lightmap to be divided and streamed piece by piece rather than loaded as one large texture"}, {"id": "gk_769", "t": "lighting", "text": "[LIGHTING] Disabling real-time viewport rendering (VP Realtime off) during GPU Lightmass baking significantly speeds up the build process. Context: Turning off the viewport's realtime rendering frees GPU resources for the light baking operation"}, {"id": "gk_770", "t": "lighting", "text": "[LIGHTING] Cloud shading alone costs 5 milliseconds at 1080p on a 13 teraflop machine, covering only half the frame surface area. Context: Demonstrates how a single atmospheric lighting effect can consume a significant portion of the frame budget on high-end hardware"}, {"id": "gk_771", "t": "lighting", "text": "[LIGHTING] Unreal Engine 5.5 cloud shading runs over 800% slower than Unreal Engine 5.4 and still relies on temporal smear abuse to hide jittering artifacts. Context: Major performance regression in a core atmospheric lighting system between engine versions, indicating unstable indirect lighting pipeline"}, {"id": "gk_772", "t": "lighting", "text": "[LIGHTING] A realistic third-person action game scene is typically 75% static objects and 25% dynamic elements (characters, breakable objects, vehicles, moving light occluders like doors/windows, and togglable light sources). Context: This static-to-dynamic ratio is critical for deciding what lighting can be baked vs realtime, and mirrors hundreds of shipped 9th-gen titles"}, {"id": "gk_773", "t": "lighting", "text": "[LIGHTING] PS4 rendered 8th-gen visuals at 1080p 30fps on 1.9 teraflops; doubling frame rate to 60fps requires ~2x power, fitting within PS5 budget with large headroom for 9th-gen visual improvements. Context: Frame budget math showing that targeting 1080p60 leaves significant GPU headroom for advanced lighting features like global illumination and ambient occlusion"}, {"id": "gk_774", "t": "lighting", "text": "[LIGHTING] Moving from 1080p to 4K requires 4x computational power, consuming over half the available hardware resources just to maintain baseline visual fidelity. Context: Explains why 4K targets severely limit the budget available for realtime global illumination, shadow distance, and ambient occlusion quality"}, {"id": "gk_775", "t": "lighting", "text": "[LIGHTING] Moving light occluders (doors, windows) and togglable light sources are classified as dynamic elements requiring realtime lighting solutions rather than baked approaches. Context: Identifies specific gameplay objects that force realtime shadow and indirect lighting calculations, impacting global illumination strategy"}, {"id": "gk_776", "t": "lighting", "text": "[LIGHTING] Light mapping UVs must be set up on UV Channel 2 with no overlapping UV islands to prevent light bleeding and pixelation artifacts in baked lightmaps.. Context: Unity 6 URP scene breakdown showing how custom light mapping UVs are separate from texture UVs."}, {"id": "gk_777", "t": "lighting", "text": "[LIGHTING] Static objects should be marked as static to be included in baked lightmaps, while dynamic/moving objects should not be marked static and should use light probes instead for indirect lighting.. Context: Explains the static vs dynamic object workflow for Unity's baked lighting pipeline."}, {"id": "gk_778", "t": "lighting", "text": "[LIGHTING] Unity can auto-generate light mapping UVs from existing UV channels, but this often causes issues; manually authored Channel 2 UVs with non-overlapping islands produce cleaner bakes.. Context: Demonstrates the Generate Lightmap UVs option in Unity's mesh import settings and its common pitfalls."}, {"id": "gk_779", "t": "lighting", "text": "[LIGHTING] PBR material workflow using base color map, emissive map, mask map, and metallic/smoothness maps ensures assets look correct under any lighting scenario including baked and realtime.. Context: Arch viz assets authored in Substance Painter following PBR standards for Unity 6 URP and HDRP."}, {"id": "gk_780", "t": "emissive", "text": "[EMISSIVE] Emissive maps are included as part of the standard PBR texture set (base color, emissive, mask/metallic/smoothness) for arch viz models, contributing to both baked and realtime illumination.. Context: Breakdown of texture channels used on high-quality arch viz furniture and environment assets."}, {"id": "gk_781", "t": "lighting", "text": "[LIGHTING] Gathering real-world reference images before building a scene helps determine directional light angle, additional light placement, and overall mood for realistic lighting setups.. Context: Workflow advice for planning lighting in Unity arch viz scenes before placing any lights."}, {"id": "gk_782", "t": "ambient_occlusion", "text": "[AMBIENT_OCCLUSION] AO maps enhance shadows by adding subtle contact shadows in crevices and cracks, bringing out depth in materials without additional geometry cost.. Context: HDRP uses AO maps as part of the material pipeline to simulate realistic shadowing in surface details."}, {"id": "gk_783", "t": "ambient_occlusion", "text": "[AMBIENT_OCCLUSION] In HDRP, ambient occlusion is not assigned directly to the lit shader but is channel-packed into the mask map, stored in a specific color channel of a single RGBA texture alongside metallic and roughness maps.. Context: HDRP uses channel-packed textures (mask map) to combine AO, metallic, roughness, and other grayscale maps into one texture for efficient single-fetch sampling."}, {"id": "gk_784", "t": "lighting", "text": "[LIGHTING] Normal maps simulate bumps and grooves by altering how light interacts with the surface without increasing geometry; in HDRP the texture type must be set to 'normal map' in import settings.. Context: Correct normal map import settings are critical for HDRP's physically-based lighting to interact with surface detail properly."}, {"id": "gk_785", "t": "lighting", "text": "[LIGHTING] Height maps displace actual surface geometry (unlike normal maps which only simulate it) and require the HDRP Lit shader's displacement mode set to 'Tessellation Displacement' with tessellation mode set to 'Full'.. Context: Real geometric displacement via height maps costs more performance but creates true depth, useful for materials like cobblestones."}, {"id": "gk_786", "t": "lighting", "text": "[LIGHTING] HDRP channel-packed mask map stores four grayscale maps (metallic, AO, detail mask, smoothness) in RGBA channels of a single texture, allowing the renderer to sample all four with a single texture fetch.. Context: Channel packing is a core HDRP optimization that reduces texture sampling overhead for physically-based materials."}, {"id": "gk_787", "t": "lighting", "text": "[LIGHTING] When importing textures for HDRP materials, set texture type to 'default' (except normal maps) and disable sRGB for grayscale maps like metallic, smoothness, and AO to ensure correct linear-space interpretation.. Context: Incorrect sRGB settings cause HDRP's PBR pipeline to misinterpret material data, producing flat or incorrect lighting responses."}, {"id": "gk_788", "t": "networking", "text": "[NETWORKING] ClientNetworkTransform overrides NetworkTransform with IsServerAuthoritative returning false, allowing client-controlled movement without server round-trip for snappy response, while still implementing server reconciliation for 100% server authority. Context: Unity Netcode pattern where client predicts movement locally but server remains authoritative through reconciliation"}, {"id": "gk_789", "t": "networking", "text": "[NETWORKING] Unity Netcode for GameObjects v1.4 requires NetworkManager component with Unity Transport set to localhost, and each player prefab needs a NetworkObject component plus NetworkTransform for sync. Context: Basic netcode setup requires transport layer configuration and network-aware components on all synced prefabs"}, {"id": "gk_790", "t": "networking", "text": "[NETWORKING] NetworkManager.Singleton.StartHost() or StartClient() are the entry points for multiplayer sessions, with host combining server and client in one instance. Context: Network session initialization uses singleton pattern with host/client split for local testing and deployment"}, {"id": "gk_791", "t": "networking", "text": "[NETWORKING] Syncing rigid bodies between server and clients is the core challenge of networked physics; client-side prediction avoids round-trip latency while server reconciliation corrects drift. Context: Rigid body synchronization is identified as the main difficulty in multiplayer netcode for physics-based games"}, {"id": "gk_792", "t": "networking", "text": "[NETWORKING] ClientNetworkTransform syncs position and rotation but scale sync can be disabled to reduce unnecessary network traffic. Context: Selective transform component syncing reduces bandwidth by only transmitting values that actually change during gameplay"}, {"id": "gk_793", "t": "networking", "text": "[NETWORKING] Two main multiplayer architectures: dedicated servers (server-authoritative, harder to cheat, more costly) vs peer-to-peer (one player hosts as both server and client, cheaper but easier to cheat). Context: Choosing between dedicated servers for competitive games and peer-to-peer for casual games is the first architectural decision in multiplayer game development."}, {"id": "gk_794", "t": "networking", "text": "[NETWORKING] Server-authoritative model: server moves all players and handles all logic while clients only send input. Alternative: each client moves their own character and position is synchronized, giving smoother gameplay but easier to cheat.. Context: The client-authoritative movement approach trades cheat resistance for smoother gameplay and is suitable for casual multiplayer games."}, {"id": "gk_795", "t": "networking", "text": "[NETWORKING] Unity's default NetworkTransform is server-authoritative (only server can move it). To allow client-authoritative movement, create a custom ClientNetworkTransform script that overrides the OnIsServerAuthoritative method to return false.. Context: Client-side prediction in Unity Netcode for GameObjects requires overriding the default server-authoritative transform to let clients directly modify their own position."}, {"id": "gk_796", "t": "networking", "text": "[NETWORKING] NetworkTransform sync settings: only check the variables you want to sync (position axes, rotation axes, scale) to avoid sending unnecessary data and reduce bandwidth/latency.. Context: Minimizing synced variables reduces network overhead, which is critical for lag compensation in multiplayer games."}, {"id": "gk_797", "t": "networking", "text": "[NETWORKING] NetworkVariable with configurable read/write permissions can represent synced game state like player health. Scripts must extend NetworkBehaviour (not MonoBehaviour) and use OnNetworkSpawn instead of Start for initialization.. Context: Network variables provide a permission-controlled way to synchronize game state across the network with server reconciliation of who can read/write values."}, {"id": "gk_798", "t": "networking", "text": "[NETWORKING] Ownership check pattern: in OnNetworkSpawn, check IsOwner to deactivate extra cameras for non-owned players. In Update, gate movement input behind IsOwner so clients only control their own character.. Context: The IsOwner check is the fundamental client prediction pattern ensuring each client only processes input and controls movement for their own networked player object."}, {"id": "gk_799", "t": "client-side prediction", "text": "[CLIENT-SIDE PREDICTION] Client-side prediction uses the same shared movement processing code as the server, feeding it the entity's current state and the player's input to compute the predicted position locally without waiting for the server response.. Context: A shared library ensures both client and server produce identical movement results given the same starting state and input."}, {"id": "gk_800", "t": "server reconciliation", "text": "[SERVER RECONCILIATION] Reconciliation compares the client's predicted position against the server's authoritative state; if they match (e.g., both at 1,0), the prediction is accepted, otherwise the client must accept the authoritative state and resolve the misprediction.. Context: Predictions must eventually be validated against the server's authoritative response to detect and correct drift."}, {"id": "gk_801", "t": "tick accumulation during latency", "text": "[TICK ACCUMULATION DURING LATENCY] Multiple movement ticks occur between sending input and receiving the server's state response (e.g., client advances from 1,0 to 2,0 to 3,0 while waiting), causing the client's current position to diverge from the authoritative state which only reflects tick 1.. Context: On anything other than LAN, several simulation ticks will elapse during the round-trip, so naive comparison of current client state vs server state will always show a mismatch."}, {"id": "gk_802", "t": "state history for reconciliation", "text": "[STATE HISTORY FOR RECONCILIATION] The client needs a programmatic way to map a past local state to the corresponding server tick \u2014 e.g., knowing that the local position of 1,0 at tick N corresponds to the server's authoritative state for that same tick \u2014 requiring a history buffer of past predicted states.. Context: Without storing historical states indexed by tick, the client cannot compare the correct past prediction against the arriving authoritative update."}, {"id": "gk_803", "t": "deterministic simulation", "text": "[DETERMINISTIC SIMULATION] Prediction accuracy depends on both client and server starting from the same state (e.g., both at 0,0) and using identical movement logic with the same input, guaranteeing deterministic outcomes like both arriving at 1,0.. Context: Shared code and identical starting conditions are prerequisites for client predictions to match server results."}, {"id": "gk_804", "t": "input-to-state pipeline", "text": "[INPUT-TO-STATE PIPELINE] Without client prediction, pressing a key (e.g., D to move right) sends input to the server and the client must wait for the full round-trip before rendering any movement, creating perceived input lag equal to the network latency.. Context: This wait-for-authority approach is the baseline problem that client-side prediction solves."}, {"id": "gk_805", "t": "networking", "text": "[NETWORKING] Authoritative server architecture means all game logic and calculations run on a central server; clients only send inputs while the server manages the entire game state, preventing hacked clients from modifying values like health or position. Context: Core anti-cheat principle for competitive multiplayer: never trust the client, always validate on the server"}, {"id": "gk_806", "t": "networking", "text": "[NETWORKING] The server update loop follows a three-step cycle: clients send actions to the server, the server updates the game state periodically (tick), then sends the new game state back to all clients. Context: Fundamental authoritative server loop that governs how state is synchronized across all connected players"}, {"id": "gk_807", "t": "networking", "text": "[NETWORKING] UDP is preferred over TCP for fast-paced multiplayer because TCP has significant per-packet overhead and causes head-of-line blocking, which is brutal for FPS multiplayer experience. Context: Transport protocol selection for competitive shooters often leads to implementing a custom reliable-UDP layer"}, {"id": "gk_808", "t": "networking", "text": "[NETWORKING] Delta compression and optimized serialization strategies are used to squeeze maximum information into the smallest number of bits, critical for scaling to 50-100 players on a single server. Context: Bandwidth optimization is essential when a server must keep 100 players updated with world state every tick"}, {"id": "gk_809", "t": "networking", "text": "[NETWORKING] Without client-side prediction, a round-trip latency of ~200ms creates a perceivable delay between player input and character movement; at 500ms the game becomes unplayable. Context: Raw server-authoritative input-response loop exposes full round-trip latency to the player"}, {"id": "gk_810", "t": "networking", "text": "[NETWORKING] Client-side prediction, snapshot interpolation, and lag compensation are the three core techniques that solve input-to-response latency in authoritative multiplayer games. Context: These methods work together to make the game feel responsive despite network delay between client and server"}, {"id": "gk_811", "t": "networking", "text": "[NETWORKING] For fast-moving multiplayer objects, custom extrapolation outperforms Unity's built-in NetworkTransform, NetworkRigidBody, and interpolation \u2014 it reaches endpoints faster with less visible delay and stays more in sync across clients.. Context: Demonstrated with five synchronization methods side-by-side: extrapolation, interpolation, NetworkTransform, NetworkRigidBody, and NetworkTransform with interpolation off."}, {"id": "gk_812", "t": "networking", "text": "[NETWORKING] Client-authoritative movement pattern in FixedUpdate: if owner, process local input/movement then send position and velocity to server via RPC; if not owner, extrapolate from previous position+velocity data (or snap without interpolation).. Context: The networked car uses FixedUpdate with an owner check to separate local authority from remote extrapolation logic."}, {"id": "gk_813", "t": "networking", "text": "[NETWORKING] Without interpolation (raw snapping), networked objects appear bouncy and jerk around; NetworkTransform with interpolation is smoother but introduces noticeable positional delay that worsens significantly under poor network conditions (e.g., 2.5G simulation).. Context: Using Unity's network simulator to degrade connection quality amplified the delay and jitter for all methods except custom extrapolation."}, {"id": "gk_814", "t": "networking", "text": "[NETWORKING] The server acts as a relay in client-authoritative movement: client sends position and velocity to the server, which forwards that data to all other clients for extrapolation.. Context: The SendPosition RPC transmits both position and velocity so remote clients can predict movement between updates."}, {"id": "gk_815", "t": "networking", "text": "[NETWORKING] Local movement uses transform rotation from horizontal axis input and sets rigidbody velocity directly on the authoritative client, keeping physics-based movement simple for network replication.. Context: The DoLocalMovement method reads horizontal/vertical axes, rotates the transform, and applies velocity to the non-kinematic rigidbody."}, {"id": "gk_816", "t": "networking", "text": "[NETWORKING] NetworkRigidBody synchronization mostly matches NetworkTransform quality but both lag behind custom extrapolation; the rigidbody on the prefab must NOT be set to kinematic for physics-based networked movement.. Context: The prefab uses a non-kinematic rigidbody alongside NetworkObject, with no NetworkTransform or NetworkRigidBody component on the extrapolated variant."}, {"id": "gk_817", "t": "lag_compensation", "text": "[LAG_COMPENSATION] Server receives a shot packet, reads the latency on that packet, factors in interpolation, infers the exact tick the client fired, rewinds game state to that tick, and checks player positions at that historical time to determine if the shot was a hit.. Context: This is the core lag compensation algorithm used in FPS games to let players aim at what they see on screen despite network delay."}, {"id": "gk_818", "t": "interpolation", "text": "[INTERPOLATION] The client does not render a player at their latest known position; instead it holds off by one tick and smoothly animates the player between the last two known positions. On a 64-tick matchmaking server, ticks arrive every ~16ms, so interpolation adds one tick (~16ms) of visual delay.. Context: Interpolation prevents jerky movement caused by discrete tick updates and unsynchronized refresh rates between GPU, monitor, and server."}, {"id": "gk_819", "t": "latency_budget", "text": "[LATENCY_BUDGET] Total visual delay without lag compensation = (enemy_ping / 2) for enemy's action to reach server + (my_ping / 2) for server to send to me + 1 tick for interpolation + (my_ping / 2) for my shot to reach server. Each half-ping and interp tick compounds the positional discrepancy.. Context: These cumulative delays explain why the position you see, the server's position, and the enemy's self-position all differ at any given moment."}, {"id": "gk_820", "t": "peeker_disadvantage", "text": "[PEEKER_DISADVANTAGE] With lag compensation, you can be hit after going around a corner on your screen because the shooting player's client saw you in the open for the duration of your peek \u2014 the entire peek just occurred after a delay (ping + interp) on the shooter's screen.. Context: This 'shot around corners' effect is lag compensation working correctly, not a bug \u2014 the shooter aimed accurately at what they saw."}, {"id": "gk_821", "t": "hit_priority", "text": "[HIT_PRIORITY] Lag compensation does NOT determine who shot first; the first shot packet to arrive at the server is the one that registers first, giving the lower-ping player an advantage in simultaneous engagements.. Context: Lag compensation only validates aim accuracy by rewinding state, but shot ordering is still determined by network arrival time."}, {"id": "gk_822", "t": "tick_rate", "text": "[TICK_RATE] A standard matchmaking server runs at 64 ticks per second (~16ms per tick). Without interpolation, player positions would visually jump between discrete tick positions, and since GPU refresh rate, monitor refresh rate, and server tick rate are not synchronized, motion appears unsmooth.. Context: The tick rate defines the temporal resolution of the server simulation and directly affects interpolation delay and lag compensation rewind granularity."}, {"id": "gk_823", "t": "client-side prediction", "text": "[CLIENT-SIDE PREDICTION] Client-side prediction works by moving the player locally while waiting for server response, hiding latency in authoritative server architecture. The client sends inputs to the server, moves the player locally using the same movement logic, stores the resulting position in a state buffer, then reconciles when the server response arrives.. Context: Core technique for hiding latency in multiplayer games with authoritative servers."}, {"id": "gk_824", "t": "server reconciliation", "text": "[SERVER RECONCILIATION] Server reconciliation checks if the client's predicted position in the past matches the server's authoritative snapshot for that same tick. When the client receives the server state, it sets rigidbody.position to the server's position and replays any inputs that occurred after that tick.. Context: Corrects mispredictions by comparing past client state against server-confirmed state at the same tick number."}, {"id": "gk_825", "t": "tick-based input buffering", "text": "[TICK-BASED INPUT BUFFERING] Both client state and input history are stored in circular buffers of size 1024, indexed by tick number. Each InputMessage contains a uint tick and an Inputs struct. Each ClientState contains a uint tick, Vector3 position, and Vector3 velocity. The buffer size (1024) defines how far back reconciliation can reach.. Context: Buffer structure enables replaying inputs from any past tick for reconciliation."}, {"id": "gk_826", "t": "client prediction loop", "text": "[CLIENT PREDICTION LOOP] In FixedUpdate: (1) capture current input via SetInput(), (2) create InputMessage with current tick number and input, (3) send InputMessage to server, (4) move the player locally using the input, (5) call Physics.Simulate(Time.fixedDeltaTime), (6) store resulting position in clientStateBuffer at current tick, (7) increment tick number. Moving the player BEFORE storing in the buffer is critical.. Context: Exact per-tick execution order for client-side prediction in Unity using physics simulation."}, {"id": "gk_827", "t": "server authoritative processing", "text": "[SERVER AUTHORITATIVE PROCESSING] On the server when receiving an InputMessage: (1) move the player using the received input, (2) call Physics.Simulate(), (3) create a StateMessage containing rigidbody.position, rotation, velocity, angularVelocity, and set stateMessage.tick = inputMessage.tick, (4) send the StateMessage back to the client. The server echoes back the tick number so the client knows which prediction to compare against.. Context: Server processes inputs in order and returns authoritative state tagged with the corresponding client tick."}, {"id": "gk_828", "t": "physics simulation in netcode", "text": "[PHYSICS SIMULATION IN NETCODE] Both client and server call Physics.Simulate(Time.fixedDeltaTime) manually after applying player movement each tick, ensuring deterministic physics stepping that is synchronized between client prediction and server processing. This manual simulation call is essential for prediction and reconciliation to produce matching results.. Context: Manual physics stepping ensures client and server produce comparable results for the same input at the same tick."}, {"id": "gk_829", "t": "networking", "text": "[NETWORKING] Unity Relay enables multiplayer connections without dedicated servers, port forwarding, or firewall configuration by routing traffic through Unity's relay servers using a join code system.. Context: Relay acts as a connection intermediary so players don't need to share IPs or open ports."}, {"id": "gk_830", "t": "networking", "text": "[NETWORKING] Unity Relay setup requires only three lines of code for basic functionality: allocate a relay, get a join code, and have clients join with that code.. Context: The relay API is minimal, with the bulk of complexity handled by Unity's backend services."}, {"id": "gk_831", "t": "networking", "text": "[NETWORKING] Unity Relay, Lobby, and Netcode for Game Objects are three independent but interoperable tools \u2014 Lobby can automatically share relay join codes so players don't need to manually exchange them.. Context: Combining Lobby with Relay eliminates the need for players to manually share connection codes."}, {"id": "gk_832", "t": "networking", "text": "[NETWORKING] Without a relay or port forwarding solution, peer-to-peer multiplayer only works on the same local machine or LAN \u2014 remote players are blocked by firewalls and NAT.. Context: Direct connections between players fail across the internet due to firewall and NAT traversal issues."}, {"id": "gk_833", "t": "networking", "text": "[NETWORKING] Destructible voxel objects can be synchronized across network in multiplayer by tracking per-voxel health state and replicating damage events to all clients.. Context: A voxel-based Unity3D multiplayer prototype synchronizes player movements, actions, and destructible object state across the network."}, {"id": "gk_834", "t": "networking", "text": "[NETWORKING] Voxel health can be visually indicated by color interpolation (e.g., shifting toward red as health decreases), with this visual state derived from replicated health values rather than syncing color separately.. Context: Damaged voxels become redder to indicate lower health, providing visual feedback synced through health state replication."}, {"id": "gk_835", "t": "networking", "text": "[NETWORKING] A host-or-join server architecture (client-hosted/listen server model) allows one player to act as both server and client, reducing infrastructure needs for prototypes.. Context: The multiplayer prototype uses a model where players can host a server or join an existing one."}, {"id": "gk_836", "t": "networking", "text": "[NETWORKING] Synchronizing destructible environments in multiplayer requires replicating both the destruction events (e.g., cannonball impacts) and the resulting state changes (voxel health/removal) to maintain consistency across clients.. Context: Shooting cannonballs at voxel walls causes damage that must be reflected identically on all connected players' views."}, {"id": "gk_837", "t": "networking", "text": "[NETWORKING] An authoritative server acts as the sole source of truth for game state, making final calls on events like scoring or boundary checks, overriding any client-side calculations that may differ due to lag or slow hardware.. Context: Server authority is compared to a referee who determines the official outcome regardless of what individual clients compute locally."}, {"id": "gk_838", "t": "networking", "text": "[NETWORKING] Client-authoritative architecture lets the client report its own actions (e.g. hit registration, position) directly to the server, which accepts them without independent verification \u2014 reducing server computation but exposing the game to cheating and exploits as the player base grows.. Context: Hybrid and full client-authority models are presented as acceptable for prototyping but problematic at scale."}, {"id": "gk_839", "t": "networking", "text": "[NETWORKING] A hybrid authority model exists where some game events are server-authoritative (e.g. match timing, player count, foul detection) while others are client-authoritative (e.g. player movement or action reporting), balancing development simplicity against cheat resistance.. Context: Developers starting out are advised they can use hybrid authority initially and migrate toward full server authority as their game scales."}, {"id": "gk_840", "t": "networking", "text": "[NETWORKING] When a client has lag or runs on slow hardware, its local calculations can diverge from the true game state, requiring the server to override the client's version of events to maintain consistency across all players.. Context: Lag-induced client desync is the core justification for server-authoritative architecture."}, {"id": "gk_841", "t": "particles", "text": "[PARTICLES] Spawn rate of 20 particles per second with particle lifetime randomized between 1.2 and 1.6 seconds produces good stylized smoke density in Niagara.. Context: Setting up a stylized smoke emitter from scratch in Unreal Engine 5 Niagara system."}, {"id": "gk_842", "t": "particles", "text": "[PARTICLES] For mesh-based smoke VFX, use a mesh renderer instead of sprite renderer to emit custom 3D cloud meshes built from joined ico spheres.. Context: Stylized smoke effect uses remeshed and decimated cloud-shaped meshes rather than flat sprite particles."}, {"id": "gk_843", "t": "particles", "text": "[PARTICLES] Velocity set to cone mode at ~800 units with cone axis (0, 0, 1) makes smoke rise upward; cone angle controls horizontal spread.. Context: Add Velocity module in Niagara with Solve Forces and Velocity to drive upward smoke motion."}, {"id": "gk_844", "t": "particles", "text": "[PARTICLES] Initial particle scale randomized between 1.0 and 2.0 adds size variation to smoke puffs for a more natural look.. Context: Scale set in the initialize particle module of the Niagara emitter."}, {"id": "gk_845", "t": "particles", "text": "[PARTICLES] Shape Location module set to cylinder with zero height and radius of 20 offsets spawn positions so particles don't all emit from a single point.. Context: Prevents uniform spawn clustering by distributing emission across a small cylindrical area."}, {"id": "gk_846", "t": "particles", "text": "[PARTICLES] Custom smoke mesh workflow: create 3-4 ico spheres (subdivision 1) in Blender, join with Ctrl+J, remesh at voxel size 0.5 with smooth shading, then decimate with un-subdivide to lower poly count.. Context: Building a lightweight stylized cloud mesh for use as a Niagara mesh particle."}, {"id": "gk_847", "t": "particles", "text": "[PARTICLES] To create a circuit effect in UE Niagara, start with the default Fountain preset and delete all forces, velocity, and location modules to strip it to basics. Context: Starting point for circuit-style VFX is removing default movement behaviors so particles remain controllable"}, {"id": "gk_848", "t": "particles", "text": "[PARTICLES] Set spawn rate to 100 and particle lifetime to a constant value of 5 for steady circuit particle emission. Context: Using constant lifetime instead of random range ensures uniform particle duration for structured effects"}, {"id": "gk_849", "t": "particles", "text": "[PARTICLES] Curl noise force is added to circuit particles after stripping default forces to create organic flowing circuit-like movement patterns. Context: Curl noise provides swirling, non-repeating motion that mimics electrical current paths"}, {"id": "gk_850", "t": "particles", "text": "[PARTICLES] In Niagara, setting lifetime to constant (e.g. 5) rather than a random range gives predictable particle behavior needed for structured effects like circuits. Context: Constant lifetime prevents randomness that would break the visual coherence of circuit patterns"}, {"id": "gk_851", "t": "particles", "text": "[PARTICLES] Particle effects can be controlled via user parameters (widgets) that expose spawn rate, drag, color, and opacity as editable values, allowing real-time tweaking without modifying the underlying particle system directly.. Context: Demonstrates a modular approach where each particle property (spawn rate, drag, color, opacity) is connected to a user-facing parameter widget for non-destructive editing."}, {"id": "gk_852", "t": "particles", "text": "[PARTICLES] Spawn rate can be exposed as a user parameter and dynamically increased or decreased at runtime to change particle density and visual intensity.. Context: The spawn rate parameter is wired from the particle module settings to an external widget, enabling real-time control over emission frequency."}, {"id": "gk_853", "t": "particles", "text": "[PARTICLES] Drag can be increased or decreased via user parameters to control how quickly particles decelerate, dramatically changing the visual look of the same base effect.. Context: Adjusting drag alongside spawn rate through widgets allows a single particle system to produce many different-looking effects."}, {"id": "gk_854", "t": "particles", "text": "[PARTICLES] A modular particle system architecture connects module settings (color, opacity, spawn rate, drag) to user parameters, enabling widget-based control over the entire effect.. Context: Each module property is linked to a named user parameter, creating a clean separation between the particle logic and its tunable values."}, {"id": "gk_855", "t": "performance", "text": "[PERFORMANCE] Static batching combines multiple static meshes into a single mesh and single draw call, reducing CPU-to-GPU draw call overhead automatically for geometry that never moves.. Context: Unity's built-in optimization that works with every render pipeline and Unity version."}, {"id": "gk_856", "t": "performance", "text": "[PERFORMANCE] A draw call is the CPU telling the GPU to render something; both CPU throughput for issuing calls and GPU capacity for processing them are limited, making excessive draw calls a bottleneck especially on lower-end and mobile devices.. Context: There is no fixed magic number for max draw calls \u2014 it depends on call complexity and platform."}, {"id": "gk_857", "t": "performance", "text": "[PERFORMANCE] Two non-batched cubes plus a background produce 3 separate draw calls (one per object); marking both cubes as batching static reduces this by combining them into a single batch.. Context: Demonstrated in Unity's Frame Debugger showing each individual batch sent to the GPU."}, {"id": "gk_858", "t": "performance", "text": "[PERFORMANCE] Objects must be marked as 'batching static' in the Unity inspector to enable static batching; a runtime API also exists for procedural generation scenarios.. Context: Static batching only works for objects that never move, which is its main drawback."}, {"id": "gk_859", "t": "performance", "text": "[PERFORMANCE] Unity's Frame Debugger (Window > Analysis > Profiler > Rendering > Frame Debugger) allows inspecting each individual draw call batch sent to the GPU and viewing the scene state between batches.. Context: Essential profiling tool for verifying batching effectiveness and diagnosing draw call counts."}, {"id": "gk_860", "t": "performance", "text": "[PERFORMANCE] Unity has built-in occlusion culling that prevents rendering objects hidden behind other objects, significantly improving FPS in scenes with many objects. Context: Occlusion culling skips draw calls for objects not visible to the camera, reducing GPU workload in dense scenes"}, {"id": "gk_861", "t": "performance", "text": "[PERFORMANCE] To enable occlusion culling in Unity: enable it on the Camera component, then open Window > Rendering > Occlusion Culling, select static objects with MeshRenderer, check Occluder and Occludee boxes, and press Bake. Context: This is the standard Unity workflow for setting up occlusion culling on static geometry"}, {"id": "gk_862", "t": "performance", "text": "[PERFORMANCE] Unity occlusion culling only works on static objects that do not move; objects must have a MeshRenderer component and be marked as both Occluder (blocks visibility) and Occludee (can be hidden). Context: The bake process precomputes visibility data for static geometry, so dynamic objects cannot participate in baked occlusion"}, {"id": "gk_863", "t": "performance", "text": "[PERFORMANCE] Unity's occlusion culling requires a bake step that precomputes visibility cells, and results can be verified using the Visualization tab in the Occlusion Culling window. Context: The visualization mode shows which objects are being rendered vs culled in the scene view for debugging"}, {"id": "gk_864", "t": "performance", "text": "[PERFORMANCE] Without occlusion culling, rendering all visible and hidden objects simultaneously causes FPS to drop progressively as the camera views denser areas of the scene. Context: Every object in the camera frustum generates draw calls even if completely hidden behind other geometry, wasting GPU cycles"}, {"id": "gk_865", "t": "performance", "text": "[PERFORMANCE] Each draw call is created per mesh per material \u2014 3 meshes with 2 materials = 6 draw calls; reducing from 1.6M batches to 20K by joining meshes in Blender (Ctrl+J) boosted FPS from 0.5 to ~80. Context: Draw calls funnel through the CPU before reaching the GPU, so excessive calls bottleneck the CPU and tank frame rate."}, {"id": "gk_866", "t": "performance", "text": "[PERFORMANCE] Reducing materials per object from 3 to 1 (using a single texture atlas to color different parts) improved FPS from ~80 to ~180 on a 5000-building scene. Context: Each additional material on a mesh adds another draw call, so consolidating to one material per object is a major optimization."}, {"id": "gk_867", "t": "performance", "text": "[PERFORMANCE] Static batching in Unity combines same-material meshes into a single mesh at build time \u2014 enabled by ticking the 'static' checkbox on non-moving objects, boosting FPS from ~180 to ~210. Context: Static batching only applies to objects that will never move; individual parts can be excluded from navigation or baked lighting via a dropdown."}, {"id": "gk_868", "t": "performance", "text": "[PERFORMANCE] GPU instancing renders multiple copies of the same mesh+material in a single draw call and is enabled via a checkbox on the material \u2014 it achieved the same ~210 FPS as static batching while allowing objects to move. Context: GPU instancing requires identical mesh and identical material across instances; it cannot be used simultaneously with static batching on the same objects."}, {"id": "gk_869", "t": "performance", "text": "[PERFORMANCE] Mesh combining only improves performance when the combined sub-meshes share the same material; joining meshes with different materials still produces one draw call per material. Context: When joining objects in Blender, the last selected object becomes the new origin \u2014 save as a separate file to preserve editability."}, {"id": "gk_870", "t": "performance", "text": "[PERFORMANCE] Unity's 'Stats' panel in play mode shows real-time batch count (visible as 'Batches' in top-right stats overlay), which directly corresponds to draw call volume. Context: Monitoring batch count is the primary way to verify draw call optimizations are working in Unity."}, {"id": "gk_871", "t": "performance", "text": "[PERFORMANCE] Occlusion culling in Unity only works on objects marked as static; you bake it via the Render dropdown and it culls objects not visible to the camera, yielding a small frame rate increase (roughly 70\u219273 FPS in a mobile-target scene).. Context: Unity scene optimization tutorial demonstrating occlusion culling bake workflow on terrain and tree objects."}, {"id": "gk_872", "t": "performance", "text": "[PERFORMANCE] Large single-mesh objects like a water plane cannot be occlusion-culled effectively; splitting them into smaller pieces is required for the occlusion system to cull individual segments.. Context: A full-size water plane remained always visible because occlusion culling needs separate smaller objects to cull individually."}, {"id": "gk_873", "t": "performance", "text": "[PERFORMANCE] Non-static objects (e.g., trees) are always loaded regardless of camera view; marking them as static enables occlusion culling and reduces rendered vertices from ~1.5M down to ~800K depending on camera angle.. Context: Vertex count swung between 800K and 1.5M based on camera direction after baking occlusion culling with static trees."}, {"id": "gk_874", "t": "performance", "text": "[PERFORMANCE] Reflection probes set to real-time with HDR on and 256 resolution are costly; switching to individual faces, lowering resolution to 32, and disabling HDR recovers a few FPS.. Context: Optimizing a real-time reflection probe from default 256/HDR to 32/no-HDR improved frame rate marginally."}, {"id": "gk_875", "t": "performance", "text": "[PERFORMANCE] Post-processing effects ambient occlusion and color grading are among the most expensive screen-space effects; disabling just those two boosted FPS from ~79 to nearly 100.. Context: Camera post-processing stack was the largest single performance drain in the test scene."}, {"id": "gk_876", "t": "performance", "text": "[PERFORMANCE] Completely disabling the post-processing stack yields the maximum frame rate gain, significantly beyond the ~100 FPS achieved by only turning off ambient occlusion and color grading.. Context: Final optimization step showed that all remaining post-processing effects still carried measurable GPU cost."}, {"id": "gk_877", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] Unity's built-in occlusion culling only disables the MeshRenderer component on static objects, leaving all other components (scripts, colliders, audio, lights, particles) still active and consuming CPU cycles.. Context: Custom frustum culling that disables the entire GameObject including all components provides greater performance savings than Unity's default approach."}, {"id": "gk_878", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] Custom frustum culling works by placing edge points (bounding markers) built from the mesh data as child objects of the target GameObject, then testing whether those edge points fall within the camera's frustum to determine visibility.. Context: The edge points are auto-generated from mesh data and can be manually adjusted in size and position for accuracy."}, {"id": "gk_879", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] The frustum culling script must be attached to the same GameObject that holds the MeshRenderer component, not a parent or child, for the edge/bounds calculation to work correctly.. Context: Edge markers are built by reading the mesh data from the MeshRenderer on that specific GameObject."}, {"id": "gk_880", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] A two-part architecture is used: a single FrustumCullingManager (with auto-catch or runtime camera reference) and per-object FrustumCullingObject components, enabling centralized camera frustum checks against distributed object bounds.. Context: The manager supports both scene-start cameras and runtime-spawned cameras via an autocatch toggle and a main cam property settable from code."}, {"id": "gk_881", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] Non-rendering components like point lights and interactable objects benefit significantly from full GameObject disabling via frustum culling, since Unity's default culling only targets mesh rendering and leaves lights, scripts, and physics active.. Context: Point lights that contribute minimal visible illumination can be entirely disabled when out of view to save GPU light calculations and shadow passes."}, {"id": "gk_882", "t": "frustum_culling", "text": "[FRUSTUM_CULLING] Objects are re-enabled before they fully enter the camera's field of view (using the edge bounding points), ensuring visually seamless transitions with no visible pop-in regardless of camera rotation speed.. Context: The edge markers extend slightly beyond the mesh bounds so the object activates just before it would become visible to the player."}, {"id": "gk_883", "t": "performance", "text": "[PERFORMANCE] Hierarchical LOD (HLOD) reduced draw calls from ~3000-4000 down to 161 by automatically combining child meshes into larger batched groups at distance. Context: Unity's free HLOD system subdivides scene by chunk size, combines meshes per quadrant, and replaces high-quality meshes with combined meshes as camera distance increases"}, {"id": "gk_884", "t": "performance", "text": "[PERFORMANCE] Even with static batching saving 11,000 batches, the scene still had 5,900 draw calls and 15,000 batch draw calls, showing static batching alone is insufficient for large modular scenes. Context: Medieval village demo with uncombined modular meshes demonstrated poor performance despite Unity's built-in static batching"}, {"id": "gk_885", "t": "performance", "text": "[PERFORMANCE] HLOD works by subdividing child objects by a configurable chunk size, combining all meshes within each quadrant, and progressively merging into larger quadrants at greater camera distances. Context: The system automatically groups and merges geometry spatially, reducing draw calls because more objects share a single draw call at distance"}, {"id": "gk_886", "t": "performance", "text": "[PERFORMANCE] Standard LOD groups may not improve performance enough for wide sweeping views with large numbers of distant objects; HLOD applies LOD logic to groups of objects rather than individual meshes. Context: Per-object LOD still results in many draw calls at distance, whereas HLOD batches entire spatial regions into single combined meshes"}, {"id": "gk_887", "t": "performance", "text": "[PERFORMANCE] HLOD provides vast performance benefits for large scenes with distant objects but only mediocre improvements in close-quarters environments like city centers where large object groups cannot be replaced with combined meshes. Context: Effectiveness scales with camera distance \u2014 nearby objects cannot be aggressively merged because they need individual detail"}, {"id": "gk_888", "t": "performance", "text": "[PERFORMANCE] HLOD uses a screen-space projected AABB threshold (e.g., 30% of screen) to determine when to switch between high-quality original meshes and lower-quality combined HLOD meshes. Context: Similar to standard LOD group distance-based switching but applied at the chunk/quadrant level for groups of objects"}, {"id": "gk_889", "t": "performance", "text": "[PERFORMANCE] The SRP Batcher reduces CPU time by batching objects that use the same Shader variant, regardless of different materials. Objects with different Shader variants cause separate batches.. Context: In URP, the SRP Batcher groups draw calls by Shader variant, not by material, so a lit cube and lit plane batch together but an unlit sphere creates a separate batch."}, {"id": "gk_890", "t": "performance", "text": "[PERFORMANCE] In URP, the SRP Batcher is enabled by default under Project Settings > Graphics > Render Pipeline Asset inspector, in the Rendering section. If the checkbox is hidden, set Advanced Properties to 'all visible' in Preferences > Graphics.. Context: Toggling the SRP Batcher on/off requires locating the checkbox on the URP render pipeline asset, which may be hidden behind advanced property visibility settings."}, {"id": "gk_891", "t": "performance", "text": "[PERFORMANCE] The Frame Debugger (Window > Analysis > Frame Debugger) shows batch causes, draw call counts per batch, and which meshes are included in each batch, enabling direct inspection of draw call batching behavior.. Context: The Frame Debugger's 'draw opaque object' section reveals why objects were grouped or separated into batches, with explicit 'batch cause' information."}, {"id": "gk_892", "t": "performance", "text": "[PERFORMANCE] GPU instancing and static batching are separate optimization techniques from the SRP Batcher; all three reduce draw calls but work differently. Dynamic batching is also available as a separate toggle on the render pipeline asset.. Context: Unity 6 URP provides multiple draw call reduction strategies that can be toggled independently on the render pipeline asset."}, {"id": "gk_893", "t": "performance", "text": "[PERFORMANCE] When objects use the same Shader variant (e.g., URP Lit), they batch into a single batch with combined draw calls. A single object with a different Shader (e.g., URP Unlit) forces a separate batch with its own draw call.. Context: In a test scene, a plane and cube using URP Lit produced one batch with 2 draw calls, while adding an Unlit sphere created a second batch with 1 draw call."}, {"id": "gk_894", "t": "performance", "text": "[PERFORMANCE] GPU Resident Draw uses the BatchRendererGroup API to automatically draw game objects with GPU instancing, reducing draw calls and freeing CPU processing time. Works on all platforms including mobile.. Context: Unity 6 feature that batches objects sharing the same mesh into single draw calls for significant performance gains in scenes with many similar objects."}, {"id": "gk_895", "t": "performance", "text": "[PERFORMANCE] Enabling GPU Resident Draw instance drawing reduced batches from 4,800 to 2,000 (reduction of ~1,000 batches in a specific view) and increased FPS by an average of ~20 FPS in Unity's Fantasy Kingdom demo.. Context: Real benchmark numbers from a large scene with many shared meshes demonstrating measurable draw call batching and instancing gains."}, {"id": "gk_896", "t": "performance", "text": "[PERFORMANCE] GPU Resident Draw requires Forward+ rendering path to work efficiently. Enable via Edit > Project Settings > Quality > Render Pipeline Asset > Rendering tab, then set rendering path to Forward+ on the associated renderer.. Context: Setup requirement \u2014 without Forward+ enabled, GPU Resident Draw will show a warning and not function properly."}, {"id": "gk_897", "t": "performance", "text": "[PERFORMANCE] GPU Resident Draw increases build times because Unity compiles all BatchRendererGroup shader variants into the build.. Context: Trade-off to be aware of \u2014 runtime draw call reduction comes at the cost of longer compile/build times due to additional shader variant compilation."}, {"id": "gk_898", "t": "performance", "text": "[PERFORMANCE] Disable legacy Static Batching (Edit > Project Settings > Player > Other Settings) when using GPU Resident Draw, as the old static batching system can conflict and reducing it can yield additional performance savings.. Context: Static Batching was Unity's original draw call optimization; disabling it avoids redundancy and potential conflicts with the newer GPU instancing pipeline."}, {"id": "gk_899", "t": "performance", "text": "[PERFORMANCE] GPU Occlusion Culling works hand-in-hand with GPU Resident Draw. Additionally, using fixed lightmap size and disabling mipmap limits can further optimize GPU memory when combined with GPU Resident Draw.. Context: Complementary optimizations \u2014 GPU occlusion culling reduces rendered objects while fixed lightmap sizes control GPU memory usage for light map textures."}, {"id": "gk_900", "t": "procedural", "text": "[PROCEDURAL] Simplex noise is used to generate the noise value for each tile in a chunk, producing a random generated world made out of different blocks.. Context: A 2D sandbox open-world game uses Simplex noise for infinite terrain generation with chunk-based world storage."}, {"id": "gk_901", "t": "procedural", "text": "[PROCEDURAL] Chunks are serialized to files storing the Simplex noise value per tile, enabling read/write of player changes for persistent world saves.. Context: Chunk data including noise values is written to and read from files to preserve player modifications across sessions."}, {"id": "gk_902", "t": "procedural", "text": "[PROCEDURAL] The terrain is chunk-based with each chunk containing tiles whose block type is determined by their Simplex noise value, supporting multiple block varieties.. Context: World generation maps noise values to different block types within a chunk grid, with plans to increase block variety and mechanics."}, {"id": "gk_903", "t": "procedural", "text": "[PROCEDURAL] Back-face culling optimization for voxel terrain: check each block's six neighbors, and remove any face shared between two adjacent solid blocks. Only surface-exposed faces are rendered, dramatically reducing face count.. Context: Applied to a Minecraft-style voxel terrain in Roblox Studio to optimize rendering performance."}, {"id": "gk_904", "t": "procedural", "text": "[PROCEDURAL] Biome generation was replicated using Henrik Nyberg's Minecraft terrain generation method, which uses noise-based heightmaps but has optimization limitations since it is not the actual Minecraft source code.. Context: The developer followed Henrik Nyberg's published terrain generation approach as a reference for procedural biome and terrain generation."}, {"id": "gk_905", "t": "procedural", "text": "[PROCEDURAL] Voxel blocks use per-face textures applied via decals/extras on each of the six faces, allowing different textures per side (e.g., grass top, dirt sides) and enabling individual face removal for culling.. Context: Custom blocks were built with separate face textures to support selective face rendering during back-face culling."}, {"id": "gk_906", "t": "procedural", "text": "[PROCEDURAL] Texture resolution mismatch causes blurriness: low-resolution texture pack images mapped onto higher-resolution block faces produce a blurry effect; textures must match the target block's UV scale.. Context: The developer noted that Minecraft-style 16x16 textures appeared blurry when applied to blocks with larger face dimensions in Roblox."}, {"id": "gk_907", "t": "procedural", "text": "[PROCEDURAL] Noise generators are used for top-down world generation where each location gets a noise value and tiles spawn based on the range that the noise gives for that location. Context: In Godot 4 with the Gia add-on, a noise generator connects to a tile map via a renderer to produce procedural worlds."}, {"id": "gk_908", "t": "procedural", "text": "[PROCEDURAL] Heightmap generator 2D is used for side-scrolling procedural generation like Terraria, while noise generators are used for top-down generation. Context: Different generator types suit different game perspectives \u2014 heightmap for vertical 2D worlds, noise for top-down."}, {"id": "gk_909", "t": "procedural", "text": "[PROCEDURAL] Procedural generation pipeline in Godot 4 requires three components: a generator (noise or walker), a renderer (TileMap Gia Renderer), and a TileMap node. Context: The generator produces data, the renderer connects it to the tile map, and the tile map displays the tiles."}, {"id": "gk_910", "t": "procedural", "text": "[PROCEDURAL] Walker generator produces rogue-like dungeon generation, while noise generator produces open-world random terrain generation. Context: Two main generator types in Gia add-on serve different procedural generation styles."}, {"id": "gk_911", "t": "threejs", "text": "[THREEJS] Three.js LOD (Level of Detail) class allows switching mesh detail levels based on camera distance. Create with `const lod = new THREE.LOD()`, add meshes via `lod.addLevel(mesh, distance)` where distance is the threshold in world units.. Context: Reduces vertex/triangle count for distant objects to improve rendering performance in scenes with many meshes."}, {"id": "gk_912", "t": "threejs", "text": "[THREEJS] LOD.addLevel(mesh, distance) takes two arguments: the mesh object and the minimum distance from camera at which that mesh should be displayed. Lower detail meshes should have higher distance values.. Context: Common mistake is reversing the order \u2014 high-detail meshes should have the smallest distance threshold (e.g., 0), low-detail meshes the largest (e.g., 20)."}, {"id": "gk_913", "t": "threejs", "text": "[THREEJS] LOD.getCurrentLevel() returns the index of the currently active detail level, which can be used in the animation loop to track or display which LOD tier is rendering.. Context: Useful for debugging or displaying LOD status labels using CSS2DRenderer and CSS2DObject overlays."}, {"id": "gk_914", "t": "threejs", "text": "[THREEJS] CSS2DRenderer and CSS2DObject can be used to attach HTML/CSS labels to 3D objects in a Three.js scene, enabling HUD-style overlays that track world-space positions.. Context: Used here to display the current LOD level as a label attached to the object."}, {"id": "gk_915", "t": "threejs", "text": "[THREEJS] Performance optimization strategy: create multiple copies of the same model with decreasing triangle/vertex counts, then use THREE.LOD to automatically swap between them based on camera proximity.. Context: Particularly valuable for scenes with many meshes where rendering all at full detail would be too expensive."}, {"id": "gk_916", "t": "threejs", "text": "[THREEJS] AmbientLight is instantiated with color and intensity parameters and added to the scene; it equally brightens everything with constant color, useful for simulating bounce light in shadowed areas.. Context: AmbientLight provides a poor man's global illumination by adding uniform brightness across the entire scene."}, {"id": "gk_917", "t": "threejs", "text": "[THREEJS] HemisphereLight takes two colors (sky and ground) and interpolates between them based on surface normal direction \u2014 normals facing up use sky color, normals facing down use ground color.. Context: HemisphereLight is commonly used instead of AmbientLight for outdoor scenes to add directional detail in shadowed areas."}, {"id": "gk_918", "t": "threejs", "text": "[THREEJS] RectAreaLight is instantiated with color, intensity, width, and height parameters (e.g., width=2.0, height=20.0) to create a soft rectangular light emitting diffuse semi-directional light.. Context: RectAreaLight is based on a SIGGRAPH paper and is useful for indoor scenes like simulating TV screen glow or strip lighting."}, {"id": "gk_919", "t": "threejs", "text": "[THREEJS] DirectionalLight simulates sunlight with parallel rays from an infinitely far source, uses N\u00b7L (normal dot light) for diffuse calculation, and is the first light type that supports shadow maps.. Context: Shadows are straightforward for directional lights because from the sun's perspective it's just the area behind an object."}, {"id": "gk_920", "t": "threejs", "text": "[THREEJS] AmbientLight and HemisphereLight do not support shadows in Three.js; shadow support begins with directional lights which have clear light direction for shadow map calculation.. Context: Softer, non-directional light types lack straightforward shadow contribution calculation."}, {"id": "gk_921", "t": "threejs", "text": "[THREEJS] Three.js is a rendering API that renders to an HTML canvas element within the DOM, not a game engine like Unity or Unreal. Context: Clarifies Three.js scope as a rendering layer, not a full engine with built-in physics, scene management, or editor"}, {"id": "gk_922", "t": "threejs", "text": "[THREEJS] React Three Fiber provides a useful abstraction layer over the raw Three.js API and can accelerate initial learning, though it is not required for production projects. Context: R3F wraps Three.js in React declarative syntax but the presenter stopped using it for his own projects"}, {"id": "gk_923", "t": "threejs", "text": "[THREEJS] Custom GLSL shaders are the single biggest differentiator in Three.js scene quality \u2014 mastering vertex and fragment shaders separates basic scenes from professional-grade work. Context: Presenter emphasizes shader skills as the highest-leverage investment after learning Three.js basics"}, {"id": "gk_924", "t": "threejs", "text": "[THREEJS] Blender's Shader Node editor and Geometry Nodes tab teach 3D material and procedural geometry concepts that directly transfer to Three.js scene composition and custom shaders. Context: Recommended as pre-requisite knowledge before touching Three.js code"}, {"id": "gk_925", "t": "threejs", "text": "[THREEJS] Core Blender skills that transfer to Three.js include lighting setup, geometry creation, and PBR material authoring. Context: Understanding these in a visual tool first reduces the learning curve when implementing them programmatically in Three.js"}, {"id": "gk_926", "t": "threejs", "text": "[THREEJS] InstancedMesh class takes geometry, material, and instance count as constructor arguments, enabling rendering of thousands of objects in a single draw call instead of one render call per object.. Context: Instanced rendering reduces CPU-GPU communication overhead by passing shared geometry and material data once, letting the GPU render all instances together."}, {"id": "gk_927", "t": "threejs", "text": "[THREEJS] All instances in an InstancedMesh must share the same geometry and material, but each instance can have unique geometric transformations (position, rotation, scale) applied via transformation matrices.. Context: Per-instance transforms are set using Object3D matrices rather than direct position/rotation properties."}, {"id": "gk_928", "t": "threejs", "text": "[THREEJS] Without instancing, rendering N objects requires N separate render calls; with InstancedMesh, even 100,000+ objects can be rendered in a single render call.. Context: The performance bottleneck is CPU-GPU communication per draw call, not GPU rendering power itself."}, {"id": "gk_929", "t": "threejs", "text": "[THREEJS] To set per-instance transforms, create a temporary Object3D, set its position/rotation/scale, call updateMatrix(), then use instancedMesh.setMatrixAt(index, object3D.matrix) for each instance.. Context: A for loop iterates over instance count, using Object3D as a helper to build transformation matrices for each instance."}, {"id": "gk_930", "t": "threejs", "text": "[THREEJS] Instancing is ideal for particle systems and repeated environmental objects like grass models covering large terrains, where classic for-loop mesh creation would cause thousands of costly render calls.. Context: These are common game dev use cases where instanced rendering provides the biggest performance gains."}, {"id": "gk_931", "t": "threejs", "text": "[THREEJS] Each mesh with a unique material creates one draw call. Two boxes with a physical material = 2 draw calls.. Context: Draw calls represent the number of objects the GPU renders every frame and are the first metric to optimize."}, {"id": "gk_932", "t": "threejs", "text": "[THREEJS] Enabling shadows adds one extra draw call per shadow-casting mesh. Two shadow-casting boxes add 2 extra draw calls (total 4).. Context: Shadows increase draw call count proportionally to the number of shadow-casting objects in the scene."}, {"id": "gk_933", "t": "threejs", "text": "[THREEJS] A transmissive material doubles the total draw call count of the entire scene (e.g., 4 draw calls become 8).. Context: Transmissive materials are expensive because the scene behind the object must be rendered separately."}, {"id": "gk_934", "t": "threejs", "text": "[THREEJS] Enabling post-processing (e.g., Bloom) causes the entire scene to be rendered twice, doubling draw calls, plus Bloom itself has a base cost of ~12 draw calls.. Context: A simple scene with 2 boxes, shadows, and transmissive material went from 8 to ~32 draw calls after adding Bloom."}, {"id": "gk_935", "t": "threejs", "text": "[THREEJS] Performance should be tracked using stat.js (shows FPS, allocated memory in MB, and ms per frame) or r3f-perf for React Three Fiber (shows polygons, textures, etc.).. Context: Combining these with OS-level performance monitors gives the most comprehensive view of WebGL content performance."}, {"id": "gk_936", "t": "threejs", "text": "[THREEJS] Optimization is about trade-offs: polygon count, materials, textures, shadows, and animations are sliders \u2014 increasing one may require reducing others to maintain performance.. Context: Before starting a project, identify priorities to make informed decisions on resource allocation across these factors."}, {"id": "gk_937", "t": "webgl", "text": "[WEBGL] WebGL allows hardware-accelerated 2D and 3D graphics rendering directly in an HTML canvas element using the client's GPU, without external plugins. Context: WebGL is the foundation that Three.js builds upon for all browser-based 3D rendering."}, {"id": "gk_938", "t": "webgl", "text": "[WEBGL] The 3D rendering pipeline follows: vertices (x,y,z) -> primitives (triangles) -> lighting/shadows -> rasterization (3D vector to 2D pixel projection). Context: Understanding this pipeline is essential for optimizing Three.js scenes with bloom, shadows, and instanced meshes."}, {"id": "gk_939", "t": "webgl", "text": "[WEBGL] Shaders are custom GPU functions that control pixel rendering; vertex shaders process vertex data and fragment shaders calculate per-pixel color, written in GLSL ES (OpenGL ES Shading Language). Context: Custom shaders are used in Three.js for bloom post-processing passes in EffectComposer and particle system rendering."}, {"id": "gk_940", "t": "webgl", "text": "[WEBGL] WebGL is based on OpenGL, a graphics library dating back to 1992, and offloads matrix multiplication and linear algebra to the GPU for smooth 60fps rendering. Context: GPU-based computation is why instanced mesh rendering and particle systems can handle thousands of objects efficiently in Three.js."}, {"id": "gk_941", "t": "threejs", "text": "[THREEJS] Three.js abstracts raw WebGL shader writing, allowing developers to build 3D experiences without manually coding vertex and fragment shaders or managing the WebGL context directly. Context: Libraries like Three.js provide higher-level APIs for shadow maps, EffectComposer bloom, and instanced meshes on top of WebGL."}, {"id": "gk_942", "t": "webgl", "text": "[WEBGL] To initialize WebGL you grab an HTML canvas element from the DOM and call getContext('webgl') to access the rendering API; main logic is JavaScript while shaders use GLSL ES. Context: Three.js handles this canvas/context setup automatically via its WebGLRenderer constructor."}, {"id": "vision_elden_ring_terrain_scale_biomes", "t": "elden ring", "text": "[VISION/ELDEN_RING - terrain_scale_biomes] building height appears ~15 player heights tall. road is approximately 2 lanes wide. lighting color temperature: warm, hex estimate #FFE4C4. fog density: light, starts at ~25 units. art style: realistic. key design patterns observed: Ruined architecture scattered throughout a vast, open landscape enhances the sense of a fallen civilization, with the Erdtree acting as a dominant landmark and providing directional guidance, with distant landmarks visible. Measurements: buildingHeightPlayers: 15, roadWidthLanes: 2, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_elden_ring_lighting_atmosphere_mood", "t": "elden ring", "text": "[VISION/ELDEN_RING - lighting_atmosphere_mood] building height appears several player heights tall, difficult to assess due to perspective.. roads are not visible, so assessing its width is imposiblle.. lighting color temperature: neutral, sunrise/sunset hue.. fog density: light, starts mid distance to heavy distant fog.. art style: realistic. key design patterns observed: majestic views, grand sweeping landscapes, sense of exploration and peril, dramatic lighting to heighten emotion, architectural scale conveying importance. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_elden_ring_architecture_scale_details", "t": "elden ring", "text": "[VISION/ELDEN_RING - architecture_scale_details] building height appears ~15 player heights tall. road is approximately 1 lanes wide. lighting color temperature: neutral, hex estimate. fog density: light, starts at ~30 units. art style: realistic. key design patterns observed: imposing castle architecture, suggests a once-grand and possibly decaying civilization; use of bonfire as a central light source and potential gathering point; the placement of impaled bodies on stakes adds to the bleak atmosphere; level design might incorporate verticality and strategic points within the castle. Measurements: buildingHeightPlayers: 15, roadWidthLanes: 1, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_dark_souls3_terrain_scale_biomes", "t": "dark souls3", "text": "[VISION/DARK_SOULS3 - terrain_scale_biomes] building height appears ~5-6 player heights tall. road is approximately 2 lanes wide. lighting color temperature: warm, hex estimate #F0E68C. fog density: light, starts at ~100 units. art style: realistic. key design patterns observed: verticality in level design, limited color palette, sense of overwhelming scale and imposing architecture Measurements: buildingHeightPlayers: 6, roadWidthLanes: 2, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_dark_souls3_lighting_atmosphere_mood", "t": "dark souls3", "text": "[VISION/DARK_SOULS3 - lighting_atmosphere_mood] building height appears ~3 player heights tall. road is approximately 2 lanes wide. lighting color temperature: hex estimate #F8E39F/#B8B1A3 with warm emphasis around the player character. fog density: light, starts at ~50 units. art style: realistic. key design patterns observed Measurements: buildingHeightPlayers: 3, roadWidthLanes: 2, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_dark_souls3_environment_density_style", "t": "dark souls3", "text": "[VISION/DARK_SOULS3 - environment_density_style] building height appears >10 player heights tall, with varied heights indicating a dense urban environment.. road is approximately 1 lane wide or less.. lighting color temperature: neutral. fog density: none. art style: realistic. key design patterns observed: Dense architectural environment with a focus on verticality to obstruct visibility, detailed textures providing a high fidelity visual experience, contrast between light and shadow, debris is scattered on ground to indicate destruction. Measurements: buildingHeightPlayers: 10, roadWidthLanes: 1, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_gta5_terrain_scale_biomes", "t": "gta5", "text": "[VISION/GTA5 - terrain_scale_biomes] building height appears ~5+ player heights tall. road is approximately 5+ lanes wide. lighting color temperature: neutral, hex estimate. fog density: none, starts at ~X units. art style: realistic. key design patterns observed: airport runway to accommodate large planes, flying cars and planes demonstrate large map scale, lighting is realistic to create realism and environment. Measurements: buildingHeightPlayers: 5, roadWidthLanes: 5, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_gta5_lighting_atmosphere_mood", "t": "gta5", "text": "[VISION/GTA5 - lighting_atmosphere_mood] lighting color temperature: mixture of warm and cool tones, with warm bursts of muzzle flares against a mostly desaturated cool background light. fog density: none, but there is a lot of dust and smoke in the air giving a sense of depth and reduced visibility. art style: realistic with exagerrated lighting effects for dramatic effect. key design patterns observed: high contrast between light and shadow to create a sense of tension and danger; prominent lighting on the weapons further enhances the action Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: mixed, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_gta5_architecture_scale_details", "t": "gta5", "text": "[VISION/GTA5 - architecture_scale_details] The image appears to be set in an underground bunker or facility.. Minimal architectural detail is visible, the focus is on the characters.. There is a large circular table-like structure with a depiction of water on it, possibly a holographic display.. Lighting appears to be artificial and somewhat dim, focusing on illuminating the table.. Art style: realistic. key design patterns observed: The scene uses darkness and silhouettes to create a sense of mystery and tension. The brightly lit table acts as the focal point, drawing the viewer's attention. The positioning of the characters suggests they are involved in a briefing or strategy session. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: cool, fogDensity: none, artStyle: realistic, drawDistance: short."}, {"id": "vision_gta5_environment_density_style", "t": "gta5", "text": "[VISION/GTA5 - environment_density_style] building height appears ~X player heights tall, (Not Visible so can't tell). road is approximately X lanes wide (Not Visible so can't tell). lighting color temperature: neutral. fog density: none. art style: realistic. key design patterns observed: Interior environment appears to be a sterile office or control room; limited environmental details suggest a focus on gameplay & objectives rather than detailed worldbuilding in this specific indoor location; suggests a high-stakes heist or infiltration scenario; use of modern office equipment and minimal decor. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_resident_evil2_terrain_scale_biomes", "t": "resident evil2", "text": "[VISION/RESIDENT_EVIL2 - terrain_scale_biomes] building height appears ~2-3 player heights tall. road is approximately 2 lanes wide. lighting color temperature: cool, hex estimate #404080. fog density: light, starts at ~25 units. art style: realistic. key design patterns observed: constrained urban environment, focus on interior spaces, high detail textures emphasizing claustrophobia, sense of unease Measurements: buildingHeightPlayers: 3, roadWidthLanes: 2, lightingTemp: cool, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_resident_evil2_lighting_atmosphere_mood", "t": "resident evil2", "text": "[VISION/RESIDENT_EVIL2 - lighting_atmosphere_mood] Building height appears ~4 player heights tall.. Lighting color temperature: warm (yellowish) from lamps, cool (blueish) from natural light through windows. Lamp hex estimate: #FFDEAD. Fog density: none. Art style: realistic. Key design patterns observed: Use of high contrast between light and shadow to create a sense of tension and foreboding. Lighting focuses on key areas of interest, drawing the player's eye. The warm lighting from indoor sources contrasts with the cool, ominous light outside, suggesting danger. Wet surfaces enhance the specular reflections and add to the overall atmospheric tension. The statue is brightly lit, suggesting it is important or acts as an important landmark.. The room is dimly lit to create a dark and suspenseful mood, typical for a horror game.. The wet floor enhances the lighting of the room.. Draw distance is medium and covered by the limited lighting of the scene. Measurements: buildingHeightPlayers: 4, roadWidthLanes: 0, lightingTemp: mixed warm and cool, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_resident_evil2_architecture_scale_details", "t": "resident evil2", "text": "[VISION/RESIDENT_EVIL2 - architecture_scale_details] building height appears ~1 player heights tall. road is approximately 0 lanes wide. lighting color temperature: cool, hex estimate #aed6ff. fog density: light, starts at ~5 units. art style: realistic. key design patterns observed: claustrophobic corridor design, strong chiaroscuro lighting for suspense, environmental storytelling using caution tape and water puddles. Measurements: buildingHeightPlayers: 1, roadWidthLanes: 0, lightingTemp: cool, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_cyberpunk2077_terrain_scale_biomes", "t": "cyberpunk2077", "text": "[VISION/CYBERPUNK2077 - terrain_scale_biomes] building height appears ~10-20 player heights tall. road is approximately 4 lanes wide. lighting color temperature: warm, hex estimate #ffcc80. fog density: light, starts at ~1000 units. art style: realistic. key design patterns observed Measurements: buildingHeightPlayers: 15, roadWidthLanes: 4, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_cyberpunk2077_architecture_scale_details", "t": "cyberpunk2077", "text": "[VISION/CYBERPUNK2077 - architecture_scale_details] building height appears ~X player heights tall. road is approximately X lanes wide. lighting color temperature: warm/cool, hex estimate. fog density: none/light/heavy, starts at ~X units. art style: realistic/stylized/cartoon/lowpoly. key design patterns observed: character selection is on a bright, red tinted UI Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_cyberpunk2077_environment_density_style", "t": "cyberpunk2077", "text": "[VISION/CYBERPUNK2077 - environment_density_style] building height appears >5 player heights tall. road is approximately 3 lanes wide. lighting color temperature: predominantly cool in the police car lights, yellow car lights. fog density: light, emanating from tire smoke on ground level. art style: realistic. key design patterns observed Measurements: buildingHeightPlayers: 5, roadWidthLanes: 3, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_red_dead2_terrain_scale_biomes", "t": "red dead2", "text": "[VISION/RED_DEAD2 - terrain_scale_biomes] building height appears ~1 player heights tall. road is approximately 1 lane wide. lighting color temperature: warm, hex estimate. fog density: heavy, starts at ~5 units. art style: realistic. key design patterns observed Measurements: buildingHeightPlayers: 1, roadWidthLanes: 1, lightingTemp: warm, fogDensity: heavy, artStyle: realistic, drawDistance: medium."}, {"id": "vision_red_dead2_lighting_atmosphere_mood", "t": "red dead2", "text": "[VISION/RED_DEAD2 - lighting_atmosphere_mood] building height appears ~2 player heights tall.. road not visible, hard to estimate width but the wooden platform seems narrow which is more like path that road.. lighting color temperature: neutral, with a mix of shadows and highlights suggests natural noon light.. fog density: none, implying a clear day.. art style: realistic, aiming for a gritty and immersive feel.. key design patterns observed. the atmosphere has some action, the dust in the air is a particle effect that goes by fairly quickly, gives depth to the image Measurements: buildingHeightPlayers: 2, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_red_dead2_architecture_scale_details", "t": "red dead2", "text": "[VISION/RED_DEAD2 - architecture_scale_details] There are no buildings in the immediate vicinity, so building height cannot be calculated relative to player height.. There are no roads visible, so road width cannot be measured.. The lighting color temperature appears relatively neutral, leaning towards cool due to the snowy environment.. There is no fog visible.. The art style is realistic.. Key design patterns observed: attention to detail in character clothing, snow accumulation is dynamically modeled on the characters and environment, distant mountains are rendered using atmospheric perspective and high detail textures. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_red_dead2_environment_density_style", "t": "red dead2", "text": "[VISION/RED_DEAD2 - environment_density_style] building height appears ~X player heights tall. road is approximately X lanes wide. lighting color temperature: neutral. fog density: light, starts at considerable distance. art style: realistic. key design patterns observed: volumetric fog usage to create depth and atmosphere, realistic rendering of foliage with varied density, use of shallow depth of field to focus on the character, use of neutral lighting to create a realistic and somber mood Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_battlefield1_architecture_scale_details", "t": "battlefield1", "text": "[VISION/BATTLEFIELD1 - architecture_scale_details] There are no buildings.. There are no roads.. lighting color temperature: warm, hex estimate #F0E68C. fog density: none. art style: realistic. key design patterns observed: motion blur used extensively. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: warm, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_battlefield1_environment_density_style", "t": "battlefield1", "text": "[VISION/BATTLEFIELD1 - environment_density_style] building height appears 1-2 player heights tall. road is approximately 1-2 lanes wide. lighting color temperature: neutral/slightly warm, hex estimate #F2E3D5. fog density: light, appears with distance. art style: realistic. key design patterns observed: sparse building distribution across the landscape, varied terrain providing natural cover, significant detail in the explosions and terrain texture indicating high graphical fidelity. Measurements: buildingHeightPlayers: 2, roadWidthLanes: 2, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_skyrim_terrain_scale_biomes", "t": "skyrim", "text": "[VISION/SKYRIM - terrain_scale_biomes] building height appears ~4-6 player heights tall.. road is approximately 1 lane wide.. lighting color temperature: cool, hex estimate #d5e8ef. fog density: light, starts at ~500 units.. art style: realistic. key design patterns observed: large scale stone architecture integrated into mountainous terrain, snowy environment with visible rock patches and sparse vegetation, focus on verticality with tiered structures and staircases, distinct transition from snowy lower ground to rocky mountainous regions. Measurements: buildingHeightPlayers: 5, roadWidthLanes: 1, lightingTemp: cool, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_skyrim_lighting_atmosphere_mood", "t": "skyrim", "text": "[VISION/SKYRIM - lighting_atmosphere_mood] lighting color temperature: warm, hex estimate (FAF0E6). fog density: light, starts at ~500 units. art style: realistic. key design patterns observed: god rays, volumetric fog, warm color palette, high contrast, depth of field blur Measurements: buildingHeightPlayers: 5, roadWidthLanes: 1, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_skyrim_environment_density_style", "t": "skyrim", "text": "[VISION/SKYRIM - environment_density_style] environment density: trees are moderately dense. lighting color temperature: warm due to the autumn leaves. fog density: light, enhances the depth of field. art style: realistic. key design patterns observed: use of blurring to create a sense of speed/action. draw distance is limited by the use of fog/blurring Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_sekiro_terrain_scale_biomes", "t": "sekiro", "text": "[VISION/SEKIRO - terrain_scale_biomes] building height appears ~50 player heights tall. road is approximately 1 lane wide. lighting color temperature: warm, hex estimate #F5DABB. fog density: light, starts at ~50-100 units. art style: realistic. key design patterns observed Measurements: buildingHeightPlayers: 50, roadWidthLanes: 1, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_hollow_knight_terrain_scale_biomes", "t": "hollow knight", "text": "[VISION/HOLLOW_KNIGHT - terrain_scale_biomes] building height appears ~3 player heights tall. road is approximately 1 lanes wide. lighting color temperature: warm. fog density: light, starts at ~3 units. art style: stylized. key design patterns observed. Platforms are small, and separated vertically, suggesting a lot of jumping and vertical movement; high contrast between characters and background, increasing readability Measurements: buildingHeightPlayers: 3, roadWidthLanes: 1, lightingTemp: warm, fogDensity: light, artStyle: stylized, drawDistance: medium."}, {"id": "vision_death_stranding_terrain_scale_biomes", "t": "death stranding", "text": "[VISION/DEATH_STRANDING - terrain_scale_biomes] Building height appears ~20 player heights tall. Road is approximately 4 lanes wide. lighting color temperature: neutral, hex estimate. fog density: light, starts at ~1000 units. art style: realistic. key design patterns observed: layered landscape with a focus on long distance travel, the terrain is mostly open plains with some hills Measurements: buildingHeightPlayers: 20, roadWidthLanes: 4, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_death_stranding_lighting_atmosphere_mood", "t": "death stranding", "text": "[VISION/DEATH_STRANDING - lighting_atmosphere_mood] The scene is indoors and appears to be set in a sterile environment.. Lighting seems to be coming from overhead, creating a bright and clean feel.. The atmosphere is relatively calm and sterile, contributing to a clinical mood.. The lighting color temperature is neutral, leaning slightly towards cool due to the white/grey color scheme.. Art style: realistic with high fidelity character models and environments.. Key design patterns observed include use of white and grey tones to create a sense of cleanliness and the bright ambient lighting, used to highlight character detail. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_death_stranding_architecture_scale_details", "t": "death stranding", "text": "[VISION/DEATH_STRANDING - architecture_scale_details] building height appears ~X player heights tall. Unable to ascertain specific building height value.. road is approximately X lanes wide. Road appears to be 2 lanes wide. lighting color temperature: neutral, hex estimate. fog density: none/light/heavy, starts at ~X units. Fog density: light in the background. art style: realistic/stylized/cartoon/lowpoly. Art style: realistic. key design patterns observed: vast open world with a focus on traversal, ruined infrastructure indicating a post-apocalyptic setting. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 2, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_death_stranding_environment_density_style", "t": "death stranding", "text": "[VISION/DEATH_STRANDING - environment_density_style] building height appears ~X player heights tall. road is approximately X lanes wide. lighting color temperature: warm/cool, hex estimate. fog density: none/light/heavy, starts at ~X units. art style: realistic/stylized/cartoon/lowpoly. key design patterns observed Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_elden_ring_environment_density_style", "t": "elden ring", "text": "[VISION/ELDEN_RING - environment_density_style] The environment features a dense forest setting with trees of varying sizes and autumn foliage.. The composition is balanced with characters (rider and mount) occupying the foreground and the creature being placed slightly to the right.. The overall density feels medium, with trees filling a majority of the space, yet there are still spaces or breaks between foliage to see objects behind.. lighting color temperature: warm, hex estimate. fog density: light, starts at ~50 units. art style: realistic. key design patterns observed: high texture detail, dynamic lighting & shadows, atmospheric fog/mist Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: #e3d5ba, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_dark_souls3_architecture_scale_details", "t": "dark souls3", "text": "[VISION/DARK_SOULS3 - architecture_scale_details] building height appears ~10+ player heights tall. road is approximately 0 lanes wide. lighting color temperature: neutral. fog density: none. art style: realistic. key design patterns observed: imposing architecture to emphasize the player's small stature, heavy use of gothic architectural elements (arches, vaults) to create a sense of grandeur and age Measurements: buildingHeightPlayers: 10, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_resident_evil2_environment_density_style", "t": "resident evil2", "text": "[VISION/RESIDENT_EVIL2 - environment_density_style] building height appears inaccessible in scene. road is approximately inaccessible in scene. lighting color temperature: cool, hex estimate #000033. fog density: none. art style: realistic. key design patterns observed: claustrophobic spaces, emphasis on darkness and limited visibility to create tension, graphic gore and disturbing visuals used to establish horror tone. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: cool, fogDensity: none, artStyle: realistic, drawDistance: medium."}, {"id": "vision_battlefield1_terrain_scale_biomes", "t": "battlefield1", "text": "[VISION/BATTLEFIELD1 - terrain_scale_biomes] tank height appears around 2 player heights tall. lighting color temperature: warm, hex estimate #F0E68C. fog density: light, starts at close range. art style: realistic. key design patterns observed: war-torn environment, gritty textures, realistic scale of military units and environments, focus on dust and particulate effects. Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_battlefield1_lighting_atmosphere_mood", "t": "battlefield1", "text": "[VISION/BATTLEFIELD1 - lighting_atmosphere_mood] The lighting is primarily warm due to the fire on the right side of the images and it is raining.. The fog is light and makes for medium draw distance. The weather is very dark, rainy and tense. The overall mood is intense and chaotic, reflecting the brutality of warfare.. The art style appears to be realistic. Key design patterns observed include the use of intense warm and cool lighting to create an immersive environment, as well as the use of rain and smoke for the weather effects to simulate a realistic war zone. The image has light fog Measurements: buildingHeightPlayers: 0, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_sekiro_lighting_atmosphere_mood", "t": "sekiro", "text": "[VISION/SEKIRO - lighting_atmosphere_mood] building height appears roughly 3 player heights tall.. The lighting is relatively neutral, with slight warmth from the sun and slight cool tint from the fog. . Fog density: very light, but it is a visible part of the scene and it adds atmosphere. Art style: Realistic.. The color palette is muted with a natural feel. key design patterns observed: contrast between detailed character assets and slightly less detailed environment. Measurements: buildingHeightPlayers: 3, roadWidthLanes: 0, lightingTemp: neutral, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_sekiro_environment_density_style", "t": "sekiro", "text": "[VISION/SEKIRO - environment_density_style] building height appears ~6-8 player heights tall (pagodas).. road is approximately 0 lanes wide (lacking roads).. lighting color temperature: warm, hex estimate #F5DEB3.. fog density: light, starts at ~50 units.. art style: realistic. key design patterns observed: vertical level design, with multiple layers of structures and pathways. Heavy use of autumn foliage to create visual density and guide player. A focus on creating a sense of scale and depth in the environment. Measurements: buildingHeightPlayers: 7, roadWidthLanes: 0, lightingTemp: warm, fogDensity: light, artStyle: realistic, drawDistance: medium."}, {"id": "vision_hollow_knight_architecture_scale_details", "t": "hollow knight", "text": "[VISION/HOLLOW_KNIGHT - architecture_scale_details] building height appears ~8 player heights tall. road is approximately 2 lanes wide. lighting color temperature: warm, hex estimate #ee3344. fog density: light, starts at ~150 units. art style: stylized. key design patterns observed: repetitive background elements, simplified forms, perspective compression; pink / red color bias Measurements: buildingHeightPlayers: 8, roadWidthLanes: 2, lightingTemp: warm, fogDensity: light, artStyle: stylized, drawDistance: medium."}, {"id": "vision_hollow_knight_environment_density_style", "t": "hollow knight", "text": "[VISION/HOLLOW_KNIGHT - environment_density_style] building height appears ~3 player heights tall. road is approximately 1 lanes wide. lighting color temperature: cool, #CCD1E7. fog density: none. art style: stylized. key design patterns observed: layered background with varying density in different layers to create depth, bright foreground elements contrasting with dark background to focus attention, crystal structures used to add detail and visual elements, platforms built into the level Measurements: buildingHeightPlayers: 3, roadWidthLanes: 1, lightingTemp: cool, fogDensity: none, artStyle: stylized, drawDistance: medium."}, {"id": "gen_tactical_shooter_0", "t": "tactical_shooter", "text": "[TACTICAL_SHOOTER] Cover system implementation: raycasts to detect cover points, crouch/lean animations, blind fire mechanics, exposure calculation"}, {"id": "gen_tactical_shooter_1", "t": "tactical_shooter", "text": "[TACTICAL_SHOOTER] Weapon mechanics: recoil patterns (vertical + horizontal), bullet spread cone, aim-down-sights FOV change, weapon sway math"}, {"id": "gen_tactical_shooter_2", "t": "tactical_shooter", "text": "[TACTICAL_SHOOTER] Tactical AI: squad formations, suppression behavior, flanking pathfinding, threat assessment scoring"}, {"id": "gen_tactical_shooter_3", "t": "tactical_shooter", "text": "[TACTICAL_SHOOTER] Damage model: hitbox multipliers (head 4x, torso 1x, limbs 0.6x), armor penetration values, damage falloff over distance"}, {"id": "gen_tactical_shooter_4", "t": "tactical_shooter", "text": "[TACTICAL_SHOOTER] Movement: tactical sprint (1.5x speed, weapon lowered), lean angles (15-20 degrees), prone transition (0.8s), vault detection"}, {"id": "gen_weather_systems_0", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Rain system: particle emitter attached to camera, splash particles on ground collision, wet surface shader (increased roughness, specular), puddle accumulation over time"}, {"id": "gen_weather_systems_1", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Dynamic sky: sun position from time-of-day angle, cloud layer scrolling UV, color gradient lookup (dawn orange, noon blue, dusk red), star fade based on sun altitude"}, {"id": "gen_weather_systems_2", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Fog system: FogExp2 density ramp (clear 0.0005, light fog 0.002, heavy 0.008), height-based fog (ground fog denser below y=10), volumetric fog ray marching"}, {"id": "gen_weather_systems_3", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Snow: ground accumulation shader (blend white texture based on surface normal.y > 0.7), snowfall particles, footprint deformation via displacement map"}, {"id": "gen_weather_systems_4", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Wind: global wind vector affects particles, tree sway (vertex shader sine wave), grass bend, flag cloth simulation force"}, {"id": "gen_weather_systems_5", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Lightning: random flash (emissive sky pulse), thunder delay = distance/343, bolt geometry (segmented line with random offsets)"}, {"id": "gen_weather_systems_6", "t": "weather_systems", "text": "[WEATHER_SYSTEMS] Weather transitions: lerp between states over 30-60 seconds, gradual particle density change, smooth fog density interpolation"}, {"id": "gen_extraction_games_0", "t": "extraction_games", "text": "[EXTRACTION_GAMES] Loot spawn system: loot tables with rarity weights (common 60%, uncommon 25%, rare 10%, legendary 5%), spawn points shuffled per raid, container types with different loot pools"}, {"id": "gen_extraction_games_1", "t": "extraction_games", "text": "[EXTRACTION_GAMES] Extraction points: timed extraction (10-15 seconds), extraction zone trigger volume, visual indicator (flare/smoke), conditional extractions (need key item)"}, {"id": "gen_extraction_games_2", "t": "extraction_games", "text": "[EXTRACTION_GAMES] Raid timer: match duration 20-45 minutes, warning at 5 min remaining, forced extraction or death at 0, time pressure drives player decisions"}, {"id": "gen_extraction_games_3", "t": "extraction_games", "text": "[EXTRACTION_GAMES] Persistent inventory: stash system between raids, insurance mechanic, flea market/trading, hideout upgrades that unlock crafting"}, {"id": "gen_extraction_games_4", "t": "extraction_games", "text": "[EXTRACTION_GAMES] AI Scavs: patrol routes with random variation, aggro radius 30-50m, hearing detection from gunshots 100m+, difficulty scaling by map zone"}, {"id": "gen_racing_physics_0", "t": "racing_physics", "text": "[RACING_PHYSICS] Tire grip model: lateral force = slip_angle * grip_coefficient, longitudinal force for acceleration/braking, combined slip circle limits total force"}, {"id": "gen_racing_physics_1", "t": "racing_physics", "text": "[RACING_PHYSICS] Suspension: spring force = stiffness * compression, damping force = damping_coeff * velocity, anti-roll bar connects left/right springs"}, {"id": "gen_racing_physics_2", "t": "racing_physics", "text": "[RACING_PHYSICS] Steering: Ackermann geometry (inner wheel turns more), speed-sensitive steering reduction, counter-steer assist for drifting"}, {"id": "gen_racing_physics_3", "t": "racing_physics", "text": "[RACING_PHYSICS] Arcade vs sim: arcade uses simplified grip (binary slip), speed boost on drift, forgiving collision, auto-straighten. Sim uses full tire model"}, {"id": "gen_racing_physics_4", "t": "racing_physics", "text": "[RACING_PHYSICS] Track design: racing line optimization, corner apex points, elevation changes for excitement, chicanes to break up straights, pit lane entry/exit"}, {"id": "gen_racing_physics_5", "t": "racing_physics", "text": "[RACING_PHYSICS] Drift mechanics: rear wheel slip angle > threshold triggers drift state, score based on angle * speed * duration, boost reward for clean drifts"}, {"id": "gen_racing_physics_6", "t": "racing_physics", "text": "[RACING_PHYSICS] Vehicle stats: top speed 150-300 km/h, 0-60 in 2-8 seconds, weight 800-2000kg, downforce increases grip at speed, drag coefficient 0.3-0.5"}, {"id": "gen_building_placement_0", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Grid system: world divided into cells (1x1 to 4x4 meters), snapping position = round(worldPos / gridSize) * gridSize, rotation snapping to 90 or 45 degrees"}, {"id": "gen_building_placement_1", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Placement validation: overlap check via box collision test, terrain conformity (raycast corners to ground), resource cost check, build radius from base"}, {"id": "gen_building_placement_2", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Preview ghost: semi-transparent material (alpha 0.5), green = valid placement, red = blocked, follows mouse raycast to ground plane"}, {"id": "gen_building_placement_3", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Foundation system: foundations snap to grid, walls snap to foundation edges, floors snap to wall tops, stairs connect floors vertically"}, {"id": "gen_building_placement_4", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Structural integrity: each piece has stability value (foundation 100%, decreasing with distance from ground), pieces below threshold collapse"}, {"id": "gen_building_placement_5", "t": "building_placement", "text": "[BUILDING_PLACEMENT] Building types: walls (1x3m), floors (4x4m), roofs (angled), doors (1x2.5m), windows (1x1m), stairs (1x3m at 45 degrees), pillars for support"}, {"id": "gen_save_systems_0", "t": "save_systems", "text": "[SAVE_SYSTEMS] Serialization: convert game state to JSON/binary, include player position/rotation/health/inventory, world state (destroyed objects, opened doors, NPC states)"}, {"id": "gen_save_systems_1", "t": "save_systems", "text": "[SAVE_SYSTEMS] Save file structure: header (version, timestamp, playtime), player data, world data, quest progress, settings. Version number for migration support"}, {"id": "gen_save_systems_2", "t": "save_systems", "text": "[SAVE_SYSTEMS] Auto-save: trigger on zone transitions, every N minutes, before boss fights. Show indicator icon. Keep 3 rotating auto-saves"}, {"id": "gen_save_systems_3", "t": "save_systems", "text": "[SAVE_SYSTEMS] Save slots: 3-10 manual slots, thumbnail screenshot, playtime display, character name/level, last save location name"}, {"id": "gen_save_systems_4", "t": "save_systems", "text": "[SAVE_SYSTEMS] Cloud saves: sync to server on save, conflict resolution (latest wins or prompt user), offline queue for later sync"}, {"id": "gen_save_systems_5", "t": "save_systems", "text": "[SAVE_SYSTEMS] Checkpoint system: invisible trigger volumes, respawn at last checkpoint on death, checkpoint saves subset of state (position, health, ammo)"}, {"id": "gen_UI_menus_0", "t": "UI_menus", "text": "[UI_MENUS] Main menu layout: title/logo centered top, menu items vertically stacked (New Game, Continue, Settings, Quit), animated background scene, fade transitions"}, {"id": "gen_UI_menus_1", "t": "UI_menus", "text": "[UI_MENUS] HUD elements: health bar (top-left, red fill), ammo counter (bottom-right, current/reserve), minimap (top-right, rotating), crosshair (center), compass (top-center)"}, {"id": "gen_UI_menus_2", "t": "UI_menus", "text": "[UI_MENUS] Pause menu: darken/blur game behind overlay, Resume/Settings/Save/Quit options, game time paused (timeScale=0), escape key toggle"}, {"id": "gen_UI_menus_3", "t": "UI_menus", "text": "[UI_MENUS] Settings menu: tabs (Video, Audio, Controls, Gameplay), resolution dropdown, fullscreen toggle, quality presets (Low/Med/High/Ultra), volume sliders, key rebinding"}, {"id": "gen_UI_menus_4", "t": "UI_menus", "text": "[UI_MENUS] Inventory UI: grid layout (8x4 slots), drag-and-drop items, tooltip on hover (name, stats, description), equipment slots (head/chest/legs/weapon/shield)"}, {"id": "gen_UI_menus_5", "t": "UI_menus", "text": "[UI_MENUS] Loading screen: progress bar or spinner, random gameplay tips, background art, minimum display time 2 seconds to prevent flash"}, {"id": "gen_UI_menus_6", "t": "UI_menus", "text": "[UI_MENUS] Dialogue UI: text box at screen bottom, character portrait left side, response options as clickable list, typewriter text effect 30 chars/sec"}, {"id": "gen_particle_effects_0", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Fire: emitter at base, particles rise (velocity.y = 2-5), orange->red->black color over lifetime, size shrinks, emission rate 50-200/sec, point light flicker"}, {"id": "gen_particle_effects_1", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Smoke: large soft particles, gray color with alpha fade, slow rise (velocity.y = 0.5-1), turbulence noise offset, billboard sprites, sort back-to-front"}, {"id": "gen_particle_effects_2", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Explosion: burst emission (200 particles in 0.1s), radial velocity (10-30 m/s), debris sub-emitter with gravity, shockwave ring mesh scale animation, screen shake"}, {"id": "gen_particle_effects_3", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Magic/energy: spiral motion (sin/cos on x/z), glow via additive blending, trail renderer following particles, color cycling, orbit around cast point"}, {"id": "gen_particle_effects_4", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Rain splash: spawn on raycast ground hit, tiny upward burst (5-10 particles), very short lifetime (0.1-0.2s), ripple ring mesh on water surfaces"}, {"id": "gen_particle_effects_5", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Dust/dirt: triggered by footsteps/impacts, small puff (10-20 particles), brown/tan color, gravity pulls down quickly, ground-hugging motion"}, {"id": "gen_particle_effects_6", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Muzzle flash: single-frame burst, bright yellow-white, point light flash (1 frame), sprite sheet animation 4 frames, camera-facing billboard"}, {"id": "gen_particle_effects_7", "t": "particle_effects", "text": "[PARTICLE_EFFECTS] Particle optimization: object pooling (pre-allocate 1000), LOD (reduce count at distance), GPU instancing, texture atlas for all particle types"}, {"id": "gen_destruction_physics_0", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Fracture pre-computation: Voronoi fracture mesh into 10-30 pieces offline, store as separate meshes, swap intact->fractured on damage threshold"}, {"id": "gen_destruction_physics_1", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Debris physics: each fragment gets rigidbody, initial velocity = explosion force / mass, angular velocity random, sleep after 3 seconds, despawn after 10s"}, {"id": "gen_destruction_physics_2", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Structural support: connectivity graph between pieces, removing support piece triggers cascade, check if remaining pieces still connected to ground"}, {"id": "gen_destruction_physics_3", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Damage model: health per destructible (wall 100HP, pillar 300HP), weapon damage values, AOE damage falloff (damage * (1 - dist/radius))"}, {"id": "gen_destruction_physics_4", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Visual effects: dust cloud particles on break, sparks for metal, wood splinters sub-emitter, crack decals before full destruction, sound cues per material"}, {"id": "gen_destruction_physics_5", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Performance: limit simultaneous destructions (max 3), LOD for distant debris (simplified collision), cleanup timer, don't simulate tiny fragments"}, {"id": "gen_destruction_physics_6", "t": "destruction_physics", "text": "[DESTRUCTION_PHYSICS] Material types: wood (splinters, low HP), concrete (chunks, medium HP), metal (dents before break, high HP), glass (shatter pattern, very low HP)"}, {"id": "gen_open_world_0", "t": "open_world", "text": "[OPEN_WORLD] Distant mountains: low-poly impostor meshes at 5-20km, billboards beyond 20km, height fog hides base transition, parallax scrolling for far background"}, {"id": "gen_open_world_1", "t": "open_world", "text": "[OPEN_WORLD] World boundaries: invisible walls with camera push-back, natural barriers (ocean, cliffs, storms), narrative barriers (character refuses), gradual damage zone"}, {"id": "gen_open_world_2", "t": "open_world", "text": "[OPEN_WORLD] LOD terrain: chunked heightmap (256x256 per chunk), 4-5 LOD levels, geomorphing between levels to prevent popping, distance-based chunk loading"}, {"id": "gen_open_world_3", "t": "open_world", "text": "[OPEN_WORLD] Skybox/horizon: HDRI skybox for distant detail, fog color matches horizon, atmospheric scattering shader, cloud layers at different altitudes"}, {"id": "gen_open_world_4", "t": "open_world", "text": "[OPEN_WORLD] Streaming: divide world into cells/chunks, load 3x3 grid around player, async loading in background thread, transition zones overlap for seamless"}, {"id": "gen_open_world_5", "t": "open_world", "text": "[OPEN_WORLD] Points of interest: visible landmarks from distance (towers, mountains, smoke), guide player exploration, density increases near critical path"}, {"id": "gen_open_world_6", "t": "open_world", "text": "[OPEN_WORLD] Scale tricks: distant objects slightly oversized (1.2-1.5x) to feel correct, atmospheric perspective (blue tint at distance), forced perspective for landmarks"}];
